  app.post("/api/subcontractor/:token/status", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;
      if (tokenRecord.status !== 'accepted') return res.status(400).json({ error: 'Must accept job first' });

      const { status, latitude, longitude, etaMinutes } = req.body;
      const validStatuses = ['en_route', 'arrived', 'working', 'done'];
      if (!validStatuses.includes(status)) return res.status(400).json({ error: 'Invalid status' });

      // Validate GPS coordinates when location is provided (action-triggering endpoint)
      if (latitude !== undefined && longitude !== undefined) {
        const validation = validateAustralianCoords(
          typeof latitude === 'string' ? parseFloat(latitude) : latitude,
          typeof longitude === 'string' ? parseFloat(longitude) : longitude
        );
        if (!validation.valid) {
          return res.status(400).json({ error: `Invalid coordinates: ${validation.reason}` });
        }
      }

      const eventTypeMap: Record<string, string> = {
        'en_route': 'SUBBIE_EN_ROUTE',
        'arrived': 'SUBBIE_ARRIVED',
        'working': 'SUBBIE_STARTED',
        'done': 'SUBBIE_FINISHED',
      };

      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: eventTypeMap[status],
        eventData: { status, ...(etaMinutes ? { etaMinutes: parseInt(etaMinutes) } : {}) },
        latitude: latitude || null,
        longitude: longitude || null,
      });

      if (status === 'en_route' && etaMinutes) {
        await storage.updateSubcontractorToken(tokenRecord.id, { etaMinutes: parseInt(etaMinutes) });
      }
      if (status === 'arrived' || status === 'working' || status === 'done') {
        await storage.updateSubcontractorToken(tokenRecord.id, { etaMinutes: null });
      }

      if (latitude && longitude) {
        await storage.createSubcontractorLocationPing({
          tokenId: tokenRecord.id,
          jobId: tokenRecord.jobId,
          latitude,
          longitude,
        });
      }

      res.json({ success: true, status });
    } catch (error: any) {
      console.error('Error updating subcontractor status:', error);
      res.status(500).json({ error: "Failed to update status" });
    }
  });

  app.post("/api/subcontractor/:token/notes", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;
      if (!(tokenRecord.permissions as string[])?.includes('add_notes')) return res.status(403).json({ error: 'No permission' });

      const { content } = req.body;
      if (!content?.trim()) return res.status(400).json({ error: 'Note content required' });

      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: 'SUBBIE_NOTE_ADDED',
        eventData: { content: content.trim(), author: tokenRecord.contactName || 'Subcontractor' },
      });

      res.json({ success: true });
    } catch (error: any) {
      console.error('Error adding subcontractor note:', error);
      res.status(500).json({ error: "Failed to add note" });
    }
  });

  app.post("/api/subcontractor/:token/photos", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;
      if (!(tokenRecord.permissions as string[])?.includes('add_photos')) return res.status(403).json({ error: 'No permission to add photos' });

      const { fileName, fileBase64, mimeType, category, caption } = req.body;
      if (!fileName || !fileBase64 || !mimeType) {
        return res.status(400).json({ error: 'fileName, fileBase64, and mimeType required' });
      }

      const fileBuffer = Buffer.from(fileBase64, 'base64');
      const { uploadJobPhoto } = await import('./photoService');
      const result = await uploadJobPhoto(tokenRecord.userId, tokenRecord.jobId, fileBuffer, {
        fileName,
        fileSize: fileBuffer.length,
        mimeType,
        category: category || 'general',
        caption: caption || `Photo by ${tokenRecord.contactName || 'Subcontractor'}`,
      });

      if (!result.success) {
        return res.status(500).json({ error: result.error });
      }

      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: 'SUBBIE_PHOTO_UPLOADED',
        eventData: { fileName, category: category || 'general', author: tokenRecord.contactName || 'Subcontractor' },
      });

      res.json({ success: true, photo: result });
    } catch (error: any) {
      console.error('Error uploading subcontractor photo:', error);
      res.status(500).json({ error: "Failed to upload photo" });
    }
  });

  app.post("/api/subcontractor/:token/location", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;

      const { latitude, longitude, accuracyMeters } = req.body;
      if (!latitude || !longitude) return res.status(400).json({ error: 'Location required' });

      // Validate GPS coordinates (action-triggering endpoint - reject invalid coords)
      const validation = validateAustralianCoords(
        typeof latitude === 'string' ? parseFloat(latitude) : latitude,
        typeof longitude === 'string' ? parseFloat(longitude) : longitude,
        typeof accuracyMeters === 'string' ? parseFloat(accuracyMeters) : accuracyMeters
      );
      if (!validation.valid) {
        return res.status(400).json({ error: `Invalid coordinates: ${validation.reason}` });
      }

      await storage.createSubcontractorLocationPing({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        latitude,
        longitude,
        accuracyMeters: accuracyMeters || null,
      });

      res.json({ success: true });
    } catch (error: any) {
      console.error('Error storing subcontractor location:', error);
      res.status(500).json({ error: "Failed to store location" });
    }
  });

  app.post("/api/subcontractor/:token/logout", async (req, res) => {
    try {
      const authHeader = req.headers.authorization;
      if (authHeader?.startsWith('Bearer ')) {
        await storage.deleteSubcontractorSession(authHeader.substring(7));
      }
      res.json({ success: true });
    } catch (error: any) {
      console.error('Error logging out subcontractor:', error);
      res.status(500).json({ error: "Failed to log out" });
    }
  });

  // ============================================================
  // MAGIC LINK FLOW (/m/:token) — premium name-gate + optional code
  // PII-free preview, name-confirmation gate, hashed 4-digit code,
  // 3-attempt auto-revoke. Lives alongside the legacy /s/:token flow.
  // ============================================================

  // In-memory rate limiter for /api/m/:token/verify. Per-token+IP key.
  // Allows 5 attempts per 5 minutes — combined with the SQL-enforced
  // 3-attempt-then-revoke this gives defence in depth against brute force.
  const magicLinkVerifyBuckets = new Map<string, { count: number; resetAt: number }>();
  function magicLinkVerifyAttempts(key: string): boolean {
    const now = Date.now();
    const WINDOW_MS = 5 * 60 * 1000;
    const MAX = 5;
    const bucket = magicLinkVerifyBuckets.get(key);
    if (!bucket || bucket.resetAt < now) {
      magicLinkVerifyBuckets.set(key, { count: 1, resetAt: now + WINDOW_MS });
      return true;
    }
    if (bucket.count >= MAX) return false;
    bucket.count += 1;
    return true;
  }

  // GET /api/m/:token/preview — returns minimal info for name-gate.
  // No customer name, no address, no job title. Just contractor business name
  // and the first character of the contact name (so the sub can identify
  // themselves without leaking their full name to whoever is holding the phone).
  app.get("/api/m/:token/preview", async (req, res) => {
    try {
      const tokenRecord = await storage.getSubcontractorTokenByToken(req.params.token);
      if (!tokenRecord) return res.status(404).json({ error: 'Link not found' });
      if (tokenRecord.revokedAt) return res.status(410).json({ error: 'This link has been revoked' });
      if (tokenRecord.expiresAt && new Date() > tokenRecord.expiresAt) {
        return res.status(410).json({ error: 'This link has expired' });
      }

      // Track open (best-effort, no failures bubble up)
      try {
        const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim()
          || req.socket.remoteAddress
          || null;
        await db.update(subcontractorTokens)
          .set({
            openCount: sql`COALESCE(${subcontractorTokens.openCount}, 0) + 1`,
            lastOpenedFromIp: ip,
            lastAccessedAt: new Date(),
          })
          .where(eq(subcontractorTokens.id, tokenRecord.id));
      } catch (e) {
        console.error('Failed to log magic link open:', e);
      }

      const businessSettings = await storage.getBusinessSettings(tokenRecord.userId);
      const businessName = businessSettings?.businessName || 'A contractor';
      // PII-FREE: only the first character of the contact name is exposed
      // pre-confirmation. The full first name is intentionally NOT returned —
      // a wrong-number recipient should not see "are you Jake?" before they
      // confirm. They see "are you J?" which is enough for legitimate
      // recipients to recognise themselves while preventing PII leakage.
      const contactNameFirstChar = (tokenRecord.contactName || '').trim().charAt(0).toUpperCase();

      // SECURITY: We intentionally DO NOT expose the recipient's first name
      // here, even when the token is auto-linked to an existing JR user.
      // Doing so would let anyone holding the token URL enumerate whether a
      // phone belongs to a JR user and learn that user's first name without
      // ever proving identity. The personalized "Welcome back, X" greeting
      // is shown only AFTER the recipient passes the code/session gate, via
      // the authenticated /api/m/:token/account-status endpoint.
      res.json({
        status: tokenRecord.status,
        revoked: !!tokenRecord.revokedAt,
        nameConfirmed: !!(tokenRecord as any).nameConfirmedAt,
        requiresCode: !!(tokenRecord as any).requireCode,
        contactNameFirstChar,
        business: {
          companyName: businessName,
        },
      });
    } catch (error: any) {
      console.error('Error fetching magic link preview:', error);
      res.status(500).json({ error: 'Failed to load link' });
    }
  });

  // POST /api/m/:token/confirm — name-gate response.
  // body: { confirm: true } → if no code required, returns sessionToken; else { requiresCode: true }
  // body: { confirm: false } → revokes the link and notifies the contractor.
  app.post("/api/m/:token/confirm", async (req, res) => {
    try {
      const { confirm } = req.body || {};
      const tokenRecord = await storage.getSubcontractorTokenByToken(req.params.token);
      if (!tokenRecord) return res.status(404).json({ error: 'Link not found' });
      if (tokenRecord.revokedAt) return res.status(410).json({ error: 'This link has been revoked' });
      if (tokenRecord.expiresAt && new Date() > tokenRecord.expiresAt) {
        return res.status(410).json({ error: 'This link has expired' });
      }

      if (confirm === false) {
        // Wrong number — revoke immediately and emit an event so the contractor sees it.
        await storage.revokeSubcontractorToken(tokenRecord.id);
        try {
          await db.update(subcontractorTokens)
            .set({ revokedReason: 'wrong_number_self_reported' })
            .where(eq(subcontractorTokens.id, tokenRecord.id));
        } catch (e) {
          console.error('Failed to set revoke reason:', e);
        }
        await storage.createSubcontractorEvent({
          tokenId: tokenRecord.id,
          jobId: tokenRecord.jobId,
          eventType: 'SUBBIE_WRONG_NUMBER',
          eventData: { reportedAt: new Date().toISOString() },
        });
        return res.json({ revoked: true });
      }

      if (confirm !== true) {
        return res.status(400).json({ error: 'confirm must be true or false' });
      }

      // Mark name as confirmed
      try {
        await db.update(subcontractorTokens)
          .set({ nameConfirmedAt: new Date() })
          .where(eq(subcontractorTokens.id, tokenRecord.id));
      } catch (e) {
        console.error('Failed to mark name confirmed:', e);
      }

      const requiresCode = !!(tokenRecord as any).requireCode;
      if (requiresCode) {
        return res.json({ requiresCode: true });
      }

      // No code required — issue a session immediately.
      const sessionToken = randomBytes(32).toString('hex');
      const expiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
      await storage.createSubcontractorSession(
        tokenRecord.id,
        sessionToken,
        tokenRecord.contactPhone || '',
        expiresAt
      );
      await storage.updateSubcontractorTokenAccess(tokenRecord.id);
      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: 'SUBBIE_NAME_CONFIRMED',
        eventData: {},
      });
      return res.json({ requiresCode: false, sessionToken, expiresAt: expiresAt.toISOString() });
    } catch (error: any) {
      console.error('Error confirming magic link:', error);
      res.status(500).json({ error: 'Confirmation failed' });
    }
  });

  // POST /api/m/:token/verify — verify the 4-digit code.
  // SECURITY:
  //   - Atomic SQL increment under WHERE code_attempts < 3 AND revoked_at IS NULL
  //     prevents TOCTOU brute-force when multiple parallel requests are sent.
  //   - Code expires after CODE_TTL_MS (default 30 minutes from issuance).
  //   - Rate-limited per token + IP via the in-memory map below.
  app.post("/api/m/:token/verify", async (req, res) => {
    try {
      const { code } = req.body || {};
      if (!code || typeof code !== 'string') {
        return res.status(400).json({ error: 'Code required' });
      }

      const ip = (req.headers['x-forwarded-for'] as string)?.split(',')[0]?.trim()
        || req.socket.remoteAddress
        || 'unknown';
      const rateKey = `${req.params.token}:${ip}`;
      if (!magicLinkVerifyAttempts(rateKey)) {
        return res.status(429).json({ error: 'Too many attempts. Try again in a moment.' });
      }

      const tokenRecord = await storage.getSubcontractorTokenByToken(req.params.token);
      if (!tokenRecord) return res.status(404).json({ error: 'Link not found' });
      if (tokenRecord.revokedAt) return res.status(410).json({ error: 'This link has been revoked' });
      if (tokenRecord.expiresAt && new Date() > tokenRecord.expiresAt) {
        return res.status(410).json({ error: 'This link has expired' });
      }

      const requiresCode = !!(tokenRecord as any).requireCode;
      const storedHash = (tokenRecord as any).codeHash as string | null;
      const codeIssuedAt = (tokenRecord as any).codeIssuedAt as Date | null;
      if (!requiresCode || !storedHash) {
        return res.status(400).json({ error: 'No code is required for this link' });
      }

      // Enforce code expiry — 30 minutes from issuance.
      // FAIL CLOSED: a missing codeIssuedAt is treated as expired so that a
      // bad data state can't leave codes valid forever.
      const CODE_TTL_MS = 30 * 60 * 1000;
      if (!codeIssuedAt || (Date.now() - new Date(codeIssuedAt).getTime()) > CODE_TTL_MS) {
        return res.status(410).json({ error: 'This code has expired. Ask the contractor to send a fresh link.' });
      }

      const submittedHash = createHash('sha256').update(String(code).trim()).digest('hex');
      const isMatch = submittedHash === storedHash;

      if (!isMatch) {
        // Atomic increment: only if attempts < 3 and not revoked.
        // RETURNING gives us the post-update value so we know if this was the
        // attempt that maxed out.
        const updated = await db.update(subcontractorTokens)
          .set({ codeAttempts: sql`COALESCE(${subcontractorTokens.codeAttempts}, 0) + 1` })
          .where(and(
            eq(subcontractorTokens.id, tokenRecord.id),
            isNull(subcontractorTokens.revokedAt),
            lt(subcontractorTokens.codeAttempts, 3),
          ))
          .returning({ codeAttempts: subcontractorTokens.codeAttempts });

        if (updated.length === 0) {
          // Either already revoked or already maxed out by a parallel request.
          if (!tokenRecord.revokedAt) {
            await db.update(subcontractorTokens)
              .set({ revokedAt: new Date(), revokedReason: 'too_many_code_attempts' })
              .where(and(
                eq(subcontractorTokens.id, tokenRecord.id),
                isNull(subcontractorTokens.revokedAt),
              ));
            await storage.createSubcontractorEvent({
              tokenId: tokenRecord.id,
              jobId: tokenRecord.jobId,
              eventType: 'SUBBIE_LINK_AUTO_REVOKED',
              eventData: { reason: 'too_many_code_attempts' },
            });
          }
          return res.status(429).json({ error: 'Too many attempts. The contractor has been notified.', autoRevoked: true });
        }

        const newAttempts = updated[0].codeAttempts ?? 0;
        if (newAttempts >= 3) {
          // We just hit the cap with this request — atomically revoke.
          await db.update(subcontractorTokens)
            .set({ revokedAt: new Date(), revokedReason: 'too_many_code_attempts' })
            .where(and(
              eq(subcontractorTokens.id, tokenRecord.id),
              isNull(subcontractorTokens.revokedAt),
            ));
          await storage.createSubcontractorEvent({
            tokenId: tokenRecord.id,
            jobId: tokenRecord.jobId,
            eventType: 'SUBBIE_LINK_AUTO_REVOKED',
            eventData: { reason: 'too_many_code_attempts' },
          });
          return res.status(429).json({ error: 'Too many attempts. The contractor has been notified.', autoRevoked: true });
        }
        return res.status(400).json({ error: 'Wrong code', attemptsRemaining: 3 - newAttempts });
      }

      // Code accepted — issue a session and emit event.
      const sessionToken = randomBytes(32).toString('hex');
      const sessionExpiresAt = new Date(Date.now() + 24 * 60 * 60 * 1000);
      await storage.createSubcontractorSession(
        tokenRecord.id,
        sessionToken,
        tokenRecord.contactPhone || '',
        sessionExpiresAt
      );
      await storage.updateSubcontractorTokenAccess(tokenRecord.id);
      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: 'SUBBIE_VERIFIED',
        eventData: { method: 'magic_link_code' },
      });

      res.json({ sessionToken, expiresAt: sessionExpiresAt.toISOString() });
    } catch (error: any) {
      console.error('Error verifying magic link code:', error);
      res.status(500).json({ error: 'Verification failed' });
    }
  });

  // T008: GET /api/m/:token/account-status — does this recipient already
  // have a JR account, or is the token already linked to one?
  // Requires a valid sub session — only callable from inside the unlocked
  // sub web view, so we know the recipient has confirmed identity.
  app.get("/api/m/:token/account-status", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;

      // Already linked on this token
      const linkedUserId = (tokenRecord as any).recipientUserId as string | null;
      if (linkedUserId) {
        const user = await storage.getUserById(linkedUserId);
        return res.json({
          hasAccount: true,
          alreadyLinked: true,
          firstName: user?.firstName || null,
        });
      }

      // Not linked on this token — see if their phone matches an existing user
      const normalized = normalizeAuPhone(tokenRecord.contactPhone);
      if (!normalized) {
        return res.json({ hasAccount: false, alreadyLinked: false });
      }
      const existing = await storage.getUserByPhoneNormalized(normalized);
      if (existing) {
        return res.json({
          hasAccount: true,
          alreadyLinked: false,
          firstName: existing.firstName || null,
        });
      }
      return res.json({ hasAccount: false, alreadyLinked: false });
    } catch (error: any) {
      console.error('Error checking magic-link account status:', error);
      res.status(500).json({ error: 'Status check failed' });
    }
  });

  // T008: POST /api/m/:token/save-account — link or create a sub account.
  // Requires a valid sub session.
  // Body: { firstName?: string, lastName?: string, tradeType?: string }
  // - If recipient phone matches an existing user → link recipientUserId,
  //   ignore firstName/lastName/tradeType (existing profile wins).
  // - If no existing user → firstName REQUIRED, create new free-tier user
  //   with phone/phoneNormalized populated, link recipientUserId.
  // Also retroactively links every other unrevoked token sent to the same
  // phone, so future links from any contractor skip the name-gate.
  app.post("/api/m/:token/save-account", async (req, res) => {
    try {
      const v = await validateSubSession(req);
      if (!v.ok) return res.status(v.status).json(v.body);
      const { tokenRecord } = v;

      const normalized = normalizeAuPhone(tokenRecord.contactPhone);
      if (!normalized) {
        return res.status(400).json({ error: 'This link has no valid phone number to attach.' });
      }

      let user = await storage.getUserByPhoneNormalized(normalized);
      let mode: 'linked' | 'created' = 'linked';

      if (!user) {
        const { firstName, lastName, tradeType } = req.body || {};
        const trimmedFirst = String(firstName || '').trim();
        if (!trimmedFirst) {
          return res.status(400).json({ error: 'First name is required to create your account.' });
        }
        // Generate a placeholder username from the phone (no email required —
        // sub accounts can be email-less, they sign in via magic links).
        const usernameSeed = `sub_${normalized.replace(/\D/g, '')}_${Date.now().toString(36)}`;
        try {
          user = await storage.createUser({
            username: usernameSeed,
            firstName: trimmedFirst,
            lastName: String(lastName || '').trim() || null,
            phone: tokenRecord.contactPhone || normalized,
            phoneNormalized: normalized,
            tradeType: tradeType ? String(tradeType).trim() : null,
            subscriptionTier: 'free',
            isActive: true,
          } as any);
          mode = 'created';
        } catch (e: any) {
          // Race: someone else created the same phone account in parallel.
          // Fall back to lookup.
          user = await storage.getUserByPhoneNormalized(normalized);
          if (!user) {
            console.error('Failed to create sub account:', e);
            return res.status(500).json({ error: 'Could not create your account. Please try again.' });
          }
        }
      }

      // Link THIS token to the user (and mark name confirmed in case it wasn't).
      await storage.setSubcontractorTokenRecipient(tokenRecord.id, user.id, /*alsoMarkNameConfirmed*/ true);

      // Retroactively link every other unrevoked, unexpired token sent to the
      // same phone so future opens skip the name-gate.
      try {
        await db.update(subcontractorTokens)
          .set({ recipientUserId: user.id, nameConfirmedAt: sql`COALESCE(${subcontractorTokens.nameConfirmedAt}, NOW())` })
          .where(and(
            eq(subcontractorTokens.contactPhone, tokenRecord.contactPhone || ''),
            isNull(subcontractorTokens.recipientUserId),
            isNull(subcontractorTokens.revokedAt),
          ));
      } catch (e) {
        console.error('Failed retroactive link of sibling tokens:', e);
      }

      await storage.createSubcontractorEvent({
        tokenId: tokenRecord.id,
        jobId: tokenRecord.jobId,
        eventType: mode === 'created' ? 'SUBBIE_ACCOUNT_CREATED' : 'SUBBIE_ACCOUNT_LINKED',
        eventData: { userId: user.id },
      });

      return res.json({
        success: true,
        mode,
        user: {
          id: user.id,
          firstName: user.firstName,
          lastName: user.lastName,
          tradeType: user.tradeType,
        },
      });
    } catch (error: any) {
      console.error('Error saving sub account:', error);
      res.status(500).json({ error: 'Save failed' });
    }
  });

  // POST /api/m/:token/revoke — sub voluntarily revokes their own access.
  app.post("/api/m/:token/revoke", async (req, res) => {
    try {
      const tokenRecord = await storage.getSubcontractorTokenByToken(req.params.token);
      if (!tokenRecord) return res.status(404).json({ error: 'Link not found' });
      if (!tokenRecord.revokedAt) {
        await storage.revokeSubcontractorToken(tokenRecord.id);
        try {
          await db.update(subcontractorTokens)
            .set({ revokedReason: 'sub_self_revoked' })
            .where(eq(subcontractorTokens.id, tokenRecord.id));
        } catch (e) {
          console.error('Failed to set revoke reason:', e);
        }
        await storage.createSubcontractorEvent({
          tokenId: tokenRecord.id,
          jobId: tokenRecord.jobId,
          eventType: 'SUBBIE_LINK_REVOKED',
          eventData: { revokedBy: 'sub' },
        });
      }
      res.json({ success: true });
    } catch (error: any) {
      console.error('Error revoking magic link:', error);
      res.status(500).json({ error: 'Revoke failed' });
    }
  });

  // PUBLIC: Unified document view endpoint for client portal
  app.get("/api/public/document/:type/:token", portalIpRateLimiterMiddleware, async (req, res) => {
    try {
      const { type, token } = req.params;
      
      if (type === 'quote') {
        const quote = await storage.getQuoteByToken(token);
        if (!quote) {
          return res.status(404).json({ error: 'Quote not found' });
        }
        
        // Log quote view for activity tracking
        await logTeamActivity({
          businessOwnerId: quote.userId,
          activityType: 'quote_viewed',
          entityType: 'quote',
          entityId: quote.id,
          entityTitle: quote.title || quote.number,
          description: 'Quote viewed in client portal'
        });
        
        const client = await storage.getClientById(quote.clientId);
        const settings = await storage.getBusinessSettingsByUserId(quote.userId);
        const lineItems = await storage.getQuoteLineItems(quote.id);
        let job = null;
        if (quote.jobId) {
          job = await storage.getJob(quote.jobId, quote.userId);
        }
        
        // Get signature - from quote record or fall back to digital_signatures table
        let signatureData = quote.acceptanceSignatureData || null;
        if (!signatureData && quote.status === 'accepted') {
          try {
            const sigs = await db.select().from(digitalSignatures)
              .where(eq(digitalSignatures.quoteId, quote.id))
              .orderBy(desc(digitalSignatures.signedAt))
              .limit(1);
            if (sigs.length > 0 && sigs[0].signatureData) {
              signatureData = sigs[0].signatureData;
            }
          } catch (e) {
            // ignore - signature is optional
          }
        }
        
        return res.json({
          type: 'quote',
          id: quote.id,
          number: quote.number,
          title: quote.title,
          description: quote.description,
          status: quote.status,
          subtotal: quote.subtotal,
          gstAmount: quote.gstAmount,
          total: quote.total,
          createdAt: quote.createdAt,
          validUntil: quote.validUntil,
          acceptedAt: quote.acceptedAt,
          acceptedBy: quote.acceptedBy,
          acceptanceSignatureData: signatureData,
          depositRequired: quote.depositRequired,
          depositAmount: quote.depositAmount,
          depositPaid: quote.depositPaid,
          lineItems: lineItems.map(item => ({
            id: item.id,
            description: item.description,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            total: item.total
          })),
          client: {
            name: client?.name,
            email: client?.email,
            phone: client?.phone,
            address: client?.address
          },
          business: {
            name: settings?.businessName,
            email: settings?.email,
            phone: settings?.phone,
            address: settings?.address,
            abn: settings?.abn,
            logoUrl: settings?.logoUrl
          },
          job: job ? { title: job.title, address: job.address } : null
        });
      }
      
      if (type === 'invoice') {
        const invoice = await storage.getInvoiceByPaymentToken(token);
        if (!invoice) {
          return res.status(404).json({ error: 'Invoice not found' });
        }
        
        // Log invoice view for activity tracking
        await logTeamActivity({
          businessOwnerId: invoice.userId,
          activityType: 'invoice_viewed',
          entityType: 'invoice',
          entityId: invoice.id,
          entityTitle: invoice.number,
          description: 'Invoice viewed in client portal'
        });
        
        const client = await storage.getClientById(invoice.clientId);
        const settings = await storage.getBusinessSettingsByUserId(invoice.userId);
        const allLineItems = await storage.getInvoiceLineItems(invoice.id);
        const lineItems = allLineItems.filter(item => item.sourceType !== 'labour');
        let job = null;
        if (invoice.jobId) {
          job = await storage.getJob(invoice.jobId, invoice.userId);
        }
        
        return res.json({
          type: 'invoice',
          id: invoice.id,
          number: invoice.number,
          title: invoice.title,
          description: invoice.description,
          status: invoice.status,
          subtotal: invoice.subtotal,
          gstAmount: invoice.gstAmount,
          total: invoice.total,
          createdAt: invoice.createdAt,
          dueDate: invoice.dueDate,
          paidAt: invoice.paidAt,
          allowOnlinePayment: invoice.allowOnlinePayment,
          stripePaymentLink: invoice.stripePaymentLink,
          depositRequired: invoice.depositRequired || false,
          depositPercent: invoice.depositPercent,
          depositAmount: invoice.depositAmount,
          depositPaid: invoice.depositPaid || false,
          depositPaidAt: invoice.depositPaidAt,
          amountPaid: invoice.amountPaid,
          lineItems: lineItems.map(item => ({
            id: item.id,
            description: item.description,
            quantity: item.quantity,
            unitPrice: item.unitPrice,
            total: item.total
          })),
          client: {
            name: client?.name,
            email: client?.email,
            phone: client?.phone,
            address: client?.address
          },
          business: {
            name: settings?.businessName,
            email: settings?.email,
            phone: settings?.phone,
            address: settings?.address,
            abn: settings?.abn,
            logoUrl: settings?.logoUrl
          },
          job: job ? { title: job.title, address: job.address } : null
        });
      }
      
      if (type === 'receipt') {
        let receipt = await storage.getReceiptByViewToken(token);
        if (!receipt) {
          try {
            receipt = await storage.getReceiptById(token) as any;
          } catch (e) {}
        }
        if (!receipt) {
          return res.status(404).json({ error: 'Receipt not found' });
        }
        
        const client = receipt.clientId ? await storage.getClientById(receipt.clientId) : null;
        const settings = await storage.getBusinessSettingsByUserId(receipt.userId);
        
        return res.json({
          type: 'receipt',
          id: receipt.id,
          number: receipt.receiptNumber,
          title: 'Payment Receipt',
          description: receipt.description,
          status: 'paid',
          subtotal: receipt.subtotal,
          gstAmount: receipt.gstAmount,
          total: receipt.amount,
          createdAt: receipt.createdAt,
          paidAt: receipt.paidAt,
          lineItems: [],
          client: {
            name: client?.name,
            email: client?.email,
            phone: client?.phone,
            address: client?.address
          },
          business: {
            name: settings?.businessName,
            email: settings?.email,
            phone: settings?.phone,
            address: settings?.address,
            abn: settings?.abn,
            logoUrl: settings?.logoUrl
          },
          job: null
        });
      }
      
      return res.status(400).json({ error: 'Invalid document type' });
    } catch (error: any) {
      console.error('Error fetching public document:', error);
      res.status(500).json({ error: 'Failed to load document' });
    }
  });

  // PUBLIC: Accept a quote
  app.post("/api/public/quote/:token/accept", buildQuoteAcceptHandler({
    getQuoteByToken: (token) => storage.getQuoteByToken(token),
    updateQuote: (quoteId, userId, data) => storage.updateQuote(quoteId, userId, data as any),
    notifyAccepted: async (userId, quote, acceptedBy) => {
      await notifyQuoteAcceptedDB(storage, userId, quote, acceptedBy);
      await notifyQuoteAccepted(userId, (quote as any).number, quote.id, acceptedBy);
    },
    autoCreateJob: (quote, name) => autoCreateJobFromAcceptedQuote(quote, name),
    broadcastUpdate: (quoteId, userId, jobId) => {
      const wss = (global as any).__wss;
      if (!wss) return;
      const message = JSON.stringify({ type: 'quote_update', data: { quoteId, status: 'accepted', jobId } });
      wss.clients?.forEach((client: any) => {
        if (client.userId === userId && client.readyState === 1) client.send(message);
      });
    },
    getClientIp: (req: any) => {
      const raw = req.headers?.['x-forwarded-for'] || req.socket?.remoteAddress || 'unknown';
      return typeof raw === 'string' ? raw : raw[0];
    },
  }));

