  // ===== SUBSCRIPTION API ENDPOINTS (Cross-Platform Sync) =====

  // GET /api/subscription/status - Returns current subscription status for authenticated user
  app.get("/api/subscription/status", requireAuth, async (req: any, res) => {
    try {
      const { getSubscriptionStatus, getPaymentMethodDetails } = await import('./billingService');
      const { IS_BETA } = await import('./freemiumService');
      const userId = req.userId!;
      
      const status = await getSubscriptionStatus(userId);
      const paymentMethod = await getPaymentMethodDetails(userId);
      const user = await storage.getUser(userId);
      const businessSettings = await storage.getBusinessSettings(userId);
      const aiReceptionistConfig = await storage.getAiReceptionistConfig(userId);
      
      // Get actual team member count for billing purposes
      // Count includes team members only (owner is included in base plan)
      // Check if user is a team member first - if so, use owner's ID for team count
      const teamMembership = await storage.getTeamMembershipByMemberId(userId);
      const businessOwnerId = teamMembership?.businessOwnerId || userId;
      const teamMembers = await storage.getTeamMembers(businessOwnerId);
      // Filter for accepted team members only (not pending invites) for billing purposes
      const activeTeamMembers = teamMembers.filter(m => m.inviteStatus === 'accepted');
      const teamMemberCount = activeTeamMembers.length;
      // Total billable users = owner (1) + team members
      const totalBillableUsers = 1 + teamMemberCount;
      
      // Determine upgrade/downgrade eligibility
      const canUpgrade = status.tier === 'free' || status.tier === 'trial' || status.tier === 'pro' || status.tier === 'team';
      const canDowngrade = status.tier === 'team' || status.tier === 'business' || status.tier === 'pro';
      
      res.json({
        tier: status.tier,
        status: status.status,
        isTrial: status.isTrial || false,
        daysRemaining: status.daysRemaining ?? null,
        trialEndsAt: status.trialEndsAt || user?.trialEndsAt || null,
        nextBillingDate: status.currentPeriodEnd || null,
        cancelAtPeriodEnd: status.cancelAtPeriodEnd || false,
        subscriptionSource: user?.subscriptionSource || null,
        stripeSubscriptionId: status.stripeSubscriptionId || null,
        paymentMethod: paymentMethod.success ? {
          last4: paymentMethod.last4,
          brand: paymentMethod.brand,
        } : null,
        seats: (status.tier === 'team' || status.tier === 'business') ? status.seatCount : undefined,
        teamMemberCount,
        totalBillableUsers,
        isBeta: IS_BETA,
        betaUser: user?.betaUser || false,
        betaLifetimeAccess: user?.betaLifetimeAccess || false,
        betaCohortNumber: user?.betaCohortNumber || null,
        canUpgrade,
        canDowngrade,
        addons: {
          dedicatedNumber: businessSettings?.dedicatedPhoneNumber || null,
          smsMode: businessSettings?.smsMode || 'standard',
          aiReceptionistEnabled: businessSettings?.aiReceptionistEnabled || false,
          aiReceptionistMode: businessSettings?.aiReceptionistMode || 'off',
          aiReceptionistApprovalStatus: aiReceptionistConfig?.approvalStatus || 'none',
        },
      });
    } catch (error: any) {
      console.error('Error getting subscription status:', error);
      res.status(500).json({ error: error.message || 'Failed to get subscription status' });
    }
  });

  // POST /api/subscription/reconcile - Self-healing sync after returning from
  // Stripe checkout. The subscription webhook can be delayed or (for new trials)
  // not delivered, so the user can land back on the app still showing "Free".
  // This pulls the live subscription straight from Stripe by customer id, saves
  // its id, then lets getSubscriptionStatus persist the correct tier.
  app.post("/api/subscription/reconcile", requireAuth, ownerOnly(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { getUncachableStripeClient } = await import('./stripeClient');
      const { getSubscriptionStatus } = await import('./billingService');
      const stripe = await getUncachableStripeClient();
      const businessSettings = await storage.getBusinessSettings(userId);
      const customerId = businessSettings?.stripeCustomerId;

      let reconciled = false;
      if (stripe && customerId) {
        const subs = await stripe.subscriptions.list({ customer: customerId, status: 'all', limit: 10 });
        // Most recent first so multi-subscription histories pick the latest.
        const sorted = [...subs.data].sort((a: any, b: any) => (b.created || 0) - (a.created || 0));
        const live = sorted.find((s: any) => s.status === 'trialing' || s.status === 'active')
          || sorted.find((s: any) => s.status === 'past_due');
        if (live && businessSettings?.stripeSubscriptionId !== live.id) {
          await storage.updateBusinessSettings(userId, {
            stripeSubscriptionId: live.id,
            subscriptionStatus: live.status,
          } as any);
          reconciled = true;
        }
      }

      // getSubscriptionStatus reads the now-saved subscription id and persists
      // the live tier (e.g. team/business) back onto the user record.
      const status = await getSubscriptionStatus(userId);
      res.json({ tier: status.tier, status: status.status, reconciled });
    } catch (error: any) {
      console.error('Error reconciling subscription:', error);
      res.status(500).json({ error: error.message || 'Failed to reconcile subscription' });
    }
  });

  // POST /api/subscription/create-checkout - Creates Stripe checkout session with trial
  // During beta: Skip Stripe and grant free access directly
  app.post("/api/subscription/create-checkout", requireAuth, async (req: any, res) => {
    try {
      const { IS_BETA } = await import('./freemiumService');
      const userId = req.userId!;
      const { tier, seats } = req.body;
      
      // Validate tier
      if (!tier || !['pro', 'team', 'business'].includes(tier)) {
        return res.status(400).json({ error: 'Invalid tier. Must be "pro", "team", or "business"' });
      }
      
      const user = await storage.getUser(userId);
      if (!user?.email) {
        return res.status(400).json({ error: 'User email is required for checkout' });
      }
      
      // BETA MODE: Skip Stripe, grant free access immediately
      if (IS_BETA) {
        // Update user subscription tier directly (no Stripe)
        const subscriptionTier = tier as 'pro' | 'team' | 'business';
        await storage.updateUser(userId, { 
          subscriptionTier,
          betaUser: true,
          // Set trial end date far in future for beta users
          trialEndsAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7-day trial
        });
        
        if (subscriptionTier === 'team' || subscriptionTier === 'business') {
          const bs = await storage.getBusinessSettings(userId);
          if (bs && (!bs.teamSize || bs.teamSize === 'solo')) {
            await storage.updateBusinessSettings(userId, { teamSize: 'small' });
          }
        }
        
        console.log(`[BETA] Granted ${tier} access to user ${userId} without payment`);
        
        // Return success without Stripe URL - frontend will handle this
        return res.json({ 
          success: true, 
          betaAccess: true,
          tier: subscriptionTier,
          message: `${tier.charAt(0).toUpperCase() + tier.slice(1)} access granted - free during beta!`
        });
      }
      
      // PRODUCTION MODE: Use Stripe checkout
      const {
        createSubscriptionCheckout,
        createTeamSubscriptionCheckout,
        createBusinessSubscriptionCheckout,
      } = await import('./billingService');
      
      // Get base URL for success/cancel redirects
      const protocol = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers.host;
      const baseUrl = `${protocol}://${host}`;
      
      const successUrl = `${baseUrl}/settings?tab=billing&success=true`;
      const cancelUrl = `${baseUrl}/settings?tab=billing&canceled=true`;

      let result;
      if (tier === 'business') {
        result = await createBusinessSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      } else if (tier === 'team') {
        result = await createTeamSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      } else {
        result = await createSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      }
      
      if (!result.success) {
        return res.status(400).json({ error: result.error });
      }
      
      res.json({ url: result.sessionUrl });
    } catch (error: any) {
      console.error('Error creating checkout session:', error);
      res.status(500).json({ error: error.message || 'Failed to create checkout session' });
    }
  });

  // POST /api/subscription/email-payment-link - Creates a Stripe checkout
  // session and emails it to the user. Used by the Android app where
  // Google Play billing isn't wired up yet — gives the user a clean way to
  // upgrade by tapping the link in their email on a desktop browser.
  app.post("/api/subscription/email-payment-link", requireAuth, ownerOnly(), async (req: any, res) => {
    try {
      const { IS_BETA } = await import('./freemiumService');
      const userId = req.userId!;
      const { tier, seats } = req.body;

      // All three tiers are now self-serve via Stripe checkout
      // (matches Apple IAP — Pro $49.99 / Team $99.99 / Business $199.99 flat).
      if (!tier || !['pro', 'team', 'business'].includes(tier)) {
        return res.status(400).json({
          error: 'Invalid tier. Must be "pro", "team", or "business".',
        });
      }

      // Per-user cooldown to prevent accidental double-taps and basic abuse.
      const lastSent = emailPaymentLinkCooldown.get(userId);
      if (lastSent && Date.now() - lastSent < EMAIL_PAYMENT_LINK_COOLDOWN_MS) {
        const waitSec = Math.ceil((EMAIL_PAYMENT_LINK_COOLDOWN_MS - (Date.now() - lastSent)) / 1000);
        return res.status(429).json({
          error: `Please wait ${waitSec}s before requesting another payment link.`,
        });
      }

      const user = await storage.getUser(userId);
      if (!user?.email) {
        return res.status(400).json({ error: 'User email is required for checkout' });
      }

      // BETA: short-circuit and grant directly so user doesn't need to pay.
      if (IS_BETA) {
        const subscriptionTier = tier as 'pro' | 'team' | 'business';
        await storage.updateUser(userId, {
          subscriptionTier,
          betaUser: true,
          trialEndsAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000),
        });
        if (subscriptionTier === 'team' || subscriptionTier === 'business') {
          const bs = await storage.getBusinessSettings(userId);
          if (bs && (!bs.teamSize || bs.teamSize === 'solo')) {
            await storage.updateBusinessSettings(userId, { teamSize: 'small' });
          }
        }
        emailPaymentLinkCooldown.set(userId, Date.now());
        return res.json({
          success: true,
          betaAccess: true,
          message: `${tier.charAt(0).toUpperCase() + tier.slice(1)} access granted free during beta — no payment needed.`,
        });
      }

      const {
        createSubscriptionCheckout,
        createTeamSubscriptionCheckout,
        createBusinessSubscriptionCheckout,
      } = await import('./billingService');
      const { getProductionBaseUrl } = await import('./urlHelper');
      // Use the canonical app URL rather than trusting Host/X-Forwarded-Proto
      // headers — these are emailed links and host-header spoofing could
      // otherwise redirect the user post-checkout to an attacker domain.
      const baseUrl = getProductionBaseUrl();
      const successUrl = `${baseUrl}/settings?tab=billing&success=true`;
      const cancelUrl = `${baseUrl}/settings?tab=billing&canceled=true`;

      let result;
      if (tier === 'business') {
        result = await createBusinessSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      } else if (tier === 'team') {
        result = await createTeamSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      } else {
        result = await createSubscriptionCheckout(userId, user.email, successUrl, cancelUrl);
      }

      if (!result.success || !result.sessionUrl) {
        return res.status(400).json({ error: result.error || 'Failed to create checkout session' });
      }

      // Email the link to the user.
      try {
        const { sendSystemEmail } = await import('./emailService');
        const tierLabel = tier.charAt(0).toUpperCase() + tier.slice(1);
        const firstName = user.firstName || 'there';
        await sendSystemEmail({
          to: user.email,
          subject: `Your JobRunner ${tierLabel} upgrade link`,
          html: `
            <div style="font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif; max-width: 560px; margin: 0 auto; padding: 24px; color: #111;">
              <h2 style="margin: 0 0 16px 0;">G'day ${firstName},</h2>
              <p style="font-size: 16px; line-height: 1.5;">Here's your secure link to upgrade JobRunner to the <strong>${tierLabel}</strong> plan. Open it on any device to finish payment.</p>
              <p style="margin: 32px 0; text-align: center;">
                <a href="${result.sessionUrl}" style="background: #f97316; color: white; padding: 14px 28px; border-radius: 8px; text-decoration: none; font-weight: 600; display: inline-block;">Continue to checkout</a>
              </p>
              <p style="font-size: 13px; color: #666; line-height: 1.5;">This link expires in 24 hours. If you didn't request this, ignore this email — nothing will be charged.</p>
              <p style="font-size: 13px; color: #666; word-break: break-all;">Or copy this URL: ${result.sessionUrl}</p>
            </div>
          `,
          text: `G'day ${firstName},\n\nHere's your link to upgrade JobRunner to the ${tierLabel} plan:\n${result.sessionUrl}\n\nThis link expires in 24 hours.`,
        });
      } catch (emailErr) {
        console.error('[email-payment-link] Failed to send email:', emailErr);
        return res.status(500).json({ error: 'Created checkout but failed to send email. Please try again.' });
      }

      res.json({
        success: true,
        message: `We've emailed an upgrade link to ${user.email}. Check your inbox to finish.`,
      });
    } catch (error: any) {
      console.error('Error creating email payment link:', error);
      res.status(500).json({ error: error.message || 'Failed to create payment link' });
    }
  });

  // POST /api/subscription/ai-receptionist-checkout - Creates Stripe checkout for AI Receptionist add-on
  app.post("/api/subscription/ai-receptionist-checkout", requireAuth, requirePaidTier(), ownerOnly(), async (req: any, res) => {
    try {
      const { IS_BETA } = await import('./freemiumService');
      const userId = req.userId!;

      const user = await storage.getUser(userId);
      if (!user?.email) {
        return res.status(400).json({ error: 'User email is required for checkout' });
      }

      const existingConfigs = await storage.getAiReceptionistConfigsByUser(userId);
      const activeConfigs = existingConfigs.filter(c => c.approvalStatus === 'approved' || c.approvalStatus === 'active' || c.enabled);
      const pendingConfigs = existingConfigs.filter(c => c.approvalStatus === 'pending_approval' || c.approvalStatus === 'provisioning');
      if (pendingConfigs.length > 0) {
        return res.status(400).json({ error: 'An AI Receptionist number is already being set up or pending approval.' });
      }
      const MAX_NUMBERS = 5;
      if (activeConfigs.length >= MAX_NUMBERS) {
        return res.status(400).json({ error: `Maximum of ${MAX_NUMBERS} AI Receptionist numbers allowed per business.` });
      }

      const businessSettings = await storage.getBusinessSettings(userId);
      const dedicatedNumber = businessSettings?.dedicatedPhoneNumber;
      if (!dedicatedNumber) {
        return res.status(400).json({
          error: 'You need a dedicated phone number first. Purchase one from the Phone Numbers screen before setting up AI Receptionist.',
          needsDedicatedNumber: true,
          redirectTo: '/phone-numbers',
        });
      }

      const { isSharedPlatformNumber } = await import('./phoneNumberUtils');
      if (isSharedPlatformNumber(dedicatedNumber)) {
        return res.status(400).json({
          error: 'AI Receptionist requires a dedicated number. The shared platform number cannot be used. Please purchase your own number first.',
          needsDedicatedNumber: true,
          redirectTo: '/phone-numbers',
        });
      }

      // BETA MODE: Skip Stripe, trigger provisioning directly
      if (IS_BETA) {
        console.log(`[BETA] Triggering AI Receptionist provisioning for user ${userId} without payment`);

        if (existingConfigs.length === 0) {
          await storage.createAiReceptionistConfig({
            userId,
            enabled: false,
            mode: 'always_on_message',
            voiceName: 'Jess',
            approvalStatus: 'provisioning',
          });
        } else {
          await storage.updateAiReceptionistConfig(userId, {
            approvalStatus: 'provisioning',
            provisioningError: null,
          });
        }

        const { provisionAiReceptionist } = await import('./aiReceptionistProvisioning');
        provisionAiReceptionist(userId, dedicatedNumber).catch(err => {
          console.error('[BETA AI Receptionist] Provisioning failed:', err);
        });

        return res.json({
          success: true,
          betaAccess: true,
          provisioning: true,
          message: 'AI Receptionist setup started - free during beta!'
        });
      }

      // PRODUCTION MODE: Check plan tier before allowing add-on purchase
      const tier = user.subscriptionTier || 'free';
      const hasLifetimeAccess = user.betaLifetimeAccess === true;
      if (tier === 'free' && !hasLifetimeAccess) {
        return res.status(403).json({
          error: 'Pro plan or higher required for AI Receptionist',
          upgradeRequired: true,
          requiredTier: 'pro',
        });
      }

      const { createAiReceptionistCheckout } = await import('./billingService');
      const protocol = req.headers['x-forwarded-proto'] || 'https';
      const host = req.headers.host;
      const baseUrl = `${protocol}://${host}`;

      const result = await createAiReceptionistCheckout(
        userId,
        user.email,
        `${baseUrl}/ai-receptionist?provisioning=true`,
        `${baseUrl}/settings?tab=billing&canceled=true`,
        businessSettings?.businessName || undefined,
      );

      if (!result.success) {
        return res.status(400).json({ error: result.error });
      }

      res.json({ url: result.sessionUrl });
    } catch (error: any) {
      console.error('Error creating AI Receptionist checkout:', error);
      res.status(500).json({ error: error.message || 'Failed to create checkout session' });
    }
  });

