  app.post("/api/subscription/verify-apple-receipt", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { receiptData, productId } = req.body;

      if (!receiptData || !productId) {
        return res.status(400).json({ success: false, message: 'Receipt data and product ID are required' });
      }

      const tierMap: Record<string, string> = {
        'com.jobrunner.pro.monthly': 'pro',
        'com.jobrunner.team.monthly': 'team',
        'com.jobrunner.business.monthly': 'business',
      };

      const newTier = tierMap[productId];
      if (!newTier) {
        return res.status(400).json({ success: false, message: 'Invalid product ID' });
      }

      const verifyUrl = process.env.NODE_ENV === 'production'
        ? 'https://buy.itunes.apple.com/verifyReceipt'
        : 'https://sandbox.itunes.apple.com/verifyReceipt';

      const appleResponse = await fetch(verifyUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          'receipt-data': receiptData,
          password: process.env.APP_STORE_SHARED_SECRET || '',
        }),
      });

      const appleResult = await appleResponse.json();

      if (appleResult.status === 21007) {
        const sandboxResponse = await fetch('https://sandbox.itunes.apple.com/verifyReceipt', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            'receipt-data': receiptData,
            password: process.env.APP_STORE_SHARED_SECRET || '',
          }),
        });
        const sandboxResult = await sandboxResponse.json();
        if (sandboxResult.status !== 0) {
          return res.status(400).json({ success: false, message: 'Receipt verification failed (sandbox)' });
        }
      } else if (appleResult.status !== 0) {
        return res.status(400).json({ success: false, message: `Receipt verification failed: status ${appleResult.status}` });
      }

      await storage.updateUser(userId, {
        subscriptionTier: newTier,
        subscriptionStatus: 'active',
        subscriptionSource: 'apple',
        appleProductId: productId,
        appleReceiptData: receiptData,
      } as any);

      if (newTier === 'team' || newTier === 'business') {
        const bs = await storage.getBusinessSettings(userId);
        if (bs && (!bs.teamSize || bs.teamSize === 'solo')) {
          await storage.updateBusinessSettings(userId, { teamSize: 'small' });
        }
      }

      console.log(`[IAP] User ${userId} upgraded to ${newTier} via Apple IAP (product: ${productId})`);

      res.json({
        success: true,
        tier: newTier,
        message: `Successfully upgraded to ${newTier}`,
      });
    } catch (error: any) {
      console.error('Error verifying Apple receipt:', error);
      res.status(500).json({ success: false, message: error.message || 'Failed to verify receipt' });
    }
  });

  // POST /api/subscription/verify-apple-addon - Verifies an Apple IAP add-on purchase
  // (AI Receptionist / Dedicated Number) and provisions the feature. The addon_subscriptions
  // row is the single source of truth for add-on billing state across iOS, Android and web.
  // Returns 200 even on verification failure (success:false) so the client recovers gracefully.
  app.post("/api/subscription/verify-apple-addon", requireAuth, requirePaidTier(), ownerOnly(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { receiptData, productId, phoneNumber } = req.body;

      if (!receiptData || !productId) {
        return res.json({ success: false, message: 'Receipt data and product ID are required' });
      }

      const addonMap: Record<string, 'dedicated_number' | 'ai_receptionist'> = {
        'com.jobrunner.dedicatednumber.monthly': 'dedicated_number',
        'com.jobrunner.aireceptionist.monthly': 'ai_receptionist',
      };
      const addon = addonMap[productId];
      if (!addon) {
        return res.json({ success: false, message: 'Invalid add-on product ID' });
      }

      // Verify receipt with Apple (production first, sandbox fallback on 21007)
      const verifyUrl = process.env.NODE_ENV === 'production'
        ? 'https://buy.itunes.apple.com/verifyReceipt'
        : 'https://sandbox.itunes.apple.com/verifyReceipt';
      const appleResponse = await fetch(verifyUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 'receipt-data': receiptData, password: process.env.APP_STORE_SHARED_SECRET || '' }),
      });
      let appleResult: any = await appleResponse.json();
      let verified = appleResult.status === 0;
      if (!verified && appleResult.status === 21007) {
        const sandboxResponse = await fetch('https://sandbox.itunes.apple.com/verifyReceipt', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ 'receipt-data': receiptData, password: process.env.APP_STORE_SHARED_SECRET || '' }),
        });
        appleResult = await sandboxResponse.json();
        verified = appleResult.status === 0;
      }
      if (!verified) {
        console.warn(`[IAP] Add-on receipt verification failed for user ${userId}, product ${productId}, status ${appleResult.status}`);
        return res.json({ success: false, message: `Receipt verification failed (status ${appleResult.status})` });
      }

      // The receipt MUST actually contain a transaction for the requested add-on product.
      // Binding to latest_receipt_info[0] regardless of product would let any valid receipt
      // (e.g. a tier subscription) activate an add-on, so require a real product match.
      let originalTransactionId: string | undefined;
      try {
        const latestInfo = appleResult?.latest_receipt_info;
        if (Array.isArray(latestInfo) && latestInfo.length > 0) {
          const matching = latestInfo
            .filter((t: any) => t.product_id === productId)
            .sort((a: any, b: any) => Number(b.purchase_date_ms || 0) - Number(a.purchase_date_ms || 0));
          originalTransactionId = matching[0]?.original_transaction_id;
        }
      } catch (e) {
        console.warn('[IAP] Could not extract add-on originalTransactionId:', e);
      }
      if (!originalTransactionId) {
        console.warn(`[IAP] Add-on receipt for user ${userId} has no transaction for product ${productId}`);
        return res.json({ success: false, message: 'This receipt does not contain a purchase for that add-on.' });
      }

      // Replay / cross-account guard: an Apple transaction belongs to exactly one account.
      // If this transaction is already linked to a DIFFERENT user, reject — never let a
      // shared/leaked receipt grant a second account the entitlement.
      const existingByTxn = await storage.getAddonSubscriptionByAppleTxn(originalTransactionId);
      if (existingByTxn && existingByTxn.userId !== userId) {
        console.warn(`[IAP] Add-on txn ${originalTransactionId} already linked to user ${existingByTxn.userId}, rejected for ${userId}`);
        return res.json({ success: false, message: 'This purchase is already linked to another account.' });
      }

      // Record the add-on subscription as active — billing-state source of truth.
      await storage.upsertAddonSubscription(userId, addon, {
        source: 'apple',
        status: 'active',
        appleProductId: productId,
        ...(originalTransactionId ? { appleOriginalTransactionId: originalTransactionId } : {}),
      });
      console.log(`[IAP] User ${userId} activated add-on ${addon} via Apple IAP (txn=${originalTransactionId || 'unknown'})`);

      // Provision the feature
      if (addon === 'dedicated_number') {
        const settings = await storage.getBusinessSettings(userId);
        // Provision a number now only if one was selected and none exists yet.
        if (!settings?.dedicatedPhoneNumber && phoneNumber && /^\+\d{10,15}$/.test(phoneNumber)) {
          if (!settings?.address) {
            return res.json({ success: true, addon, status: 'active', needsNumberSelection: true, message: 'Subscription active. Add your business address in Settings to get your number.' });
          }
          try {
            const { purchasePhoneNumber, createOrFindTwilioAddress } = await import('./twilioClient');
            const addressResult = await createOrFindTwilioAddress(userId, {
              businessName: settings.businessName || 'JobRunner Business',
              address: settings.address,
              customerName: settings.businessName,
            });
            if (addressResult.success && addressResult.addressSid) {
              const baseUrl = process.env.CUSTOM_DOMAIN
                ? `https://${process.env.CUSTOM_DOMAIN}`
                : `https://${process.env.REPLIT_DOMAINS?.split(',')[0] || 'localhost:5000'}`;
              const webhookUrl = `${baseUrl}/api/sms/webhook/incoming`;
              const result = await purchasePhoneNumber(phoneNumber, webhookUrl, addressResult.addressSid, settings.businessName);
              if (result.success) {
                await storage.updateBusinessSettings(userId, { dedicatedPhoneNumber: result.phoneNumber, smsMode: 'ai_receptionist' });
                return res.json({ success: true, addon, status: 'active', phoneNumber: result.phoneNumber, message: 'Dedicated number active and assigned.' });
              }
            }
          } catch (e) {
            console.error('[IAP] Dedicated number provisioning after Apple purchase failed:', e);
          }
        }
        // Subscription active; number can be picked from the Phone Numbers screen (purchase route skips Stripe for Apple-paid users).
        return res.json({ success: true, addon, status: 'active', needsNumberSelection: !settings?.dedicatedPhoneNumber, message: 'Dedicated number subscription active.' });
      }

      if (addon === 'ai_receptionist') {
        const settings = await storage.getBusinessSettings(userId);
        const dedicatedNumber = settings?.dedicatedPhoneNumber;
        const { isSharedPlatformNumber } = await import('./phoneNumberUtils');
        if (!dedicatedNumber || isSharedPlatformNumber(dedicatedNumber)) {
          return res.json({ success: true, addon, status: 'active', needsDedicatedNumber: true, message: 'AI Receptionist active. Get a dedicated number to finish setup.' });
        }
        const existingConfigs = await storage.getAiReceptionistConfigsByUser(userId);
        if (existingConfigs.length === 0) {
          await storage.createAiReceptionistConfig({
            userId,
            enabled: false,
            mode: 'always_on_message',
            voiceName: 'Jess',
            approvalStatus: 'provisioning',
          });
        } else {
          await storage.updateAiReceptionistConfig(userId, { approvalStatus: 'provisioning', provisioningError: null });
        }
        await storage.updateBusinessSettings(userId, { aiReceptionistEnabled: true });
        const { provisionAiReceptionist } = await import('./aiReceptionistProvisioning');
        provisionAiReceptionist(userId, dedicatedNumber).catch(err => {
          console.error('[IAP AI Receptionist] Provisioning failed:', err);
        });
        return res.json({ success: true, addon, status: 'active', provisioning: true, message: 'AI Receptionist activated.' });
      }

      return res.json({ success: true, addon, status: 'active' });
    } catch (error: any) {
      console.error('[IAP] Error verifying Apple add-on receipt:', error);
      res.status(500).json({ success: false, message: error.message || 'Failed to verify add-on receipt' });
    }
  });


  // POST /api/iap/apple-notifications is registered in server/index.ts BEFORE
  // express.json() so the raw JWS body is available for signature verification
  // (see verifyAppleJws / applyAppleNotification). Do NOT re-register it here.

  app.post("/api/subscription/restore-apple", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { receiptData, productId } = req.body;

      if (!receiptData || !productId) {
        return res.status(400).json({ success: false, message: 'Receipt data and product ID are required' });
      }

      const tierMap: Record<string, string> = {
        'com.jobrunner.pro.monthly': 'pro',
        'com.jobrunner.team.monthly': 'team',
        'com.jobrunner.business.monthly': 'business',
      };

      const newTier = tierMap[productId];
      if (!newTier) {
        return res.status(400).json({ success: false, message: 'Invalid product ID' });
      }

      const verifyUrl = process.env.NODE_ENV === 'production'
        ? 'https://buy.itunes.apple.com/verifyReceipt'
        : 'https://sandbox.itunes.apple.com/verifyReceipt';

      const appleResponse = await fetch(verifyUrl, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          'receipt-data': receiptData,
          password: process.env.APP_STORE_SHARED_SECRET || '',
        }),
      });

      const appleResult = await appleResponse.json();

      if (appleResult.status === 21007) {
        const sandboxResponse = await fetch('https://sandbox.itunes.apple.com/verifyReceipt', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            'receipt-data': receiptData,
            password: process.env.APP_STORE_SHARED_SECRET || '',
          }),
        });
        const sandboxResult = await sandboxResponse.json();
        if (sandboxResult.status !== 0) {
          return res.status(400).json({ success: false, message: 'Receipt verification failed during restore' });
        }
      } else if (appleResult.status !== 0) {
        return res.status(400).json({ success: false, message: `Receipt verification failed: status ${appleResult.status}` });
      }

      await storage.updateUser(userId, {
        subscriptionTier: newTier,
        subscriptionStatus: 'active',
        subscriptionSource: 'apple',
        appleProductId: productId,
        appleReceiptData: receiptData,
      } as any);

      if (newTier === 'team' || newTier === 'business') {
        const bs = await storage.getBusinessSettings(userId);
        if (bs && (!bs.teamSize || bs.teamSize === 'solo')) {
          await storage.updateBusinessSettings(userId, { teamSize: 'small' });
        }
      }

      console.log(`[IAP] User ${userId} restored to ${newTier} via Apple IAP (verified)`);

      res.json({
        success: true,
        tier: newTier,
        message: `Subscription restored to ${newTier}`,
      });
    } catch (error: any) {
      console.error('Error restoring Apple subscription:', error);
      res.status(500).json({ success: false, message: error.message || 'Failed to restore subscription' });
    }
  });

  // Returns the real road geometry (and per-leg drive time/distance) for a set
  // of ordered stops, so the map can draw the actual driving path instead of
  // straight lines. Falls back gracefully (404) when OSRM is unavailable.
  app.post("/api/routes/geometry", requireAuth, async (req: any, res) => {
    try {
      const { stops } = req.body || {};
      if (!Array.isArray(stops) || stops.length < 2) {
        return res.status(400).json({ error: "At least 2 stops are required" });
      }

      const points = stops
        .map((s: any) => ({ lat: Number(s?.lat), lng: Number(s?.lng) }))
        .filter(
          (p: { lat: number; lng: number }) =>
            Number.isFinite(p.lat) &&
            Number.isFinite(p.lng) &&
            Math.abs(p.lat) <= 90 &&
            Math.abs(p.lng) <= 180
        );

      if (points.length < 2) {
        return res.status(400).json({ error: "At least 2 valid coordinates are required" });
      }

      const geometry = await getRouteGeometry(points);
      if (!geometry) {
        return res.status(404).json({ error: "Route geometry unavailable" });
      }

      return res.json(geometry);
    } catch (error) {
      console.error("Error fetching route geometry:", error);
      return res.status(500).json({ error: "Failed to fetch route geometry" });
    }
  });

  app.post("/api/routes/optimize", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const { date, startLocation } = req.body;

      if (!date) {
        return res.status(400).json({ error: "Date is required (YYYY-MM-DD format)" });
      }

      const apiKey = process.env.GOOGLE_MAPS_API_KEY;
      
      // Fetch scheduled or in_progress jobs for this user on the given date
      const allJobs = await storage.getJobs(userContext.effectiveUserId);
      const targetDate = new Date(date).toISOString().split('T')[0];
      
      const jobsToOptimize = allJobs.filter(job => {
        if (!job.scheduledAt) return false;
        const jobDate = new Date(job.scheduledAt).toISOString().split('T')[0];
        const status = job.status.toLowerCase();
        return jobDate === targetDate && (status === 'scheduled' || status === 'in_progress');
      });

      if (jobsToOptimize.length === 0) {
        return res.json({
          optimizedOrder: [],
          totalDistance: "0 km",
          totalDuration: "0 mins",
          savedDistance: "0 km",
          message: "No jobs found to optimize for this date."
        });
      }

      // Ensure all jobs have coordinates, geocode if necessary
      const jobsWithCoords = await Promise.all(jobsToOptimize.map(async (job) => {
        let lat = job.latitude ? parseFloat(job.latitude as string) : null;
        let lng = job.longitude ? parseFloat(job.longitude as string) : null;
        
        if ((lat === null || lng === null) && job.address) {
          try {
            const coords = await geocodeAddress(job.address);
            if (coords) {
              lat = coords.latitude;
              lng = coords.longitude;
              // Update job with coordinates for future use
              await storage.updateJob(job.id, userContext.effectiveUserId, {
                latitude: lat.toString(),
                longitude: lng.toString()
              });
            }
          } catch (e) {
            console.error(`Failed to geocode address for job ${job.id}:`, e);
          }
        }
        
        return { ...job, lat, lng };
      }));

      // Filter out jobs that still don't have coordinates
      const validJobs = jobsWithCoords.filter(j => j.lat !== null && j.lng !== null);
      
      if (validJobs.length === 0) {
        return res.status(400).json({ error: "Could not determine coordinates for any jobs." });
      }

      // Optimization Logic
      let result;
      let usedGoogleMaps = false;

      if (apiKey) {
        try {
          const origin = startLocation 
            ? `${startLocation.lat},${startLocation.lng}` 
            : `${validJobs[0].lat},${validJobs[0].lng}`;
          
          // If startLocation is not provided, the first job is the origin and should not be a waypoint
          const waypointsJobs = startLocation ? validJobs : validJobs.slice(1);
          
          if (waypointsJobs.length > 0) {
            const waypoints = `optimize:true|${waypointsJobs.map(j => `${j.lat},${j.lng}`).join('|')}`;
            const url = `https://maps.googleapis.com/maps/api/directions/json?origin=${origin}&destination=${origin}&waypoints=${waypoints}&key=${apiKey}`;
            
            const response = await fetch(url);
            const data = await response.json();
            
            if (data.status === 'OK') {
              const route = data.routes[0];
              const waypointOrder = route.waypoint_order; // Array of indices into waypoints
              
              const optimizedJobs = waypointOrder.map((index: number) => waypointsJobs[index]);
              
              // If we didn't use startLocation, the first job was the origin
              const finalOrder = startLocation ? optimizedJobs : [validJobs[0], ...optimizedJobs];
              
              let totalDistanceMeters = 0;
              let totalDurationSeconds = 0;
              
              route.legs.forEach((leg: any) => {
                totalDistanceMeters += leg.distance.value;
                totalDurationSeconds += leg.duration.value;
              });

              // Calculate arrival times starting from 9:00 AM or a reasonable start time
              let currentTime = new Date(`${date}T09:00:00`);
              const optimizedOrder = finalOrder.map((job: typeof validJobs[number], idx: number) => {
                const arrivalTime = currentTime.toLocaleTimeString('en-AU', { hour: '2-digit', minute: '2-digit', hour12: false });
                // Add travel time to next job (this is simplified, normally we'd add job duration too)
                if (route.legs[idx]) {
                  currentTime = new Date(currentTime.getTime() + (route.legs[idx].duration.value * 1000) + ((job.estimatedDuration || 60) * 60 * 1000));
                }
                
                return {
                  jobId: job.id,
                  order: idx + 1,
                  arrivalTime,
                  address: job.address
                };
              });

              result = {
                optimizedOrder,
                totalDistance: `${(totalDistanceMeters / 1000).toFixed(1)} km`,
                totalDuration: `${Math.floor(totalDurationSeconds / 3600)}h ${Math.round((totalDurationSeconds % 3600) / 60)}m`,
                savedDistance: "Calculated via Google Maps" // Placeholder as "original order" isn't strictly defined
              };
              usedGoogleMaps = true;
            } else {
              console.warn("Google Maps Directions API returned status:", data.status);
            }
          } else {
            // Only one job, no optimization needed
            result = {
              optimizedOrder: [{ jobId: validJobs[0].id, order: 1, arrivalTime: "09:00", address: validJobs[0].address }],
              totalDistance: "0 km",
              totalDuration: "0 mins",
              savedDistance: "0 km"
            };
            usedGoogleMaps = true;
          }
        } catch (e) {
          console.error("Google Maps Route Optimization failed, falling back to Haversine:", e);
        }
      }

      // Fallback to Haversine nearest-neighbor if Google Maps failed or no API key
      if (!usedGoogleMaps) {
        const optimizedOrder: any[] = [];
        let currentPos = startLocation || { lat: validJobs[0].lat, lng: validJobs[0].lng };
        const remainingJobs = startLocation ? [...validJobs] : validJobs.slice(1);
        
        if (!startLocation) {
          optimizedOrder.push({
            jobId: validJobs[0].id,
            order: 1,
            arrivalTime: "09:00",
            address: validJobs[0].address
          });
        }

        let currentTime = new Date(`${date}T09:00:00`);
        let totalDist = 0;

        while (remainingJobs.length > 0) {
          let nearestIdx = 0;
          let minDist = haversineDistance(
            currentPos.lat, currentPos.lng,
            remainingJobs[0].lat!, remainingJobs[0].lng!
          );

          for (let i = 1; i < remainingJobs.length; i++) {
            const dist = haversineDistance(
              currentPos.lat, currentPos.lng,
              remainingJobs[i].lat!, remainingJobs[i].lng!
            );
            if (dist < minDist) {
              minDist = dist;
              nearestIdx = i;
            }
          }

          const nextJob = remainingJobs.splice(nearestIdx, 1)[0];
          totalDist += minDist;
          
          // Estimate 30km/h average speed for duration
          const travelTimeMins = (minDist / 30) * 60;
          currentTime = new Date(currentTime.getTime() + (travelTimeMins * 60 * 1000));
          
          optimizedOrder.push({
            jobId: nextJob.id,
            order: optimizedOrder.length + 1,
            arrivalTime: currentTime.toLocaleTimeString('en-AU', { hour: '2-digit', minute: '2-digit', hour12: false }),
            address: nextJob.address
          });
          
          // Add job duration
          currentTime = new Date(currentTime.getTime() + ((nextJob.estimatedDuration || 60) * 60 * 1000));
          currentPos = { lat: nextJob.lat!, lng: nextJob.lng! };
        }

        result = {
          optimizedOrder,
          totalDistance: `${totalDist.toFixed(1)} km`,
          totalDuration: "Estimated via Haversine",
          savedDistance: "N/A (Fallback used)",
          warning: apiKey ? "Google Maps API failed, used fallback" : "No Google Maps API key, used fallback"
        };
      }

      res.json(result);
    } catch (error) {
      console.error("Route optimization error:", error);
      res.status(500).json({ error: "Failed to optimize route" });
    }
  });

  // AI-powered schedule optimization with smart recommendations
  app.post("/api/schedule/ai-optimize", requireAuth, async (req: any, res) => {
    try {
      const effectiveUserId = req.effectiveUserId || req.userId;
      const { date, startLocation, workdayStart, workdayEnd } = req.body;
      
      // Get jobs for the specified date
      const targetDate = date ? new Date(date) : new Date();
      const jobs = await storage.getJobs(effectiveUserId);
      const clients = await storage.getClients(effectiveUserId);
      
      console.log(`[AI Schedule] Optimizing for date: ${targetDate.toDateString()}, total jobs: ${jobs.length}`);
      
      // Filter jobs scheduled for the target date (use scheduledAt field - jobs use this, not scheduledDate)
      const scheduledJobs = jobs.filter(job => {
        // Use scheduledAt (timestamp) not scheduledDate
        const jobScheduledTime = job.scheduledAt;
        if (!jobScheduledTime) return false;
        const jobDate = new Date(jobScheduledTime);
        const isTargetDate = jobDate.toDateString() === targetDate.toDateString();
        const isValidStatus = ['pending', 'scheduled', 'in_progress'].includes(job.status);
        return isTargetDate && isValidStatus;
      });
      
      console.log(`[AI Schedule] Found ${scheduledJobs.length} jobs for ${targetDate.toDateString()}`);

      // Map jobs to the format expected by the optimizer
      // Jobs store their own coordinates (latitude/longitude), use those for optimization
      const scheduleJobs = scheduledJobs.map(job => {
        const client = clients.find(c => c.id === job.clientId);
        // Use job's coordinates first, fallback to client's coordinates
        const lat = job.latitude ? parseFloat(String(job.latitude)) : undefined;
        const lng = job.longitude ? parseFloat(String(job.longitude)) : undefined;
        
        return {
          id: job.id,
          title: job.title,
          clientName: client?.name || 'Unknown',
          address: job.address || client?.address || undefined,
          latitude: lat,
          longitude: lng,
          estimatedDuration: job.estimatedDuration ? parseFloat(String(job.estimatedDuration)) / 60 : 1.5, // Convert minutes to hours
        };
      });
      
      console.log(`[AI Schedule] Jobs with coordinates: ${scheduleJobs.filter(j => j.latitude && j.longitude).length}`);

      // Import and call the AI optimizer
      const { optimizeSchedule, getSchedulingRecommendations } = await import('./ai');
      
      const optimizedSchedule = await optimizeSchedule(
        scheduleJobs,
        startLocation,
        workdayStart || '07:00',
        workdayEnd || '17:00'
      );

      // Get AI recommendations
      const businessSettings = await storage.getBusinessSettings(effectiveUserId);
      const aiRecommendations = await getSchedulingRecommendations(
        scheduleJobs,
        { 
          trade: (await storage.getUser(effectiveUserId))?.tradeType || undefined,
          businessName: businessSettings?.businessName || undefined
        }
      );

      // Fetch team members and equipment for full day plan context
      const [teamMembers, equipmentList] = await Promise.all([
        storage.getTeamMembers(effectiveUserId),
        storage.getEquipment(effectiveUserId),
      ]);

      const activeTeamMembers = teamMembers.filter((m: any) => m.isActive).map((m: any) => ({
        id: m.id,
        memberId: m.memberId,
        name: `${m.firstName || ''} ${m.lastName || ''}`.trim() || m.email,
        role: m.roleName,
      }));

      const availableEquipment = equipmentList.filter((e: any) => e.status === 'available' || e.status === 'in_use').map((e: any) => ({
        id: e.id,
        name: e.name,
        category: e.category,
        status: e.status,
      }));

      const jobEquipmentData: Record<string, any[]> = {};
      for (const job of scheduledJobs) {
        const assignments = await storage.getJobEquipment(job.id);
        if (assignments.length > 0) {
          jobEquipmentData[job.id] = assignments;
        }
      }

      res.json({
        date: targetDate.toISOString().split('T')[0],
        ...optimizedSchedule,
        aiRecommendations,
        teamMembers: activeTeamMembers,
        availableEquipment,
        jobEquipmentAssignments: jobEquipmentData,
        jobAssignments: scheduledJobs.reduce((acc: Record<string, string | null>, job) => {
          acc[job.id] = job.assignedTo || null;
          return acc;
        }, {}),
      });
    } catch (error: any) {
      console.error("AI schedule optimization error:", error);
      res.status(500).json({ error: "Failed to optimize schedule" });
    }
  });

