  // Job Proof Pack HTML Preview (for iframe preview before download)
  async function buildProofPackData(jobId: string, userId: string, query: any) {
    const job = await storage.getJob(jobId, userId);
    if (!job) throw { status: 404, message: 'Job not found' };

    const client = job.clientId ? await storage.getClientById(job.clientId) : null;
    const businessRaw = await storage.getBusinessSettingsByUserId(userId);
    if (!businessRaw) throw { status: 404, message: 'Business settings not found' };

    const { resolveBusinessLogoForPdf } = await import('./pdfService');
    const business = await resolveBusinessLogoForPdf(businessRaw);

    const hideSections = {
      timeline: query.hide_timeline === '1',
      attendance: query.hide_attendance === '1',
      gpsProof: query.hide_gpsProof === '1',
      materials: query.hide_materials === '1',
      variations: query.hide_variations === '1',
      photos: query.hide_photos === '1',
      invoice: query.hide_invoice === '1',
      retention: query.hide_retention === '1',
      compliance: query.hide_compliance === '1',
      subcontractors: query.hide_subcontractors === '1',
      swms: query.hide_swms === '1',
      forms: query.hide_forms === '1',
    };

    const rawTimeEntries = await storage.getTimeEntriesForJob(jobId);
    const ownerUser = await storage.getUser(userId);
    const ownerName = [ownerUser?.firstName, ownerUser?.lastName].filter(Boolean).join(' ') || 'Owner';

    const timeEntries = rawTimeEntries.map((e: any) => {
      const durationMinutes = e.endTime
        ? Math.floor((new Date(e.endTime).getTime() - new Date(e.startTime).getTime()) / 60000)
        : (e.duration || 0);
      return {
        workerName: e.userId === userId ? ownerName : (e.workerName || 'Team Member'),
        startTime: e.startTime?.toISOString?.() || String(e.startTime),
        endTime: e.endTime ? (e.endTime?.toISOString?.() || String(e.endTime)) : undefined,
        duration: durationMinutes,
        billable: e.billable !== false,
        clockInLatitude: e.clockInLatitude || null,
        clockInLongitude: e.clockInLongitude || null,
        clockInAddress: e.clockInAddress || null,
        clockOutLatitude: e.clockOutLatitude || null,
        clockOutLongitude: e.clockOutLongitude || null,
        clockOutAddress: e.clockOutAddress || null,
        origin: e.origin || 'manual',
      };
    });

    const materials = await storage.getJobMaterials(jobId, userId);

    let photos: Array<{url: string; caption?: string; category: string; createdAt?: string; latitude?: number | null; longitude?: number | null; address?: string | null}> = [];
    try {
      const { getJobPhotos } = await import('./photoService');
      const rawPhotos = await getJobPhotos(jobId, userId);
      photos = rawPhotos
        .filter((p: any) => p.signedUrl)
        .map((p: any) => ({
          url: p.signedUrl!,
          caption: p.caption || undefined,
          category: p.category || 'general',
          createdAt: p.createdAt ? (p.createdAt instanceof Date ? p.createdAt.toISOString() : String(p.createdAt)) : undefined,
          latitude: p.latitude != null ? p.latitude : null,
          longitude: p.longitude != null ? p.longitude : null,
          address: p.address || null,
        }));
    } catch (e) {
      console.error('Error fetching photos for proof pack:', e);
    }

    let invoiceData: { number: string; date: string; total: string; gstAmount: string; status: string } | null = null;
    try {
      const linkedInvoices = await db.select().from(invoices).where(eq(invoices.jobId, jobId)).limit(1);
      if (linkedInvoices.length > 0) {
        const inv = linkedInvoices[0];
        invoiceData = {
          number: inv.number || inv.id.slice(0, 8),
          date: inv.createdAt ? new Date(inv.createdAt).toLocaleDateString('en-AU') : '-',
          total: inv.total || '0',
          gstAmount: inv.gstAmount || '0',
          status: inv.status || 'draft',
        };
      }
    } catch (e) {
      console.error('Error fetching invoice for proof pack:', e);
    }

    let geofenceAlerts: any[] = [];
    try {
      const alerts = await db.select().from(geofence_alerts).where(eq(geofence_alerts.jobId, jobId));
      const alertsWithNames = await Promise.all(alerts.map(async (a: any) => {
        let workerName = 'Team Member';
        if (a.userId) {
          try {
            const alertUser = await storage.getUser(a.userId);
            if (alertUser) {
              workerName = [alertUser.firstName, alertUser.lastName].filter(Boolean).join(' ') || alertUser.email || 'Team Member';
            }
          } catch {}
        }
        return {
          workerName,
          alertType: a.alertType,
          latitude: a.latitude,
          longitude: a.longitude,
          address: a.address,
          distanceFromSite: a.distanceFromSite,
          createdAt: a.createdAt?.toISOString?.() || String(a.createdAt),
        };
      }));
      geofenceAlerts = alertsWithNames;
    } catch (e) {
      console.error('Error fetching geofence alerts for proof pack:', e);
    }

    let complianceDocs: any[] = [];
    try {
      const workerIds = new Set<string>();
      rawTimeEntries.forEach((e: any) => { if (e.userId) workerIds.add(e.userId); });
      workerIds.add(userId);
      
      const allDocs = await storage.getComplianceDocuments(userId);
      const now = new Date();
      complianceDocs = allDocs
        .filter((d: any) => {
          if (!d.holderUserId) return true;
          return workerIds.has(d.holderUserId);
        })
        .map((d: any) => {
          let status = 'current';
          if (d.expiryDate) {
            const expiry = new Date(d.expiryDate);
            const daysUntil = Math.floor((expiry.getTime() - now.getTime()) / (1000 * 60 * 60 * 24));
            if (daysUntil < 0) status = 'expired';
            else if (daysUntil <= 30) status = 'expiring';
          }
          return {
            type: d.type,
            title: d.title,
            documentNumber: d.documentNumber,
            issuer: d.issuer,
            holderName: d.holderName,
            expiryDate: d.expiryDate ? new Date(d.expiryDate).toLocaleDateString('en-AU') : null,
            coverageAmount: d.coverageAmount,
            status,
          };
        });
    } catch (e) {
      console.error('Error fetching compliance docs for proof pack:', e);
    }

    let subcontractorsList: any[] = [];
    try {
      const subTokens = await storage.getSubcontractorTokensByJobId(jobId);
      const jobInvitesList = await db.select().from(jobInvites).where(eq(jobInvites.jobId, jobId));
      
      subcontractorsList = [...subTokens.map((t: any) => ({
        name: t.contactName || t.contactEmail || t.contactPhone || 'Subcontractor',
        status: t.status || 'pending',
        invitedAt: t.createdAt ? new Date(t.createdAt).toLocaleDateString('en-AU') : null,
        acceptedAt: t.acceptedAt ? new Date(t.acceptedAt).toLocaleDateString('en-AU') : null,
        lastAccessed: t.lastAccessedAt ? new Date(t.lastAccessedAt).toLocaleDateString('en-AU') : null,
        source: 'direct_invite',
      })), ...jobInvitesList.filter((inv: any) => !subTokens.some((t: any) => t.inviteId === inv.id)).map((inv: any) => ({
        name: inv.email || 'Subcontractor',
        status: inv.status || 'pending',
        invitedAt: inv.createdAt ? new Date(inv.createdAt).toLocaleDateString('en-AU') : null,
        acceptedAt: inv.usedAt ? new Date(inv.usedAt).toLocaleDateString('en-AU') : null,
        lastAccessed: null,
        source: 'magic_link',
      }))];
    } catch (e) {
      console.error('Error fetching subcontractor data for proof pack:', e);
    }

    let variations: any[] = [];
    try {
      const allVariations = await storage.getJobVariations(jobId, userId);
      variations = allVariations.map((v: any) => ({
        number: v.number,
        title: v.title,
        description: v.description || undefined,
        reason: v.reason || undefined,
        additionalAmount: v.additionalAmount || '0',
        gstAmount: v.gstAmount || '0',
        totalAmount: v.totalAmount || '0',
        status: v.status,
        approvedByName: v.approvedByName || undefined,
        approvedAt: v.approvedAt ? new Date(v.approvedAt).toLocaleDateString('en-AU') : undefined,
        createdAt: v.createdAt ? new Date(v.createdAt).toLocaleDateString('en-AU') : undefined,
      }));
    } catch (e) {
      console.error('Error fetching variations for proof pack:', e);
    }

    let swmsList: any[] = [];
    try {
      const swmsDocs = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.jobId, jobId), eq(swmsDocuments.userId, userId)));
      for (const sdoc of swmsDocs) {
        const hazards = await db.select().from(swmsHazards).where(eq(swmsHazards.swmsId, sdoc.id)).orderBy(asc(swmsHazards.sortOrder));
        const sigs = await db.select().from(swmsSignatures).where(eq(swmsSignatures.swmsId, sdoc.id)).orderBy(asc(swmsSignatures.signedAt));
        const ppeLabels: Record<string, string> = { hard_hat: 'Hard Hat', safety_glasses: 'Safety Glasses', hi_vis: 'Hi-Vis Vest', steel_caps: 'Steel Cap Boots', hearing_protection: 'Hearing Protection', dust_mask: 'Dust Mask', gloves: 'Gloves', fall_harness: 'Fall Harness', face_shield: 'Face Shield', sun_protection: 'Sun Protection' };
        swmsList.push({
          title: sdoc.title,
          status: sdoc.status,
          siteAddress: sdoc.siteAddress,
          workActivity: sdoc.workActivityDescription,
          ppe: (sdoc.ppeRequirements as string[] || []).map((p: string) => ppeLabels[p] || p),
          hazards: hazards.map(h => ({
            activity: h.activityTask,
            hazard: h.hazard,
            riskBefore: h.riskBefore,
            controlMeasures: h.controlMeasures,
            riskAfter: h.riskAfter,
          })),
          signatures: sigs.map(s => ({
            name: s.workerName,
            signedAt: s.signedAt ? new Date(s.signedAt).toLocaleString('en-AU') : '-',
            location: s.address || (s.latitude ? `${s.latitude}, ${s.longitude}` : null),
          })),
          createdAt: sdoc.createdAt ? new Date(sdoc.createdAt).toLocaleDateString('en-AU') : '-',
        });
      }
    } catch (e) {
      console.error('Error fetching SWMS for proof pack:', e);
    }

    let safetyForms: any[] = [];
    try {
      const submissions = await storage.getFormSubmissionsByJob(jobId, userId);
      for (const sub of submissions) {
        const form = await storage.getCustomForm(sub.formId, userId);
        if (!form) continue;
        const formType = form.formType || 'general';
        const isJobCardForm = !!(form as any).isJobCard;
        const fields = (form.fields || []) as Array<{id: string; label: string; type: string}>;
        const data = (sub.submissionData || {}) as Record<string, any>;
        const responses: Array<{label: string; value: string; type: string}> = [];
        for (const field of fields) {
          const val = data[field.id];
          if (val === undefined || val === null || val === '') continue;
          let displayVal = String(val);
          if (typeof val === 'boolean') displayVal = val ? 'Yes' : 'No';
          if (Array.isArray(val)) displayVal = val.join(', ');
          responses.push({ label: field.label, value: displayVal, type: field.type || 'text' });
        }
        let submittedByName: string | undefined;
        if (sub.submittedBy) {
          try {
            const subUser = await storage.getUser(sub.submittedBy);
            if (subUser) submittedByName = [subUser.firstName, subUser.lastName].filter(Boolean).join(' ') || subUser.email || undefined;
          } catch {}
        }
        safetyForms.push({
          formName: form.name,
          formType,
          isJobCard: isJobCardForm,
          description: form.description || undefined,
          status: sub.status || 'submitted',
          submittedAt: sub.submittedAt ? new Date(sub.submittedAt).toLocaleString('en-AU', { timeZone: 'Australia/Sydney' }) : '-',
          submittedBy: submittedByName || undefined,
          notes: sub.notes || undefined,
          responses,
        });
      }
    } catch (e) {
      console.error('Error fetching safety forms for proof pack:', e);
    }

    // --- retention schedule (only included when retention has been withheld) ---
    let retention: {
      sumRetentionHeld: number;
      outstandingRetention: number;
      practicalCompletionDate: string | null;
      defectsLiabilityMonths: number;
      releaseDate: string | null;
      retentionStatus: string;
    } | null = null;
    try {
      const { computeRetentionSummary } = await import('./routes/retentionSummary');
      const allClaims = await storage.getClaims(jobId, userId);
      const rs = computeRetentionSummary(allClaims as any, {
        practicalCompletionDate: (job as any).practicalCompletionDate || null,
        defectsLiabilityMonths: (job as any).defectsLiabilityMonths ?? null,
      });
      retention = rs.sumRetentionHeld > 0 ? rs : null;
    } catch (e) {
      console.error('Error computing retention for proof pack:', e);
    }

    return {
      job,
      business,
      client: client || { name: 'Unknown Client' },
      timeEntries,
      materials: materials.map((m: any) => ({
        name: m.name,
        quantity: m.quantity || undefined,
        unitCost: m.unitCost || undefined,
        totalCost: m.totalCost || undefined,
        supplier: m.supplier || undefined,
        status: m.status || undefined,
      })),
      photos,
      invoice: invoiceData,
      geofenceAlerts,
      complianceDocs,
      subcontractors: subcontractorsList,
      variations,
      swmsList,
      safetyForms,
      hideSections,
      retention,
    };
  }


  // Streaming AI Photo Analysis - Analyse job photos with GPT-4o vision

  // Get Next Action for a Job - Shows what to do next

