  // Weather API - uses Open-Meteo (free, no API key required)
  // Cache weather data for 30 minutes to reduce external API calls
  let weatherCache: { data: any; timestamp: number; lat: number; lon: number } | null = null;
  const WEATHER_CACHE_DURATION = 30 * 60 * 1000; // 30 minutes

  app.get("/api/weather", requireAuth, async (req: any, res) => {
    try {
      // Accept client-provided GPS coordinates (mobile device location)
      const clientLat = parseFloat(req.query.lat as string);
      const clientLon = parseFloat(req.query.lon as string);
      
      // Default to Cairns, QLD if no location provided
      let lat = -16.9186;
      let lon = 145.7781;
      
      if (!isNaN(clientLat) && !isNaN(clientLon) && clientLat >= -90 && clientLat <= 90 && clientLon >= -180 && clientLon <= 180) {
        lat = clientLat;
        lon = clientLon;
      } else {
        // Fall back to business address location
        const settings = await storage.getBusinessSettings(req.userId);
        if (settings?.address) {
          const address = settings.address.toLowerCase();
          if (address.includes('sydney')) { lat = -33.8688; lon = 151.2093; }
          else if (address.includes('melbourne')) { lat = -37.8136; lon = 144.9631; }
          else if (address.includes('brisbane')) { lat = -27.4698; lon = 153.0251; }
          else if (address.includes('perth')) { lat = -31.9505; lon = 115.8605; }
          else if (address.includes('adelaide')) { lat = -34.9285; lon = 138.6007; }
          else if (address.includes('gold coast')) { lat = -28.0167; lon = 153.4000; }
          else if (address.includes('cairns')) { lat = -16.9186; lon = 145.7781; }
          else if (address.includes('townsville')) { lat = -19.2590; lon = 146.8169; }
          else if (address.includes('darwin')) { lat = -12.4634; lon = 130.8456; }
          else if (address.includes('hobart')) { lat = -42.8821; lon = 147.3272; }
          else if (address.includes('canberra')) { lat = -35.2809; lon = 149.1300; }
        }
      }

      // Check cache - only use if same location
      if (weatherCache && 
          weatherCache.lat === lat && 
          weatherCache.lon === lon &&
          Date.now() - weatherCache.timestamp < WEATHER_CACHE_DURATION) {
        return res.json(weatherCache.data);
      }

      // Fetch from Open-Meteo API (free, no API key required)
      const weatherUrl = `https://api.open-meteo.com/v1/forecast?latitude=${lat}&longitude=${lon}&current=temperature_2m,relative_humidity_2m,apparent_temperature,precipitation,weather_code,wind_speed_10m,is_day&daily=temperature_2m_max,temperature_2m_min,weather_code,precipitation_probability_max&timezone=Australia%2FSydney&forecast_days=3`;
      
      const response = await fetch(weatherUrl);
      if (!response.ok) {
        throw new Error('Weather API request failed');
      }
      
      const weatherData = await response.json();
      
      // Transform to our format
      const result = {
        temperature: weatherData.current.temperature_2m,
        apparentTemperature: weatherData.current.apparent_temperature,
        weatherCode: weatherData.current.weather_code,
        humidity: weatherData.current.relative_humidity_2m,
        windSpeed: weatherData.current.wind_speed_10m,
        precipitation: weatherData.current.precipitation,
        isDay: weatherData.current.is_day === 1,
        daily: {
          temperatureMax: weatherData.daily.temperature_2m_max,
          temperatureMin: weatherData.daily.temperature_2m_min,
          weatherCode: weatherData.daily.weather_code,
          precipitationProbability: weatherData.daily.precipitation_probability_max,
        },
      };

      // Cache the result
      weatherCache = { data: result, timestamp: Date.now(), lat, lon };
      
      res.json(result);
    } catch (error) {
      console.error("Error fetching weather:", error);
      // Return fallback weather data to prevent UI breakage
      res.json({
        temperature: 25,
        apparentTemperature: 26,
        weatherCode: 1,
        humidity: 65,
        windSpeed: 12,
        precipitation: 0,
        isDay: true,
        daily: {
          temperatureMax: [28, 29, 27],
          temperatureMin: [20, 21, 19],
          weatherCode: [1, 2, 3],
          precipitationProbability: [10, 20, 30],
        },
      });
    }
  });

  // General file upload endpoint for logos and images
  const generalUpload = multer({ 
    storage: multer.memoryStorage(),
    limits: { fileSize: 100 * 1024 * 1024 } // 100MB (PDFs/scans/large docs)
  });

  app.post("/api/upload", requireAuth, (req: any, res, next) => {
    generalUpload.single('file')(req, res, (err: any) => {
      if (err) {
        if (err.code === 'LIMIT_FILE_SIZE') {
          return res.status(413).json({ error: "File must be under 100MB" });
        }
        return res.status(400).json({ error: "Upload failed", details: err.message });
      }
      next();
    });
  }, async (req: any, res) => {
    try {
      if (!req.file) {
        return res.status(400).json({ error: "No file uploaded" });
      }

      const uploadType = req.body.type || 'general';
      const fileExt = req.file.originalname.split('.').pop() || 'png';

      let fileName: string;
      if (uploadType === 'compliance') {
        // Compliance documents are sensitive business records. Store them in the
        // private namespace so the /objects/ route gates them to the business owner
        // + managers only, and block non-owners/managers from uploading at all.
        const ctx = await getUserContext(req.userId);
        const isOwnerOrManager = ctx.isOwner || ctx.permissions.includes(PERMISSIONS.MANAGE_TEAM);
        if (!isOwnerOrManager) {
          return res.status(403).json({ error: "Only owners and managers can upload compliance documents" });
        }
        fileName = `.private/compliance/${ctx.effectiveUserId}/${crypto.randomUUID()}.${fileExt}`;
      } else {
        fileName = `${uploadType}/${req.userId}/${crypto.randomUUID()}.${fileExt}`;
      }

      // Try to upload to object storage
      try {
        const objectStorage = new ObjectStorageService();
        const objectPath = await objectStorage.uploadFile(fileName, req.file.buffer, req.file.mimetype);
        // uploadFile returns the path in /objects/{filename} format that works with /objects route
        res.json({ url: objectPath });
      } catch (storageError) {
        // Compliance files must stay private. Never fall back to an embeddable data:
        // URL for them — that would bypass the /objects authorization entirely.
        if (uploadType === 'compliance') {
          console.error("[Upload] Object storage failed for compliance upload:", storageError);
          return res.status(503).json({ error: "File storage is temporarily unavailable. Please try again." });
        }
        console.log("[Upload] Object storage not available, using data URL");
        // Fallback to data URL if object storage is not available
        const dataUrl = `data:${req.file.mimetype};base64,${req.file.buffer.toString('base64')}`;
        res.json({ url: dataUrl });
      }
    } catch (error) {
      console.error("Error uploading file:", error);
      res.status(500).json({ error: "Failed to upload file" });
    }
  });

