      const configured = xeroService.isXeroConfigured();
      if (!configured) {
        return res.json({ 
          configured: false,
          connected: false,
          message: "Xero integration is coming soon" 
        });
      }
      const status = await xeroService.getConnectionStatus(req.userId);
      res.json({ configured: true, ...status });
