  // Admin endpoint to force reset demo data (deletes all and recreates with new IDs)
  // Use when mobile/web IDs are out of sync or data is corrupted
  app.post("/api/admin/reset-demo-data", requireAuth, async (req: any, res) => {
    try {
      const { forceResetDemoData, DEMO_USER } = await import('./demoData');
      
      // Only allow demo user to reset their own data
      const user = await storage.getUser(req.userId);
      if (!user || user.email !== DEMO_USER.email) {
        return res.status(403).json({ error: 'Only the demo account can reset demo data' });
      }
      
      const result = await forceResetDemoData();
      
      if (!result.success) {
        return res.status(500).json({ error: result.message });
      }

      try {
        const demoJobs = await storage.getJobs(req.userId!);
        for (const job of demoJobs) {
          const existingTokens = await storage.getJobPortalTokensByJobId(job.id);
          const hasActive = existingTokens?.some((t: any) => !t.revokedAt && (!t.expiresAt || new Date(t.expiresAt) > new Date()));
          if (!hasActive) {
            const cryptoMod = await import('crypto');
            const token = cryptoMod.randomBytes(32).toString('hex');
            await storage.createJobPortalToken({
              jobId: job.id,
              userId: req.userId!,
              token,
              expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
              createdBy: req.userId!,
            });
          }
        }
        console.log('Portal tokens created for demo jobs');
      } catch (e) {
        console.error('Failed to create portal tokens for demo jobs:', e);
      }
      
      res.json({
        success: true,
        message: result.message,
        warning: 'Mobile app may need to refresh data. Pull down to refresh on all list screens.'
      });
    } catch (error: any) {
      console.error("Error resetting demo data:", error);
      res.status(500).json({ error: error.message || "Failed to reset demo data" });
    }
  });

  // Admin endpoint to refresh demo data for App Store screenshots
  // Updates scheduled jobs to today/this week and refreshes activity logs
  app.post("/api/admin/refresh-demo-screenshots", requireAuth, async (req: any, res) => {
    try {
      const { refreshDemoDataForScreenshots, DEMO_USER, createDemoActivityLogs } = await import('./demoData');
      
      // Only allow demo user to refresh their data
      const user = await storage.getUser(req.userId);
      if (!user || user.email !== DEMO_USER.email) {
        return res.status(403).json({ error: 'Only the demo account can refresh demo data for screenshots' });
      }
      
      const result = await refreshDemoDataForScreenshots();
      
      if (!result.success) {
        return res.status(500).json({ error: result.message });
      }

      try {
        const demoJobs = await storage.getJobs(req.userId!);
        for (const job of demoJobs) {
          const existingTokens = await storage.getJobPortalTokensByJobId(job.id);
          const hasActive = existingTokens?.some((t: any) => !t.revokedAt && (!t.expiresAt || new Date(t.expiresAt) > new Date()));
          if (!hasActive) {
            const cryptoMod = await import('crypto');
            const token = cryptoMod.randomBytes(32).toString('hex');
            await storage.createJobPortalToken({
              jobId: job.id,
              userId: req.userId!,
              token,
              expiresAt: new Date(Date.now() + 365 * 24 * 60 * 60 * 1000),
              createdBy: req.userId!,
            });
          }
        }
        console.log('Portal tokens created for demo jobs');
      } catch (e) {
        console.error('Failed to create portal tokens for demo jobs:', e);
      }
      
      res.json({
        success: true,
        message: result.message,
        updated: result.updated,
        instructions: 'Pull down to refresh on the home screen to see updated jobs and activity.'
      });
    } catch (error: any) {
      console.error("Error refreshing demo data for screenshots:", error);
      res.status(500).json({ error: error.message || "Failed to refresh demo data" });
    }
  });

  app.post("/api/onboarding/complete", requireAuth, ownerOnly(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      let settings = await storage.getBusinessSettings(userId);
      const wasAlreadyCompleted = !!settings?.onboardingCompleted;
      if (settings) {
        settings = await storage.updateBusinessSettings(userId, { onboardingCompleted: true });
      } else {
        settings = await storage.createBusinessSettings({
          userId,
          businessName: '',
          onboardingCompleted: true,
        });
      }

      // Send the welcome email the first time onboarding is completed (it is
      // deliberately NOT sent at signup / email verification anymore). This
      // route is ownerOnly(), so the welcome only goes to business owners —
      // which is intended: the email is owner-centric (set up business, add a
      // client, create a quote, get paid) and is not relevant to invited
      // workers/subcontractors. Non-blocking; never fail the request on an
      // email error.
      if (!wasAlreadyCompleted) {
        (async () => {
          try {
            const user = await storage.getUser(userId);
            if (user?.email) {
              await sendWelcomeEmail(
                { email: user.email, firstName: user.firstName, lastName: user.lastName },
                settings?.businessName || undefined,
              );
            }
          } catch (welcomeEmailError) {
            console.error('[Onboarding Complete] Failed to send welcome email:', welcomeEmailError);
          }
        })();
      }

      res.json({ success: true });
    } catch (error) {
      console.error('[Onboarding Complete] Error:', error);
      res.status(500).json({ error: 'Failed to complete onboarding' });
    }
  });

