  // Get team member availability (active timers + upcoming jobs)
  app.get("/api/team/members/availability", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const canManage = userContext.isOwner || userContext.permissions.includes('view_all');
      if (!canManage) {
        return res.status(403).json({ error: "Only owners and managers can view team availability" });
      }

      const teamMembers = await storage.getTeamMembers(userContext.effectiveUserId);
      const now = new Date();
      const twoHoursFromNow = new Date(now.getTime() + 2 * 60 * 60 * 1000);
      // Allow the caller to specify a date for leave-overlap checking (e.g. the job's scheduledAt).
      // Falls back to today when omitted so the existing behaviour is preserved.
      const targetDateStr: string = (req.query.date as string) || now.toISOString().slice(0, 10);

      const availability: any[] = [];

      for (const member of teamMembers) {
        if (member.inviteStatus !== 'accepted') continue;
        const memberId = member.memberId || member.id;

        let activeTimer: any = null;
        let activeJobTitle: string | null = null;
        let timerStartTime: string | null = null;

        try {
          const timer = await storage.getActiveTimeEntry(memberId);
          if (timer) {
            activeTimer = timer;
            timerStartTime = timer.startTime ? new Date(timer.startTime).toISOString() : null;
            if (timer.jobId) {
              const activeJob = await storage.getJobPublic(timer.jobId);
              activeJobTitle = activeJob?.title || null;
            }
          }
        } catch (e) {}

        let nextScheduledJob: any = null;
        try {
          const memberJobs = await storage.getJobs(memberId);
          const upcoming = memberJobs
            .filter((j: any) => {
              const scheduledDate = (j as any).scheduledDate || (j as any).scheduledAt;
              if (!scheduledDate) return false;
              const sd = new Date(scheduledDate);
              return sd >= now && sd <= twoHoursFromNow &&
                ['scheduled', 'pending'].includes(j.status) &&
                (j.assignedTo === memberId);
            })
            .sort((a: any, b: any) => {
              const aD = new Date((a as any).scheduledDate || (a as any).scheduledAt);
              const bD = new Date((b as any).scheduledDate || (b as any).scheduledAt);
              return aD.getTime() - bD.getTime();
            });

          if (upcoming.length > 0) {
            const nj = upcoming[0];
            nextScheduledJob = {
              id: nj.id,
              title: nj.title,
              scheduledDate: (nj as any).scheduledDate || (nj as any).scheduledAt,
            };
          }
        } catch (e) {}

        let status: 'available' | 'on_job' | 'upcoming' | 'on_leave' = 'available';
        if (activeTimer) status = 'on_job';
        else if (nextScheduledJob) status = 'upcoming';

        // Check for approved leave covering the target date (defaults to today)
        let onLeave = false;
        let leaveType: string | null = null;
        let leaveStartDate: string | null = null;
        let leaveEndDate: string | null = null;
        try {
          const [leaveRecord] = await db.select().from(teamMemberTimeOff)
            .where(
              and(
                eq(teamMemberTimeOff.teamMemberId, member.id),
                eq(teamMemberTimeOff.status, 'approved'),
                lte(teamMemberTimeOff.startDate, targetDateStr),
                gte(teamMemberTimeOff.endDate, targetDateStr),
              )
            )
            .limit(1);
          if (leaveRecord) {
            onLeave = true;
            leaveType = leaveRecord.reason || null;
            leaveStartDate = leaveRecord.startDate || null;
            leaveEndDate = leaveRecord.endDate || null;
            if (status === 'available') status = 'on_leave';
          }
        } catch (e) {}

        let workerState = null;
        try {
          workerState = await storage.getWorkerState(memberId, userContext.effectiveUserId);
        } catch (e) {}

        availability.push({
          memberId,
          status,
          onLeave,
          leaveType,
          leaveStartDate,
          leaveEndDate,
          workerState: workerState?.state || 'available',
          workerStateNote: workerState?.note || null,
          workerStateJobId: workerState?.jobId || null,
          activeJobTitle,
          timerStartTime,
          nextScheduledJob,
        });
      }

      res.json(availability);
    } catch (error: any) {
      console.error("Error fetching team availability:", error);
      res.status(500).json({ error: error.message || "Failed to fetch availability" });
    }
  });

