  app.get("/api/dispatch/board", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId;
      const allJobs = await storage.getJobs(userId);
      const activeJobs = allJobs.filter((j: any) => 
        !['completed', 'cancelled', 'archived', 'done'].includes(j.status?.toLowerCase() || '')
      );
      
      const dispatchData = await Promise.all(activeJobs.map(async (job: any) => {
        const assignments = await storage.getJobAssignments(job.id);
        const activeAssignments = assignments.filter((a: any) => a.isActive);
        
        const assignmentsWithLocation = await Promise.all(activeAssignments.map(async (assignment: any) => {
          let latestPing = null;
          if (assignment.assignmentStatus === 'en_route') {
            latestPing = await storage.getLatestLocationPing(assignment.id);
          }
          return {
            ...assignment,
            latestPing,
          };
        }));
        
        let client = null;
        if (job.clientId) {
          client = await storage.getClientById(job.clientId);
        }
        
        return {
          ...job,
          client: client ? { id: client.id, name: client.name, phone: client.phone } : null,
          assignments: assignmentsWithLocation,
        };
      }));
      
      res.json(dispatchData);
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Failed to get dispatch board data' });
    }
  });

  app.get("/api/dispatch/resources", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const allJobs = await storage.getJobs(userId);
      const now = new Date();
      const todayStr = now.toISOString().split('T')[0];

      const activeJobs = allJobs.filter((j: any) => {
        const status = (j.status || '').toLowerCase();
        if (['done', 'completed', 'cancelled', 'archived'].includes(status)) return false;
        if (!j.scheduledAt) return status === 'in_progress';
        return new Date(j.scheduledAt).toISOString().split('T')[0] === todayStr || status === 'in_progress';
      });

      const equipmentAssignments: any[] = [];
      const materialsNeeded: any[] = [];

      for (const job of activeJobs) {
        const eqList = await storage.getJobEquipment(job.id);
        for (const eq of eqList) {
          equipmentAssignments.push({
            ...eq,
            jobTitle: job.title,
            jobStatus: job.status,
          });
        }

        const mats = await storage.getJobMaterials(job.id, userId);
        for (const mat of mats) {
          if (['needed', 'ordered', 'shipped'].includes(mat.status ?? '')) {
            materialsNeeded.push({
              id: mat.id,
              name: mat.name,
              quantity: mat.quantity,
              unit: mat.unit,
              status: mat.status,
              supplier: mat.supplier,
              jobId: job.id,
              jobTitle: job.title,
            });
          }
        }
      }

      const equipmentList = await storage.getEquipment(userId);
      const categories = await storage.getEquipmentCategories(userId);
      const teamMembers = await storage.getTeamMembers(userId);

      const deployedEquipmentIds = new Set(equipmentAssignments.map((a: any) => a.equipmentId));

      const deployedEquipment = equipmentAssignments.map((a: any) => {
        const eq = equipmentList.find((e: any) => e.id === a.equipmentId);
        return {
          assignmentId: a.id,
          equipmentId: a.equipmentId,
          equipmentName: eq?.name || 'Unknown',
          category: eq?.categoryId ? (categories.find((c: any) => c.id === eq.categoryId)?.name || '') : '',
          categoryId: eq?.categoryId || null,
          serialNumber: eq?.serialNumber || '',
          model: eq?.model || '',
          manufacturer: eq?.manufacturer || '',
          jobId: a.jobId,
          jobTitle: a.jobTitle,
          jobStatus: a.jobStatus,
          notes: a.notes,
          assignedToName: (() => {
            if (!eq?.assignedTo) return null;
            const member = teamMembers.find((m: any) => m.memberId === eq.assignedTo || m.id === eq.assignedTo);
            return member ? `${member.firstName || ''} ${member.lastName || ''}`.trim() : null;
          })(),
        };
      });

      const allEquipment = equipmentList.map((eq: any) => {
        const cat = eq.categoryId ? categories.find((c: any) => c.id === eq.categoryId) : null;
        const isDeployed = deployedEquipmentIds.has(eq.id);
        const assignment = isDeployed ? equipmentAssignments.find((a: any) => a.equipmentId === eq.id) : null;
        const assignedMember = eq.assignedTo ? teamMembers.find((m: any) => m.memberId === eq.assignedTo || m.id === eq.assignedTo) : null;
        return {
          id: eq.id,
          name: eq.name,
          description: eq.description || '',
          model: eq.model || '',
          serialNumber: eq.serialNumber || '',
          manufacturer: eq.manufacturer || '',
          categoryId: eq.categoryId || null,
          categoryName: cat?.name || 'Uncategorized',
          status: eq.status || 'active',
          location: eq.location || '',
          assignedTo: eq.assignedTo || null,
          assignedToName: assignedMember ? `${assignedMember.firstName || ''} ${assignedMember.lastName || ''}`.trim() : null,
          isDeployed,
          deployedJobTitle: assignment?.jobTitle || null,
          deployedJobId: assignment?.jobId || null,
          deployedJobStatus: assignment?.jobStatus || null,
        };
      });

      res.json({
        deployedEquipment,
        allEquipment,
        categories: categories.filter((c: any) => c.isActive !== false).map((c: any) => ({ id: c.id, name: c.name })),
        materialsNeeded,
        totalEquipment: equipmentList.length,
        availableEquipment: equipmentList.filter((e: any) => !deployedEquipmentIds.has(e.id)).length,
      });
    } catch (error: any) {
      console.error("Error fetching dispatch resources:", error);
      res.status(500).json({ error: "Failed to fetch dispatch resources" });
    }
  });

  // Get operational health metrics for the dispatch board
  app.get("/api/ops/health", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = req.userId;
      const effectiveUserId = userContext.effectiveUserId;
      
      const allJobs = await storage.getJobs(effectiveUserId);
      const invoices = await storage.getInvoices(effectiveUserId);
      const teamMembers = await storage.getTeamMembers(effectiveUserId);
      
      const now = new Date();
      const todayStr = now.toISOString().split('T')[0];
      
      const todayJobs = allJobs.filter(j => {
        if (!j.scheduledAt) return false;
        return new Date(j.scheduledAt).toISOString().split('T')[0] === todayStr;
      });
      
      const unassignedJobs = allJobs.filter(j => 
        !j.assignedTo && 
        ['pending', 'scheduled'].includes((j.status || '').toLowerCase())
      ).length;
      
      const overdueJobs = todayJobs.filter(j => {
        if (['done', 'completed', 'invoiced', 'cancelled'].includes((j.status || '').toLowerCase())) return false;
        if (!j.scheduledAt || !j.scheduledTime) return false;
        const scheduledTime = new Date(j.scheduledAt);
        if (j.scheduledTime) {
          const [h, m] = j.scheduledTime.split(':').map(Number);
          scheduledTime.setHours(h || 0, m || 0);
        }
        return scheduledTime < now && (j.status || '').toLowerCase() !== 'in_progress';
      }).length;
      
      const activeMembers = teamMembers.filter((m: any) => m.inviteStatus === 'accepted');
      const memberJobCounts: Record<string, number> = {};
      const memberJobMinutes: Record<string, number> = {};
      todayJobs.forEach(j => {
        const assignee = j.assignedTo || 'owner';
        memberJobCounts[assignee] = (memberJobCounts[assignee] || 0) + 1;
        memberJobMinutes[assignee] = (memberJobMinutes[assignee] || 0) + (j.estimatedDuration || 60);
      });
      
      const overCapacityWorkers = Object.entries(memberJobMinutes).filter(
        ([_, minutes]) => minutes > 480
      ).length;
      
      const conflicts: Array<{ memberId: string; memberName: string; jobs: Array<{ id: string; title: string; time: string }> }> = [];
      
      const memberSchedules: Record<string, Array<{ id: string; title: string; start: Date; end: Date; time: string }>> = {};
      todayJobs.forEach(j => {
        if (!j.scheduledAt || !j.scheduledTime) return;
        const assignee = j.assignedTo || 'owner';
        if (!memberSchedules[assignee]) memberSchedules[assignee] = [];
        
        const start = new Date(j.scheduledAt!);
        if (j.scheduledTime) {
          const [h, m] = j.scheduledTime.split(':').map(Number);
          start.setHours(h || 0, m || 0, 0, 0);
        }
        const end = new Date(start.getTime() + (j.estimatedDuration || 60) * 60 * 1000);
        
        memberSchedules[assignee].push({
          id: j.id,
          title: j.title,
          start,
          end,
          time: j.scheduledTime || 'TBD',
        });
      });
      
      Object.entries(memberSchedules).forEach(([memberId, schedule]) => {
        schedule.sort((a, b) => a.start.getTime() - b.start.getTime());
        const overlaps: Array<{ id: string; title: string; time: string }> = [];
        for (let i = 0; i < schedule.length; i++) {
          for (let k = i + 1; k < schedule.length; k++) {
            if (schedule[i].end > schedule[k].start) {
              if (!overlaps.find(o => o.id === schedule[i].id)) {
                overlaps.push({ id: schedule[i].id, title: schedule[i].title, time: schedule[i].time });
              }
              if (!overlaps.find(o => o.id === schedule[k].id)) {
                overlaps.push({ id: schedule[k].id, title: schedule[k].title, time: schedule[k].time });
              }
            }
          }
        }
        if (overlaps.length > 0) {
          const member = activeMembers.find((m: any) => m.memberId === memberId);
          conflicts.push({
            memberId,
            memberName: member ? `${(member as any).firstName || ''} ${(member as any).lastName || ''}`.trim() : memberId === 'owner' ? 'You' : 'Unknown',
            jobs: overlaps,
          });
        }
      });
      
      const overdueInvoices = invoices.filter((inv: any) => {
        if (!inv.dueDate) return false;
        if (['paid', 'cancelled', 'void'].includes((inv.status || '').toLowerCase())) return false;
        return new Date(inv.dueDate) < now;
      }).length;
      
      const unpaidInvoiceTotal = invoices
        .filter((inv: any) => {
          if (['paid', 'cancelled', 'void', 'draft'].includes((inv.status || '').toLowerCase())) return false;
          return true;
        })
        .reduce((sum: number, inv: any) => sum + (Number(inv.total) || 0), 0);
      
      res.json({
        todayJobCount: todayJobs.length,
        unassignedJobs,
        overdueJobs,
        overCapacityWorkers,
        conflicts,
        conflictCount: conflicts.reduce((sum, c) => sum + c.jobs.length, 0),
        overdueInvoices,
        unpaidInvoiceTotal,
        activeWorkers: activeMembers.length + 1,
        totalSeverity: (conflicts.length > 0 ? 2 : 0) + (overdueJobs > 0 ? 1 : 0) + (unassignedJobs > 3 ? 1 : 0) + (overCapacityWorkers > 0 ? 1 : 0),
      });
    } catch (error: any) {
      res.status(500).json({ error: error.message || 'Failed to get ops health' });
    }
  });

  // ============================================
  // REPORTING & OPS ENDPOINTS
  // ============================================

  app.get("/api/payroll/summary", requireAuth, requirePaidTier(), ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const { start, end, teamMemberId } = req.query;

      const periodStart = start ? new Date(start as string) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
      const periodEnd = end ? new Date(end as string) : new Date();

      const members = await storage.getTeamMembers(ownerId);
      const filteredMembers = teamMemberId
        ? members.filter(m => m.id === teamMemberId)
        : members;

      // Task #271: existing payroll payments for this exact period (paid vs outstanding).
      const periodPayments = await storage.getPayrollPayments(ownerId, { start: periodStart, end: periodEnd });
      const paymentByWorker = new Map<string, typeof periodPayments[number]>();
      for (const p of periodPayments) {
        if (p.workerUserId) paymentByWorker.set(p.workerUserId, p);
      }

      // Fetch travel rate for allowance calculation
      const [bsRow] = await db.select({ travelRatePerKm: businessSettings.travelRatePerKm })
        .from(businessSettings).where(eq(businessSettings.userId, ownerId)).limit(1);
      const travelRatePerKm = parseFloat(bsRow?.travelRatePerKm || '0') || 0;

      const workerSummaries = [];
      let totalPayAll = 0;
      let totalHoursAll = 0;
      let totalPaidAll = 0;
      let totalOutstandingAll = 0;
      let totalTravelAllowanceAll = 0;

      for (const member of filteredMembers) {
        if (!member.memberId) continue;

        const entries = await db.select().from(timeEntries)
          .where(and(
            eq(timeEntries.userId, member.memberId),
            gte(timeEntries.startTime, periodStart),
            lte(timeEntries.startTime, periodEnd),
            isNotNull(timeEntries.endTime)
          ));

        const rate = parseFloat(member.hourlyRate || '0') || 0;

        let regularMins = 0, overtimeMins = 0, breakMins = 0, billableMins = 0, nonBillableMins = 0;
        let totalDistanceKm = 0;
        const jobIdSet = new Set<string>();
        const categories: Record<string, number> = {};

        for (const e of entries) {
          const dur = e.duration || 0;
          if (e.isBreak) {
            breakMins += dur;
            continue;
          }
          if (e.isOvertime) {
            overtimeMins += dur;
          } else {
            regularMins += dur;
          }
          if (e.isBillable) billableMins += dur;
          else nonBillableMins += dur;
          if (e.jobId) jobIdSet.add(e.jobId);
          const cat = e.timeCategory || 'work';
          categories[cat] = (categories[cat] || 0) + dur;
          // Accumulate driving distance for travel allowance
          if (cat === 'travel' && e.distanceKm) {
            totalDistanceKm += parseFloat(String(e.distanceKm)) || 0;
          }
        }

        const regularHrs = regularMins / 60;
        const overtimeHrs = overtimeMins / 60;
        const breakHrs = breakMins / 60;
        const totalHrs = regularHrs + overtimeHrs;
        const grossPay = (regularHrs * rate) + (overtimeHrs * rate * 1.5);
        const travelAllowance = Math.round(totalDistanceKm * travelRatePerKm * 100) / 100;

        const role = await db.select().from(userRoles).where(eq(userRoles.id, member.roleId)).limit(1);
        const isSubcontractor = role[0]?.name?.toLowerCase().includes('subcontractor') || false;

        totalPayAll += grossPay;
        totalHoursAll += totalHrs;
        totalTravelAllowanceAll += travelAllowance;

        const roundedGross = Math.round(grossPay * 100) / 100;
        const payment = paymentByWorker.get(member.memberId);
        if (payment) totalPaidAll += roundedGross;
        else totalOutstandingAll += roundedGross;

        workerSummaries.push({
          teamMemberId: member.id,
          memberId: member.memberId,
          firstName: member.firstName,
          lastName: member.lastName,
          email: member.email,
          hourlyRate: rate,
          isSubcontractor,
          regularHours: Math.round(regularHrs * 100) / 100,
          overtimeHours: Math.round(overtimeHrs * 100) / 100,
          breakHours: Math.round(breakHrs * 100) / 100,
          totalHours: Math.round(totalHrs * 100) / 100,
          billableHours: Math.round(billableMins / 60 * 100) / 100,
          nonBillableHours: Math.round(nonBillableMins / 60 * 100) / 100,
          grossPay: roundedGross,
          overtimePay: Math.round(overtimeHrs * rate * 1.5 * 100) / 100,
          travelAllowance,
          totalDistanceKm: Math.round(totalDistanceKm * 10) / 10,
          jobCount: jobIdSet.size,
          timeCategories: Object.fromEntries(Object.entries(categories).map(([k, v]) => [k, Math.round(v / 60 * 100) / 100])),
          entryCount: entries.filter(e => !e.isBreak).length,
          approved: entries.filter(e => e.approved).length,
          unapproved: entries.filter(e => !e.approved).length,
          paid: !!payment,
          paidAt: payment?.paidAt ? new Date(payment.paidAt).toISOString() : null,
          payrollPaymentId: payment?.id || null,
          paidMethod: payment?.method || null,
          paidReference: payment?.reference || null,
        });
      }

      res.json({
        period: { start: periodStart.toISOString(), end: periodEnd.toISOString() },
        workers: workerSummaries,
        travelRatePerKm,
        totals: {
          totalHours: Math.round(totalHoursAll * 100) / 100,
          totalPay: Math.round(totalPayAll * 100) / 100,
          totalPaid: Math.round(totalPaidAll * 100) / 100,
          totalOutstanding: Math.round(totalOutstandingAll * 100) / 100,
          totalTravelAllowance: Math.round(totalTravelAllowanceAll * 100) / 100,
          paidCount: workerSummaries.filter(w => w.paid).length,
          outstandingCount: workerSummaries.filter(w => !w.paid).length,
          workerCount: workerSummaries.length,
          subcontractorCount: workerSummaries.filter(w => w.isSubcontractor).length,
        }
      });
    } catch (error: any) {
      console.error('[Payroll] Error:', error);
      res.status(500).json({ error: "Failed to generate payroll summary" });
    }
  });

  // Task #271: record a payroll payment for one worker for a period + email payslip.
  app.post("/api/payroll/pay", requireAuth, requirePaidTier(), ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const {
        workerUserId, periodStart, periodEnd,
        regularHours, overtimeHours, totalHours, grossPay,
        method, reference, notes, paidAt, sendPayslip,
      } = req.body || {};

      if (!workerUserId || !periodStart || !periodEnd) {
        return res.status(400).json({ error: 'workerUserId, periodStart and periodEnd are required' });
      }

      const pStart = new Date(periodStart);
      const pEnd = new Date(periodEnd);

      // The worker must be an active member of this business.
      const membership = await db.select().from(teamMembers)
        .where(and(eq(teamMembers.memberId, workerUserId), eq(teamMembers.businessOwnerId, ownerId), eq(teamMembers.isActive, true)))
        .limit(1);
      if (membership.length === 0) {
        return res.status(403).json({ error: 'Worker is not a member of this business' });
      }

      // Recompute gross server-side from time entries so the client can't dictate the amount.
      const member = membership[0];
      const rate = parseFloat(member.hourlyRate || '0') || 0;
      const entries = await db.select().from(timeEntries)
        .where(and(
          eq(timeEntries.userId, workerUserId),
          gte(timeEntries.startTime, pStart),
          lte(timeEntries.startTime, pEnd),
          isNotNull(timeEntries.endTime)
        ));
      let regMins = 0, otMins = 0;
      let totalDistanceKmPay = 0;
      for (const e of entries) {
        if (e.isBreak) continue;
        if (e.isOvertime) otMins += (e.duration || 0);
        else regMins += (e.duration || 0);
        if ((e.timeCategory || 'work') === 'travel' && e.distanceKm) {
          totalDistanceKmPay += parseFloat(String(e.distanceKm)) || 0;
        }
      }
      const regHrs = regMins / 60;
      const otHrs = otMins / 60;
      const computedGross = Math.round(((regHrs * rate) + (otHrs * rate * 1.5)) * 100) / 100;
      const [bsRowPay] = await db.select({ travelRatePerKm: businessSettings.travelRatePerKm })
        .from(businessSettings).where(eq(businessSettings.userId, ownerId)).limit(1);
      const travelRatePerKmPay = parseFloat(bsRowPay?.travelRatePerKm || '0') || 0;
      const travelAllowancePay = Math.round(totalDistanceKmPay * travelRatePerKmPay * 100) / 100;
      const totalDistanceKmPayRounded = Math.round(totalDistanceKmPay * 10) / 10;

      // Prevent double-paying the same worker for the same period.
      const existing = await storage.getPayrollPayments(ownerId, { start: pStart, end: pEnd, workerUserId });
      if (existing.length > 0) {
        return res.status(409).json({ error: 'This worker has already been paid for this period', payment: existing[0] });
      }

      let payment;
      try {
        payment = await storage.createPayrollPayment({
          businessOwnerId: ownerId,
          workerUserId,
          periodStart: pStart,
          periodEnd: pEnd,
          regularHours: (Math.round(regHrs * 100) / 100).toFixed(2),
          overtimeHours: (Math.round(otHrs * 100) / 100).toFixed(2),
          totalHours: (Math.round((regHrs + otHrs) * 100) / 100).toFixed(2),
          grossPay: computedGross.toFixed(2),
          // Lock in travel snapshot so regenerated payslips are always consistent.
          travelAllowance: travelAllowancePay.toFixed(2),
          totalDistanceKm: (Math.round(totalDistanceKmPay * 100) / 100).toFixed(2),
          travelRatePerKm: travelRatePerKmPay.toFixed(4),
          method: typeof method === 'string' && method ? method : 'bank_transfer',
          reference: typeof reference === 'string' && reference.trim() ? reference.trim() : null,
          notes: typeof notes === 'string' && notes.trim() ? notes.trim() : null,
          paidAt: paidAt ? new Date(paidAt) : new Date(),
        });
      } catch (insertErr: any) {
        // Unique guard (uq_payroll_payments_worker_period) — concurrent double-pay race.
        if (insertErr?.code === '23505') {
          const dup = await storage.getPayrollPayments(ownerId, { start: pStart, end: pEnd, workerUserId });
          return res.status(409).json({ error: 'This worker has already been paid for this period', payment: dup[0] });
        }
        throw insertErr;
      }

      let payslipSent = false;
      if (sendPayslip !== false) {
        try {
          const worker = await storage.getUser(workerUserId);
          if (worker?.email) {
            const { sendSystemEmail } = await import('./emailService');
            const { generateRemittancePdf } = await import('./pdfService');
            const bizSettings = await storage.getBusinessSettings(ownerId);
            const workerName = `${worker.firstName || ''} ${worker.lastName || ''}`.trim() || worker.email;
            const payslipTotal = Math.round((computedGross + travelAllowancePay) * 100) / 100;
            const pdfBuffer = await generateRemittancePdf({
              type: 'payslip',
              business: {
                name: bizSettings?.businessName || 'Business',
                abn: bizSettings?.abn || null,
                address: bizSettings?.address || null,
                email: bizSettings?.email || null,
                phone: bizSettings?.phone || null,
              },
              payee: { name: workerName, abn: null, email: worker.email },
              paymentDate: payment.paidAt,
              method: payment.method,
              reference: payment.reference,
              notes: payment.notes,
              periodStart: pStart,
              periodEnd: pEnd,
              lines: [
                { label: `Regular (${(Math.round(regHrs * 100) / 100).toFixed(2)} hrs @ $${rate.toFixed(2)})`, value: (Math.round(regHrs * rate * 100) / 100).toFixed(2), isMoney: true },
                ...(otHrs > 0 ? [{ label: `Overtime (${(Math.round(otHrs * 100) / 100).toFixed(2)} hrs @ $${(rate * 1.5).toFixed(2)})`, value: (Math.round(otHrs * rate * 1.5 * 100) / 100).toFixed(2), isMoney: true }] : []),
                ...(travelAllowancePay > 0 ? [{ label: `Travel Allowance (${totalDistanceKmPayRounded} km @ $${travelRatePerKmPay.toFixed(2)}/km)`, value: travelAllowancePay.toFixed(2), isMoney: true }] : []),
              ],
              total: payslipTotal.toFixed(2),
            });
            await sendSystemEmail({
              to: worker.email,
              subject: `Payslip — ${pStart.toLocaleDateString('en-AU')} to ${pEnd.toLocaleDateString('en-AU')}`,
              html: `
                <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
                  <h2>You've been paid</h2>
                  <p>Your pay of <strong>$${payslipTotal.toFixed(2)}</strong> for the period ${pStart.toLocaleDateString('en-AU')} – ${pEnd.toLocaleDateString('en-AU')} has been processed.</p>
                  ${travelAllowancePay > 0 ? `<p>This includes a travel allowance of <strong>$${travelAllowancePay.toFixed(2)}</strong> for ${totalDistanceKmPayRounded} km travelled.</p>` : ''}
                  <p>Your payslip is attached.</p>
                </div>
              `,
              attachments: [{
                content: pdfBuffer.toString('base64'),
                filename: `Payslip-${pStart.toISOString().split('T')[0]}.pdf`,
                type: 'application/pdf',
                disposition: 'attachment',
              }],
            });
            payslipSent = true;
            await storage.updatePayrollPayment(payment.id, { remittanceSentAt: new Date() });
          }
        } catch (e) {
          console.warn('[Payroll Pay] Payslip email error:', e);
        }
      }

      const totalPaid = Math.round((computedGross + travelAllowancePay) * 100) / 100;
      try {
        const payslipTotalNotif = Math.round((computedGross + travelAllowancePay) * 100) / 100;
        await storage.createNotification({
          userId: workerUserId,
          type: 'payroll_paid',
          title: 'You have been paid',
          message: `Pay of $${payslipTotalNotif.toFixed(2)} has been processed`,
          relatedType: 'payroll_payment',
          relatedId: payment.id,
          priority: 'important',
        });
      } catch (e) {
        console.warn('[Payroll Pay] Notification error:', e);
      }

      res.json({ ...payment, payslipSent, totalPaid: totalPaid.toFixed(2) });
    } catch (error) {
      console.error('[Payroll Pay] Error:', error);
      res.status(500).json({ error: 'Failed to record payroll payment' });
    }
  });

  // GET /api/payroll/payslip/:id — payslip PDF for a recorded payroll payment.
  app.get("/api/payroll/payslip/:id", requireAuth, async (req: any, res) => {
    try {
      const ctx = await getUserContext(req.userId);
      const payment = await storage.getPayrollPayment(req.params.id);
      if (!payment) return res.status(404).json({ error: 'Payment not found' });
      if (payment.businessOwnerId !== ctx.effectiveUserId && payment.workerUserId !== req.userId) {
        return res.status(403).json({ error: 'Access denied' });
      }

      const worker = await storage.getUser(payment.workerUserId);
      const bizSettings = await storage.getBusinessSettings(payment.businessOwnerId);
      const workerName = worker ? (`${worker.firstName || ''} ${worker.lastName || ''}`.trim() || worker.email || 'Worker') : 'Worker';
      const regHrs = parseFloat(payment.regularHours);
      const otHrs = parseFloat(payment.overtimeHours);
      const grossWages = parseFloat(payment.grossPay);
      const rate = (regHrs + otHrs * 1.5) > 0
        ? Math.round((grossWages / (regHrs + otHrs * 1.5)) * 100) / 100
        : 0;

      // Use the locked-in travel snapshot from payment time (never recompute from
      // current entries or business rate — that would produce different amounts).
      const travelAllowanceSlip = parseFloat(payment.travelAllowance || '0');
      const travelDistanceKmSlip = Math.round(parseFloat(payment.totalDistanceKm || '0') * 10) / 10;
      const travelRatePerKmSlip = parseFloat(payment.travelRatePerKm || '0');
      const payslipTotalSlip = Math.round((grossWages + travelAllowanceSlip) * 100) / 100;

      const { generateRemittancePdf } = await import('./pdfService');
      const pdfBuffer = await generateRemittancePdf({
        type: 'payslip',
        business: {
          name: bizSettings?.businessName || 'Business',
          abn: bizSettings?.abn || null,
          address: bizSettings?.address || null,
          email: bizSettings?.email || null,
          phone: bizSettings?.phone || null,
        },
        payee: { name: workerName, abn: null, email: worker?.email || null },
        paymentDate: payment.paidAt,
        method: payment.method,
        reference: payment.reference,
        notes: payment.notes,
        periodStart: payment.periodStart,
        periodEnd: payment.periodEnd,
        lines: [
          { label: `Regular (${regHrs.toFixed(2)} hrs @ $${rate.toFixed(2)})`, value: (Math.round(regHrs * rate * 100) / 100).toFixed(2), isMoney: true },
          ...(otHrs > 0 ? [{ label: `Overtime (${otHrs.toFixed(2)} hrs @ $${(rate * 1.5).toFixed(2)})`, value: (Math.round(otHrs * rate * 1.5 * 100) / 100).toFixed(2), isMoney: true }] : []),
          ...(travelAllowanceSlip > 0 ? [{ label: `Travel Allowance (${travelDistanceKmSlip} km @ $${travelRatePerKmSlip.toFixed(2)}/km)`, value: travelAllowanceSlip.toFixed(2), isMoney: true }] : []),
        ],
        total: payslipTotalSlip.toFixed(2),
      });

      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `inline; filename="Payslip-${new Date(payment.periodStart).toISOString().split('T')[0]}.pdf"`);
      res.send(pdfBuffer);
    } catch (error) {
      console.error('[Payroll Payslip] Error:', error);
      res.status(500).json({ error: 'Failed to generate payslip' });
    }
  });

  app.get("/api/reports/receivables", requireAuth, requirePaidTier(), ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const asOf = req.query.asOf ? new Date(req.query.asOf as string) : new Date();

      const allInvoices = await db.select().from(invoices)
        .where(and(
          eq(invoices.userId, ownerId),
          inArray(invoices.status, ['sent', 'overdue'])
        ));

      const buckets = {
        current: { count: 0, total: 0, invoices: [] as any[] },
        '1-30': { count: 0, total: 0, invoices: [] as any[] },
        '31-60': { count: 0, total: 0, invoices: [] as any[] },
        '61-90': { count: 0, total: 0, invoices: [] as any[] },
        '90+': { count: 0, total: 0, invoices: [] as any[] },
      };

      const clientTotals: Record<string, { clientId: string, clientName: string, total: number, count: number }> = {};

      for (const inv of allInvoices) {
        const total = parseFloat(inv.total || '0');
        const dueDate = inv.dueDate ? new Date(inv.dueDate) : null;
        const daysOverdue = dueDate ? Math.floor((asOf.getTime() - dueDate.getTime()) / (1000 * 60 * 60 * 24)) : 0;

        const client = await db.select().from(clients).where(eq(clients.id, inv.clientId)).limit(1);
        const clientName = client[0]?.name || 'Unknown';

        const invSummary = {
          id: inv.id,
          number: inv.number,
          title: inv.title,
          clientId: inv.clientId,
          clientName,
          total,
          dueDate: dueDate?.toISOString(),
          daysOverdue: Math.max(0, daysOverdue),
          sentAt: inv.sentAt,
        };

        let bucket: keyof typeof buckets;
        if (daysOverdue <= 0) bucket = 'current';
        else if (daysOverdue <= 30) bucket = '1-30';
        else if (daysOverdue <= 60) bucket = '31-60';
        else if (daysOverdue <= 90) bucket = '61-90';
        else bucket = '90+';

        buckets[bucket].count++;
        buckets[bucket].total = Math.round((buckets[bucket].total + total) * 100) / 100;
        buckets[bucket].invoices.push(invSummary);

        if (!clientTotals[inv.clientId]) {
          clientTotals[inv.clientId] = { clientId: inv.clientId, clientName, total: 0, count: 0 };
        }
        clientTotals[inv.clientId].total = Math.round((clientTotals[inv.clientId].total + total) * 100) / 100;
        clientTotals[inv.clientId].count++;
      }

      const grandTotal = Object.values(buckets).reduce((sum, b) => sum + b.total, 0);

      res.json({
        asOf: asOf.toISOString(),
        buckets,
        clientBreakdown: Object.values(clientTotals).sort((a, b) => b.total - a.total),
        grandTotal: Math.round(grandTotal * 100) / 100,
        invoiceCount: allInvoices.length,
      });
    } catch (error: any) {
      console.error('[Receivables] Error:', error);
      res.status(500).json({ error: "Failed to generate receivables report" });
    }
  });

  app.get("/api/reports/utilisation", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const periodStart = req.query.start ? new Date(req.query.start as string) : new Date(new Date().setDate(new Date().getDate() - 30));
      const periodEnd = req.query.end ? new Date(req.query.end as string) : new Date();

      const members = await storage.getTeamMembers(ownerId);
      const allJobs = await storage.getJobs(ownerId);

      const workingDays = (() => {
        let count = 0;
        const d = new Date(periodStart);
        while (d <= periodEnd) {
          if (d.getDay() !== 0 && d.getDay() !== 6) count++;
          d.setDate(d.getDate() + 1);
        }
        return count;
      })();

      const DAILY_CAPACITY = 8;
      const totalCapacityHours = workingDays * DAILY_CAPACITY;

      const workerStats = [];

      for (const member of members) {
        if (!member.memberId) continue;
        if (req.query.teamMemberId && member.id !== req.query.teamMemberId) continue;

        const entries = await db.select().from(timeEntries)
          .where(and(
            eq(timeEntries.userId, member.memberId),
            gte(timeEntries.startTime, periodStart),
            lte(timeEntries.startTime, periodEnd),
            isNotNull(timeEntries.endTime)
          ));

        const workedMins = entries.filter(e => !e.isBreak).reduce((sum, e) => sum + (e.duration || 0), 0);
        const billableMins = entries.filter(e => !e.isBreak && e.isBillable).reduce((sum, e) => sum + (e.duration || 0), 0);
        const workedHours = workedMins / 60;
        const billableHours = billableMins / 60;

        const utilisation = totalCapacityHours > 0 ? (workedHours / totalCapacityHours) * 100 : 0;
        const billableUtil = totalCapacityHours > 0 ? (billableHours / totalCapacityHours) * 100 : 0;

        const memberJobs = allJobs.filter(j =>
          j.assignedTo === member.memberId &&
          j.completedAt &&
          new Date(j.completedAt) >= periodStart &&
          new Date(j.completedAt) <= periodEnd
        );

        const jobIds = memberJobs.map(j => j.id);
        let revenue = 0;
        if (jobIds.length > 0) {
          const invs = await db.select().from(invoices)
            .where(and(
              eq(invoices.userId, ownerId),
              inArray(invoices.jobId, jobIds),
              eq(invoices.status, 'paid')
            ));
          revenue = invs.reduce((sum, inv) => sum + parseFloat(inv.total || '0'), 0);
        }

        const rate = parseFloat(member.hourlyRate || '0') || 0;
        const labourCost = workedHours * rate;

        workerStats.push({
          teamMemberId: member.id,
          memberId: member.memberId,
          firstName: member.firstName,
          lastName: member.lastName,
          hoursWorked: Math.round(workedHours * 100) / 100,
          billableHours: Math.round(billableHours * 100) / 100,
          capacityHours: totalCapacityHours,
          utilisation: Math.round(utilisation * 10) / 10,
          billableUtilisation: Math.round(billableUtil * 10) / 10,
          jobsCompleted: memberJobs.length,
          revenue: Math.round(revenue * 100) / 100,
          labourCost: Math.round(labourCost * 100) / 100,
          revenuePerHour: workedHours > 0 ? Math.round((revenue / workedHours) * 100) / 100 : 0,
          idleHours: Math.max(0, Math.round((totalCapacityHours - workedHours) * 100) / 100),
        });
      }

      const avgUtilisation = workerStats.length > 0
        ? workerStats.reduce((sum, w) => sum + w.utilisation, 0) / workerStats.length : 0;

      res.json({
        period: { start: periodStart.toISOString(), end: periodEnd.toISOString(), workingDays },
        workers: workerStats,
        averageUtilisation: Math.round(avgUtilisation * 10) / 10,
        totalRevenue: Math.round(workerStats.reduce((sum, w) => sum + w.revenue, 0) * 100) / 100,
        totalLabourCost: Math.round(workerStats.reduce((sum, w) => sum + w.labourCost, 0) * 100) / 100,
        totalIdleHours: Math.round(workerStats.reduce((sum, w) => sum + w.idleHours, 0) * 100) / 100,
      });
    } catch (error: any) {
      console.error('[Utilisation] Error:', error);
      res.status(500).json({ error: "Failed to generate utilisation report" });
    }
  });

  app.get("/api/ops/job-aging", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const allJobs = await storage.getJobs(ownerId);
      const now = new Date();

      const thresholds: Record<string, number> = {
        'quoted': 7,
        'scheduled': 3,
        'in_progress': 14,
        'assigned': 2,
      };

      const agingJobs = [];

      for (const job of allJobs) {
        const status = (job.status || '').toLowerCase();
        if (['done', 'completed', 'invoiced', 'cancelled'].includes(status)) continue;

        const updatedAt = job.updatedAt ? new Date(job.updatedAt) : (job.createdAt ? new Date(job.createdAt) : now);
        const daysInStatus = Math.floor((now.getTime() - updatedAt.getTime()) / (1000 * 60 * 60 * 24));

        const threshold = thresholds[status] || 7;

        if (daysInStatus > threshold) {
          let clientName = 'Unknown';
          if (job.clientId) {
            const client = await db.select().from(clients).where(eq(clients.id, job.clientId)).limit(1);
            if (client[0]) clientName = client[0].name || 'Unknown';
          }

          agingJobs.push({
            id: job.id,
            title: job.title,
            status: job.status,
            clientName,
            daysInStatus,
            threshold,
            daysOverThreshold: daysInStatus - threshold,
            severity: daysInStatus > threshold * 2 ? 'critical' : 'warning',
            updatedAt: updatedAt.toISOString(),
            scheduledAt: job.scheduledAt,
          });
        }
      }

      agingJobs.sort((a, b) => b.daysOverThreshold - a.daysOverThreshold);

      res.json({
        agingJobs,
        totalAging: agingJobs.length,
        criticalCount: agingJobs.filter(j => j.severity === 'critical').length,
        warningCount: agingJobs.filter(j => j.severity === 'warning').length,
        thresholds,
      });
    } catch (error: any) {
      console.error('[JobAging] Error:', error);
      res.status(500).json({ error: "Failed to get job aging data" });
    }
  });

  app.get("/api/ops/daily-summary", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const ownerId = userContext.effectiveUserId;
      const date = req.query.date ? new Date(req.query.date as string) : new Date();

      const dayStart = new Date(date);
      dayStart.setHours(0, 0, 0, 0);
      const dayEnd = new Date(date);
      dayEnd.setHours(23, 59, 59, 999);

      const allJobs = await storage.getJobs(ownerId);
      const members = await storage.getTeamMembers(ownerId);
      const allInvoices = await db.select().from(invoices).where(eq(invoices.userId, ownerId));

      const todayJobs = allJobs.filter(j => {
        if (!j.scheduledAt) return false;
        const schedDate = new Date(j.scheduledAt);
        return schedDate >= dayStart && schedDate <= dayEnd;
      });

      const statusCounts: Record<string, number> = {};
      for (const j of todayJobs) {
        const s = j.status || 'unknown';
        statusCounts[s] = (statusCounts[s] || 0) + 1;
      }

      const activeTimers = await db.select().from(timeEntries)
        .where(and(
          isNull(timeEntries.endTime),
          gte(timeEntries.startTime, dayStart)
        ));

      const todayEntries = await db.select().from(timeEntries)
        .where(and(
          gte(timeEntries.startTime, dayStart),
          lte(timeEntries.startTime, dayEnd),
          isNotNull(timeEntries.endTime)
        ));
      const hoursLoggedToday = todayEntries.filter(e => !e.isBreak).reduce((sum, e) => sum + (e.duration || 0), 0) / 60;

      const unpaidInvoices = allInvoices.filter(i => ['sent', 'overdue'].includes(i.status));
      const overdueInvoices = allInvoices.filter(i => i.status === 'overdue' || (i.status === 'sent' && i.dueDate && new Date(i.dueDate) < new Date()));
      const unpaidTotal = unpaidInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);

      const paidToday = allInvoices.filter(i => i.paidAt && new Date(i.paidAt) >= dayStart && new Date(i.paidAt) <= dayEnd);
      const receivedToday = paidToday.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);

      const unassignedJobs = allJobs.filter(j =>
        !j.assignedTo && !['done', 'completed', 'invoiced', 'cancelled'].includes((j.status || '').toLowerCase())
      );

      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
      const allQuotes = await db.select().from(quotes).where(eq(quotes.userId, ownerId));
      const recentQuotes = allQuotes.filter(q => q.createdAt && new Date(q.createdAt) >= thirtyDaysAgo);
      const acceptedQuotes = recentQuotes.filter(q => q.status === 'accepted');
      const quoteConversion = recentQuotes.length > 0 ? Math.round((acceptedQuotes.length / recentQuotes.length) * 100) : 0;

      res.json({
        date: date.toISOString().split('T')[0],
        schedule: {
          totalJobs: todayJobs.length,
          statusBreakdown: statusCounts,
          unassignedJobs: unassignedJobs.length,
        },
        workforce: {
          activeTimers: activeTimers.length,
          hoursLoggedToday: Math.round(hoursLoggedToday * 100) / 100,
          teamSize: members.filter(m => m.isActive).length,
        },
        financial: {
          unpaidInvoices: unpaidInvoices.length,
          unpaidTotal: Math.round(unpaidTotal * 100) / 100,
          overdueInvoices: overdueInvoices.length,
          receivedToday: Math.round(receivedToday * 100) / 100,
          quoteConversionRate: quoteConversion,
        },
      });
    } catch (error: any) {
      console.error('[DailySummary] Error:', error);
      res.status(500).json({ error: "Failed to generate daily summary" });
    }
  });

  // Send "Running Late" notification to client

  // Smart running late detection — checks if user can make their next scheduled job on time
  app.post("/api/smart-running-late/check", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const { latitude, longitude } = req.body;

      if (!latitude || !longitude) {
        return res.json({ runningLate: false, reason: 'no_gps' });
      }

      // Get today's jobs, find the next upcoming scheduled one
      const allJobs = await storage.getJobs(userContext.effectiveUserId);
      const now = new Date();
      const todayStart = new Date(now);
      todayStart.setHours(0, 0, 0, 0);
      const todayEnd = new Date(now);
      todayEnd.setHours(23, 59, 59, 999);

      const upcomingJobs = allJobs
        .filter((j: any) => {
          if (j.status !== 'scheduled') return false;
          if (!j.scheduledAt) return false;
          const scheduled = new Date(j.scheduledAt);
          return scheduled >= now && scheduled <= todayEnd;
        })
        .sort((a: any, b: any) => new Date(a.scheduledAt!).getTime() - new Date(b.scheduledAt!).getTime());

      if (upcomingJobs.length === 0) {
        return res.json({ runningLate: false, reason: 'no_upcoming_jobs' });
      }

      const nextJob = upcomingJobs[0];
      const scheduledTime = new Date(nextJob.scheduledAt!);
      const minutesUntilJob = (scheduledTime.getTime() - now.getTime()) / 60000;

      // Only check if job is within the next 60 minutes
      if (minutesUntilJob > 60) {
        return res.json({ runningLate: false, reason: 'job_too_far_ahead' });
      }

      // Get job coordinates
      let jobLat = nextJob.latitude ? parseFloat(String(nextJob.latitude)) : null;
      let jobLng = nextJob.longitude ? parseFloat(String(nextJob.longitude)) : null;

      if (!jobLat || !jobLng) {
        if (nextJob.address) {
          const geocoded = await geocodeAddress(nextJob.address);
          if (geocoded) {
            jobLat = geocoded.latitude;
            jobLng = geocoded.longitude;
          }
        }
      }

      if (!jobLat || !jobLng) {
        return res.json({ runningLate: false, reason: 'no_job_coordinates' });
      }

      // Calculate real driving time
      let etaMinutes = 20;
      let distanceKm: number | null = null;

      const routeETA = await calculateRouteETA(
        parseFloat(String(latitude)),
        parseFloat(String(longitude)),
        jobLat,
        jobLng
      );

      if (routeETA) {
        etaMinutes = routeETA.durationMinutes;
        distanceKm = routeETA.distanceKm;
      } else {
        const dist = haversineDistance(
          parseFloat(String(latitude)),
          parseFloat(String(longitude)),
          jobLat,
          jobLng
        );
        distanceKm = Math.round(dist * 10) / 10;
        if (dist <= 5) etaMinutes = Math.max(Math.ceil(dist * 3), 3);
        else if (dist <= 20) etaMinutes = Math.ceil(dist * 2.5);
        else if (dist <= 50) etaMinutes = Math.ceil(dist * 2);
        else etaMinutes = Math.ceil(dist * 1.5);
      }

      // Add 5 minute buffer for parking/setup
      const arrivalMinutes = etaMinutes + 5;
      const willBeLate = arrivalMinutes > minutesUntilJob;

      // Get client info for the notification
      let clientName = 'the client';
      if (nextJob.clientId) {
        const client = await storage.getClient(nextJob.clientId, userContext.effectiveUserId);
        if (client) clientName = client.name || client.email || 'the client';
      }

      res.json({
        runningLate: willBeLate,
        jobId: nextJob.id,
        jobTitle: nextJob.title || 'Upcoming Job',
        jobAddress: nextJob.address,
        scheduledAt: nextJob.scheduledAt,
        minutesUntilJob: Math.round(minutesUntilJob),
        etaMinutes,
        distanceKm,
        clientName,
        lateByMinutes: willBeLate ? Math.round(arrivalMinutes - minutesUntilJob) : 0,
      });
    } catch (error: any) {
      console.error("Error checking running late:", error);
      res.json({ runningLate: false, reason: 'error' });
    }
  });

  // Quick Collect Payment - collect payment at job site without full invoice workflow


  // ============================================
  // WORKER STATUS UPDATE (Uber-style dispatch flow)
