      const pdfBuffer = await generatePDFBuffer(html);
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Quote-Preview.pdf"`);
      res.send(pdfBuffer);
