  // Send invoice via SMS
  app.post("/api/invoices/:id/send-sms", requireAuth, requirePaidTierForSms, messageSendLimiter, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const { sendSmsToClient } = await import('./services/smsService');
      const { smsTemplates } = await import('./twilioClient');
      
      const invoice = await storage.getInvoice(req.params.id, userContext.effectiveUserId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }

      const calcVerification = await verifyInvoiceCalculation(invoice.id, userContext.effectiveUserId, invoice);
      if (!calcVerification.valid) {
        return res.status(400).json({
          error: calcVerification.error,
          details: calcVerification.details
        });
      }
      
      const client = await storage.getClient(invoice.clientId, userContext.effectiveUserId);
      if (!client) {
        return res.status(404).json({ error: "Client not found" });
      }
      
      if (!client.phone) {
        return res.status(400).json({ error: "Client does not have a phone number. Please add a phone number to the client record." });
      }
      
      const businessSettings = await storage.getBusinessSettings(userContext.effectiveUserId);
      const businessName = businessSettings?.businessName || 'Your tradie';
      
      // Ensure invoice has payment token for public link
      let paymentToken = invoice.paymentToken;
      if (!paymentToken) {
        const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789';
        paymentToken = '';
        for (let i = 0; i < 16; i++) {
          paymentToken += chars[randomInt(chars.length)];
        }
        await storage.updateInvoice(req.params.id, userContext.effectiveUserId, { 
          paymentToken,
          allowOnlinePayment: true 
        });
      }
      
      // Build public URL and message
      const publicUrl = `${getProductionBaseUrl(req)}/pay/${paymentToken}`;
      const amount = `$${parseFloat(String(invoice.total || '0')).toFixed(2)}`;
      
      const businessPhone = businessSettings?.phone || undefined;
      const message = `${smsTemplates.invoiceSent(client.name, businessName, invoice.number || invoice.id.slice(0, 8), amount, businessPhone)} ${publicUrl}`;
      
      // Send SMS
      const smsMessage = await sendSmsToClient({
        businessOwnerId: userContext.effectiveUserId,
        clientId: client.id,
        clientPhone: client.phone,
        clientName: client.name,
        jobId: invoice.jobId || undefined,
        message,
        senderUserId: req.userId,
      });
      
      if (smsMessage.status === 'failed') {
        if (/dedicated (phone )?number/i.test(smsMessage.errorMessage || '')) {
          return res.status(402).json({ 
            error: 'Your business needs its own dedicated phone number to send SMS. Purchase one in Phone Numbers.',
            code: 'DEDICATED_NUMBER_REQUIRED',
          });
        }
        return res.status(500).json({ 
          error: smsMessage.errorMessage || 'SMS failed to send',
          notConfigured: smsMessage.errorMessage?.includes('not configured'),
        });
      }
      
      // Update invoice status to sent if it was draft
      if (invoice.status === 'draft') {
        await storage.updateInvoice(req.params.id, userContext.effectiveUserId, {
          status: 'sent',
          sentAt: new Date(),
        });
      }
      
      // Log activity for SMS sent
      await logActivity(
        userContext.effectiveUserId,
        'invoice_sent',
        `Invoice ${invoice.number || invoice.id} sent via SMS`,
        `SMS sent to ${client.name} (${client.phone})`,
        'invoice',
        invoice.id,
        { deliveryMethod: 'sms', clientPhone: client.phone, smsMessageId: smsMessage.id, amount }
      );
      
      try {
        await notifyInvoiceSent(storage, userContext.effectiveUserId, invoice, client.name);
      } catch (notifErr) {
        console.error('Failed to send invoice sent notification:', notifErr);
      }
      
      res.json({ 
        success: true, 
        message: `Invoice SMS sent to ${client.phone}`,
        smsMessageId: smsMessage.id,
        publicUrl,
      });
    } catch (error: any) {
      console.error("Error sending invoice SMS:", error);
      res.status(500).json({ error: error.message || "Failed to send invoice SMS" });
    }
  });

