  // Delete a payment record (void/reverse a payment)
  app.delete("/api/invoices/:id/payments/:paymentId", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const invoice = await storage.getInvoice(req.params.id, userContext.effectiveUserId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }
      
      const records = await storage.getPaymentRecords(req.params.id);
      const record = records.find(r => r.id === req.params.paymentId);
      if (!record) {
        return res.status(404).json({ error: "Payment record not found" });
      }
      
      await storage.deletePaymentRecord(req.params.paymentId);
      
      const deletedAmount = parseFloat(String(record.amount || '0'));
      const previousPaid = parseFloat(String(invoice.amountPaid || '0'));
      const newPaid = Math.max(0, previousPaid - deletedAmount);
      const invoiceTotal = parseFloat(String(invoice.total || '0'));
      const retentionAmount = parseFloat(String(invoice.retentionAmount || '0'));
      const effectiveTotal = invoiceTotal - retentionAmount;
      
      const updateData: any = { amountPaid: newPaid.toFixed(2) };
      if (newPaid <= 0) {
        updateData.status = invoice.sentAt ? 'sent' : 'draft';
        updateData.paidAt = null;
        updateData.lockedAt = null;
        updateData.lockedReason = null;
      } else if (newPaid < effectiveTotal) {
        updateData.status = 'partially_paid';
        updateData.paidAt = null;
        updateData.lockedAt = null;
        updateData.lockedReason = null;
      }
      
      await storage.updateInvoice(req.params.id, userContext.effectiveUserId, updateData);
      
      res.json({ message: `Payment of $${deletedAmount.toFixed(2)} voided`, newAmountPaid: newPaid.toFixed(2) });
    } catch (error) {
      console.error("Error deleting payment record:", error);
      res.status(500).json({ error: "Failed to delete payment record" });
    }
  });

  // Update payment milestones on an invoice
  app.patch("/api/invoices/:id/milestones", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const invoice = await storage.getInvoice(req.params.id, userContext.effectiveUserId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }

      const milestoneItemSchema = z.object({
        name: z.string().min(1).max(200),
        percentage: z.number().min(0).max(100),
        amount: z.union([z.string(), z.number()]).optional(),
        status: z.enum(['pending', 'invoiced', 'paid']).optional(),
        dueDate: z.string().optional().nullable(),
      });
      const milestonesSchema = z.object({
        milestones: z.array(milestoneItemSchema).optional(),
        retentionPercent: z.number().min(0).max(100).optional(),
      });
      const parsed = milestonesSchema.safeParse(req.body);
      if (!parsed.success) {
        return res.status(400).json({ error: 'Invalid milestone data', details: parsed.error.errors });
      }
      const { milestones, retentionPercent } = parsed.data;

      const updateData: any = {};

      if (milestones !== undefined) {
        updateData.paymentMilestones = milestones;
      }

      if (retentionPercent !== undefined) {
        updateData.retentionPercent = retentionPercent.toFixed(2);
        const total = parseFloat(String(invoice.total || '0'));
        updateData.retentionAmount = (total * retentionPercent / 100).toFixed(2);
      }
      
      const updated = await storage.updateInvoice(req.params.id, userContext.effectiveUserId, updateData);
      res.json(updated);
    } catch (error) {
      console.error("Error updating milestones:", error);
      res.status(500).json({ error: "Failed to update milestones" });
    }
  });

  // Record manual payment with details - RESTful alias endpoint
  app.post("/api/invoices/:id/payments", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), handleRecordPayment);
  
  // Record manual payment with details (legacy endpoint)
  app.post("/api/invoices/:id/record-payment", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), handleRecordPayment);

  // Generate labour line items from time tracking data
  app.post("/api/invoices/:id/generate-labour-lines", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const invoiceId = req.params.id;
      const userContext = await getUserContext(req.userId);
      
      const invoice = await storage.getInvoice(invoiceId, userContext.effectiveUserId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }
      
      if (!invoice.jobId) {
        return res.status(400).json({ error: "Invoice must be linked to a job to generate labour lines" });
      }
      
      const { generateLabourLineItems, generateLabourSummary } = await import('./labourService');
      const labourItems = await generateLabourLineItems(invoice.jobId, invoiceId, userContext.effectiveUserId);
      const summary = await generateLabourSummary(invoice.jobId, userContext.effectiveUserId);
      
      const allLineItems = await storage.getInvoiceLineItems(invoiceId);
      const newSubtotal = allLineItems.reduce((sum, item) => sum + parseFloat(item.total || '0'), 0);
      const gstRate = 0.1;
      const gstAmount = Math.round(newSubtotal * gstRate * 100) / 100;
      const newTotal = newSubtotal + gstAmount;

      await storage.updateInvoice(invoiceId, userContext.effectiveUserId, {
        subtotal: String(newSubtotal.toFixed(2)),
        gstAmount: String(gstAmount.toFixed(2)),
        total: String(newTotal.toFixed(2)),
      });

      const updatedInvoice = await storage.getInvoiceWithLineItems(invoiceId, userContext.effectiveUserId);
      
      res.json({ 
        labourItems,
        summary: {
          totalBillableHours: summary.totalBillableHours,
          totalLabourAmount: summary.totalLabourAmount,
          workPeriodStart: summary.workPeriodStart,
          workPeriodEnd: summary.workPeriodEnd,
          workerCount: summary.labourLines.length,
          gpsVerified: summary.gpsVerified,
        },
        invoice: updatedInvoice
      });
    } catch (error: any) {
      console.error("[Generate Labour Lines] Error:", error);
      res.status(500).json({ error: error.message || "Failed to generate labour lines" });
    }
  });

  // Remove labour line items from invoice
  app.delete("/api/invoices/:id/labour-lines", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const invoiceId = req.params.id;
      const userContext = await getUserContext(req.userId);
      
      const invoice = await storage.getInvoice(invoiceId, userContext.effectiveUserId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }
      
      const existingItems = await storage.getInvoiceLineItems(invoiceId);
      const labourItems = existingItems.filter(item => 
        item.description.startsWith('Labour —') || item.description.startsWith('Labour -')
      );
      
      for (const item of labourItems) {
        await storage.deleteInvoiceLineItem(item.id);
      }
      
      const remainingItems = await storage.getInvoiceLineItems(invoiceId);
      const newSubtotal = remainingItems.reduce((sum, item) => sum + parseFloat(item.total || '0'), 0);
      const gstRate = 0.1;
      const gstAmount = Math.round(newSubtotal * gstRate * 100) / 100;
      const newTotal = newSubtotal + gstAmount;
      
      await storage.updateInvoice(invoiceId, userContext.effectiveUserId, {
        subtotal: String(newSubtotal.toFixed(2)),
        gstAmount: String(gstAmount.toFixed(2)),
        total: String(newTotal.toFixed(2)),
      });
      
      res.json({ removed: labourItems.length });
    } catch (error: any) {
      console.error("[Remove Labour Lines] Error:", error);
      res.status(500).json({ error: error.message || "Failed to remove labour lines" });
    }
  });

  // Toggle online payment for invoice
  app.patch("/api/invoices/:id/online-payment", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const { allowOnlinePayment } = req.body;
      
      if (typeof allowOnlinePayment !== 'boolean') {
        return res.status(400).json({ error: "allowOnlinePayment must be a boolean" });
      }
      
      const invoice = await storage.getInvoice(req.params.id, req.userId);
      if (!invoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }
      
      // Check if business has Stripe Connect enabled
      const businessSettings = await storage.getBusinessSettings(req.userId);
      if (!businessSettings?.connectChargesEnabled) {
        return res.status(400).json({ 
          error: "Stripe Connect not enabled. Please connect your Stripe account in Settings first." 
        });
      }
      
      // Generate payment token if enabling online payment and no token exists
      // Uses 12-char alphanumeric for shorter URLs
      let paymentToken = invoice.paymentToken;
      if (allowOnlinePayment && !paymentToken) {
        const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
        paymentToken = '';
        for (let i = 0; i < 12; i++) {
          paymentToken += chars[randomInt(chars.length)];
        }
      }
      
      const updatedInvoice = await storage.updateInvoice(req.params.id, req.userId, {
        allowOnlinePayment,
        paymentToken: allowOnlinePayment ? paymentToken : invoice.paymentToken
      });
      
      if (!updatedInvoice) {
        return res.status(404).json({ error: "Invoice not found" });
      }
      
      res.json(updatedInvoice);
    } catch (error) {
      console.error("Error updating online payment setting:", error);
      res.status(500).json({ error: "Failed to update online payment setting" });
    }
  });

  // PDF Download - Invoice (team-aware)
  app.get("/api/invoices/:id/pdf", requireAuth, pdfPerUserLimiter, createPermissionMiddleware(PERMISSIONS.READ_INVOICES), async (req: any, res) => {
    const invoiceId = req.params.id;
    try {
      const userContext = await getUserContext(req.userId);
      const { generateInvoicePDF, generatePDFBuffer, resolveBusinessLogoForPdf } = await import('./pdfService');
      
      const invoiceWithItems = await storage.getInvoiceWithLineItems(invoiceId, userContext.effectiveUserId);
      if (!invoiceWithItems) {
        console.error(`[Invoice PDF] Invoice not found: ${invoiceId}`);
        return res.status(404).json({ error: "Invoice not found", details: `Invoice ${invoiceId} could not be found` });
      }
      
      const client = await storage.getClient(invoiceWithItems.clientId, userContext.effectiveUserId);
      const business = await storage.getBusinessSettings(userContext.effectiveUserId);
      
      if (!client) {
        console.error(`[Invoice PDF] Client not found for invoice ${invoiceId}, clientId: ${invoiceWithItems.clientId}`);
        return res.status(404).json({ error: "Client not found", details: `Client for invoice ${invoiceId} could not be found` });
      }
      
      if (!business) {
        console.error(`[Invoice PDF] Business settings not found for user ${userContext.effectiveUserId}`);
        return res.status(404).json({ error: "Business settings not found", details: "Please complete your business profile in settings" });
      }
      
      // Get linked job and time entries for site address and time tracking
      let job = undefined;
      let timeEntries: any[] = [];
      try {
        job = invoiceWithItems.jobId ? await storage.getJob(invoiceWithItems.jobId, userContext.effectiveUserId) : undefined;
        timeEntries = invoiceWithItems.jobId ? await storage.getTimeEntries(userContext.effectiveUserId, invoiceWithItems.jobId) : [];
      } catch (jobError) {
        console.warn('[Invoice PDF] Could not fetch job/time entries for invoice %s:', invoiceId, jobError);
      }
      
      let labourSummary: any = null;
      if (invoiceWithItems.jobId) {
        try {
          const { generateLabourSummary } = await import('./labourService');
          labourSummary = await generateLabourSummary(invoiceWithItems.jobId, userContext.effectiveUserId);
          const businessSettingsForProof = await storage.getBusinessSettings(userContext.effectiveUserId);
          if (businessSettingsForProof?.includeLocationProofOnInvoices === false && labourSummary) {
            labourSummary.locationProof = [];
            labourSummary.gpsVerified = false;
            for (const line of labourSummary.labourLines) {
              line.hasGpsProof = false;
              line.attendanceRecords = [];
            }
          }
        } catch (labourError) {
          console.warn('[Invoice PDF] Could not generate labour summary for invoice %s:', invoiceId, labourError);
        }
      }
      
      // Get job signatures if there's a linked job
      let jobSignatures: any[] = [];
      if (invoiceWithItems.jobId) {
        try {
          const signatures = await db.select().from(digitalSignatures).where(eq(digitalSignatures.jobId, invoiceWithItems.jobId));
          jobSignatures = signatures.filter(s => s.documentType === 'job_completion');
        } catch (sigError) {
          console.warn(`[Invoice PDF] Could not fetch signatures for job ${invoiceWithItems.jobId}:`, sigError);
        }
      }
      
      // Fetch assignments for worker timeline
      let assignments: any[] = [];
      if (invoiceWithItems.jobId) {
        try {
          const jobAssignmentsData = await storage.getJobAssignments(invoiceWithItems.jobId);
          assignments = jobAssignmentsData.map(a => ({
            workerName: a.displayName || 'Worker',
            assignmentStatus: a.assignmentStatus || 'assigned',
            travelStartedAt: a.travelStartedAt,
            arrivedAt: a.arrivedAt,
            completedAt: (a as any).completedAt,
          }));
        } catch (assignError) {
          console.warn(`[Invoice PDF] Could not fetch assignments for job ${invoiceWithItems.jobId}:`, assignError);
        }
      }
      
      // Fetch business templates for terms and warranty
      let termsTemplate = undefined;
      let warrantyTemplate = undefined;
      try {
        const termsTemplateResult = await db.select().from(businessTemplates)
          .where(and(
            eq(businessTemplates.userId, userContext.effectiveUserId),
            eq(businessTemplates.family, 'terms_conditions'),
            eq(businessTemplates.isActive, true)
          ))
          .limit(1);
        const warrantyTemplateResult = await db.select().from(businessTemplates)
          .where(and(
            eq(businessTemplates.userId, userContext.effectiveUserId),
            eq(businessTemplates.family, 'warranty'),
            eq(businessTemplates.isActive, true)
          ))
          .limit(1);
        
        termsTemplate = termsTemplateResult[0]?.content;
        warrantyTemplate = warrantyTemplateResult[0]?.content;
      } catch (templateError) {
        console.warn('[Invoice PDF] Could not fetch templates for invoice %s:', invoiceId, templateError);
      }
      
      let beforePhotos: Array<{ url: string; caption?: string; category: string }> | undefined;
      let afterPhotos: Array<{ url: string; caption?: string; category: string }> | undefined;
      if (job) {
        const includeBeforePhotos = req.query.includeBeforePhotos === 'true';
        const includeAfterPhotos = req.query.includeAfterPhotos === 'true';
        if (includeBeforePhotos || includeAfterPhotos) {
          const { getJobPhotos } = await import('./photoService');
          const allPhotos = await getJobPhotos(job.id, userContext.effectiveUserId);
          if (includeBeforePhotos) {
            beforePhotos = allPhotos
              .filter(p => p.category === 'before')
              .map(p => ({ url: p.signedUrl || '', caption: p.caption || undefined, category: p.category }));
          }
          if (includeAfterPhotos) {
            afterPhotos = allPhotos
              .filter(p => p.category === 'after')
              .map(p => ({ url: p.signedUrl || '', caption: p.caption || undefined, category: p.category }));
          }
        }
      }
      
      const excludeNotes = req.query.excludeNotes === 'true';
      
      let html: string;
      try {
        const businessForPdf = await resolveBusinessLogoForPdf(business);
        html = generateInvoicePDF({
          invoice: excludeNotes ? { ...invoiceWithItems, notes: '' } : invoiceWithItems,
          lineItems: invoiceWithItems.lineItems || [],
          client,
          business: businessForPdf,
          job,
          timeEntries,
          jobSignatures,
          termsTemplate,
          warrantyTemplate,
          beforePhotos,
          afterPhotos,
          labourSummary,
          assignments,
        });
      } catch (htmlError: any) {
        console.error('[Invoice PDF] HTML generation failed for invoice %s:', invoiceId, htmlError);
        return res.status(500).json({ 
          error: "Failed to generate invoice document", 
          details: htmlError?.message || "Error creating invoice HTML content"
        });
      }
      
      let pdfBuffer: Buffer;
      try {
        pdfBuffer = await generatePDFBuffer(html);
      } catch (pdfError: any) {
        console.error('[Invoice PDF] PDF buffer generation failed for invoice %s:', invoiceId, pdfError);
        return res.status(500).json({ 
          error: "Failed to create PDF file", 
          details: pdfError?.message || "Error converting invoice to PDF"
        });
      }
      
      res.setHeader('Content-Type', 'application/pdf');
      res.setHeader('Content-Disposition', `attachment; filename="Invoice-${invoiceWithItems.number || invoiceId}.pdf"`);
      res.send(pdfBuffer);
    } catch (error: any) {
      if (isBackpressure(error)) return send429(res, error);
      console.error('[Invoice PDF] Unexpected error generating PDF for invoice %s:', invoiceId, error);
      res.status(500).json({ 
        error: "Failed to generate invoice PDF", 
        details: error?.message || "An unexpected error occurred while generating the PDF"
      });
    }
  });

