  // =========== PAYMENT REQUESTS (Phone-to-Phone Payments) ===========
  // Get all payment requests for the user
  app.get("/api/payment-requests", requireAuth, async (req: any, res) => {
    try {
      const requests = await storage.getPaymentRequests(req.userId);
      res.json(requests);
    } catch (error) {
      console.error("Error fetching payment requests:", error);
      res.status(500).json({ error: "Failed to fetch payment requests" });
    }
  });

  // Get a specific payment request
  app.get("/api/payment-requests/:id", requireAuth, async (req: any, res) => {
    try {
      const request = await storage.getPaymentRequest(req.params.id, req.userId);
      if (!request) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      res.json(request);
    } catch (error) {
      console.error("Error fetching payment request:", error);
      res.status(500).json({ error: "Failed to fetch payment request" });
    }
  });

  // Create a new payment request
  app.post("/api/payment-requests", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const businessForStripeCheck = await storage.getBusinessSettings(req.userId);
      const canAcceptPayments = !!(businessForStripeCheck?.stripeConnectAccountId && businessForStripeCheck?.connectChargesEnabled);
      const isDemoMode = false;

      const { amount, description, reference, invoiceId, jobId, clientId, expiresInHours = 24 } = req.body;
      
      if (!amount || amount <= 0) {
        return res.status(400).json({ error: "Amount is required and must be positive" });
      }
      
      if (!description) {
        return res.status(400).json({ error: "Description is required" });
      }

      // Ownership check: any invoice/job/client reference supplied in the body
      // must belong to the caller's business, otherwise a user could attach a
      // foreign tenant's record id to their own payment request.
      const paymentReqContext = await getUserContext(req.userId);
      const paymentReqOwnerId = paymentReqContext?.effectiveUserId || req.userId;
      if (invoiceId) {
        const ownedInvoice = await storage.getInvoice(invoiceId, paymentReqOwnerId);
        if (!ownedInvoice) {
          return res.status(404).json({ error: "Invoice not found" });
        }
      }
      if (jobId) {
        const ownedJob = await storage.getJob(jobId, paymentReqOwnerId);
        if (!ownedJob) {
          return res.status(404).json({ error: "Job not found" });
        }
      }
      if (clientId) {
        const ownedClient = await storage.getClient(clientId, paymentReqOwnerId);
        if (!ownedClient) {
          return res.status(404).json({ error: "Client not found" });
        }
      }

      // Generate secure token for payment link
      const token = randomBytes(32).toString('hex');
      
      // Calculate GST (10% for Australian businesses)
      const settings = await storage.getBusinessSettings(req.userId);
      const gstEnabled = settings?.gstEnabled ?? true;
      const gstAmount = gstEnabled ? parseFloat(amount) / 11 : 0; // GST inclusive calculation
      
      // Set expiration time
      const expiresAt = new Date();
      expiresAt.setHours(expiresAt.getHours() + expiresInHours);
      
      const paymentRequest = await storage.createPaymentRequest({
        userId: req.userId,
        amount: amount.toString(),
        gstAmount: gstAmount.toFixed(2),
        description,
        reference: reference || null,
        invoiceId: invoiceId || null,
        jobId: jobId || null,
        clientId: clientId || null,
        token,
        status: 'pending',
        expiresAt,
      });
      
      // Generate the payment URL using production-ready base URL detection
      const paymentUrl = `${getProductionBaseUrl(req)}/pay/${token}`;
      
      res.status(201).json({
        ...paymentRequest,
        paymentUrl,
        isDemoMode,
      });
    } catch (error) {
      console.error("Error creating payment request:", error);
      res.status(500).json({ error: "Failed to create payment request" });
    }
  });

  // Update a payment request
  app.patch("/api/payment-requests/:id", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const { amount, description, reference, status, expiresInHours } = req.body;
      
      const updates: any = {};
      if (amount !== undefined) {
        updates.amount = amount.toString();
        // Recalculate GST
        const settings = await storage.getBusinessSettings(req.userId);
        const gstEnabled = settings?.gstEnabled ?? true;
        updates.gstAmount = gstEnabled ? (parseFloat(amount) / 11).toFixed(2) : '0.00';
      }
      if (description !== undefined) updates.description = description;
      if (reference !== undefined) updates.reference = reference;
      if (status !== undefined) updates.status = status;
      if (expiresInHours !== undefined) {
        const expiresAt = new Date();
        expiresAt.setHours(expiresAt.getHours() + expiresInHours);
        updates.expiresAt = expiresAt;
      }
      
      const updated = await storage.updatePaymentRequest(req.params.id, req.userId, updates);
      if (!updated) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      
      res.json(updated);
    } catch (error) {
      console.error("Error updating payment request:", error);
      res.status(500).json({ error: "Failed to update payment request" });
    }
  });

  // Delete a payment request
  app.delete("/api/payment-requests/:id", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const deleted = await storage.deletePaymentRequest(req.params.id, req.userId);
      if (!deleted) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      res.json({ success: true });
    } catch (error) {
      console.error("Error deleting payment request:", error);
      res.status(500).json({ error: "Failed to delete payment request" });
    }
  });

  // Cancel a payment request
  app.post("/api/payment-requests/:id/cancel", requireAuth, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const updated = await storage.updatePaymentRequest(req.params.id, req.userId, {
        status: 'cancelled'
      });
      if (!updated) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      res.json(updated);
    } catch (error) {
      console.error("Error cancelling payment request:", error);
      res.status(500).json({ error: "Failed to cancel payment request" });
    }
  });

  // Share payment request via SMS
  app.post("/api/payment-requests/:id/send-sms", requireAuth, requirePaidTierForSms, messageSendLimiter, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const { phone } = req.body;
      if (!phone) {
        return res.status(400).json({ error: "Phone number is required" });
      }
      
      const request = await storage.getPaymentRequest(req.params.id, userContext.effectiveUserId);
      if (!request) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      
      const reqClient = request.clientId ? await storage.getClient(request.clientId, userContext.effectiveUserId) : null;
      const clientName = reqClient?.name || undefined;
      
      const settings = await storage.getBusinessSettings(userContext.effectiveUserId);
      const businessName = settings?.businessName || 'Your tradie';
      
      // Use production-ready base URL detection
      const paymentUrl = `${getProductionBaseUrl(req)}/pay/${request.token}`;
      
      // Format the amount
      const amount = `$${parseFloat(request.amount).toFixed(2)}`;
      
      // Build SMS message using consistent pattern
      const message = `Hi${clientName ? ` ${clientName.split(' ')[0]}` : ''}, ${businessName} has sent you a payment request for ${amount}${request.description ? ` (${request.description})` : ''}. Pay securely here: ${paymentUrl}`;
      
      // Import and use SMS service (pass raw phone, service handles formatting)
      const { sendSmsToClient } = await import('./services/smsService');
      
      const smsResult = await sendSmsToClient({
        businessOwnerId: userContext.effectiveUserId,
        clientId: request.clientId || undefined,
        clientPhone: phone, // Let smsService handle formatting
        clientName: clientName || undefined,
        message,
        senderUserId: req.userId,
      });
      
      // Check if SMS actually sent - the service returns message with status
      if (smsResult.status === 'failed') {
        const errorMsg = smsResult.errorMessage || 'SMS service unavailable';
        if (/dedicated (phone )?number/i.test(errorMsg)) {
          return res.status(402).json({ 
            error: 'Your business needs its own dedicated phone number to send SMS. Purchase one in Phone Numbers.',
            code: 'DEDICATED_NUMBER_REQUIRED',
          });
        }
        // Check for "not configured" type errors
        if (errorMsg.toLowerCase().includes('not configured') || 
            errorMsg.toLowerCase().includes('twilio') ||
            errorMsg.toLowerCase().includes('credentials')) {
          return res.status(400).json({ error: "SMS not configured. Set up Twilio in Settings > Integrations to send SMS." });
        }
        return res.status(400).json({ error: errorMsg });
      }
      
      // Update notifications sent
      const notificationsSent = (request.notificationsSent as any[] || []);
      notificationsSent.push({ type: 'sms', phone, sentAt: new Date().toISOString() });
      
      await storage.updatePaymentRequest(req.params.id, userContext.effectiveUserId, {
        notificationsSent
      } as any);
      
      // Log activity for SMS sent (using invoice_sent type since payment requests relate to invoices)
      if (request.invoiceId) {
        await logActivity(
          userContext.effectiveUserId,
          'invoice_sent',
          `Payment link sent via SMS`,
          `SMS sent to ${clientName || 'client'} (${phone}) for ${amount}`,
          'invoice',
          request.invoiceId,
          { paymentRequestId: request.id, senderUserId: req.userId }
        );
      }
      
      res.json({ success: true, message: "SMS sent successfully" });
    } catch (error: any) {
      console.error("Error sending payment request SMS:", error);
      // Check if it's a Twilio-specific error
      if (error.message?.includes('Twilio') || error.message?.includes('SMS')) {
        return res.status(400).json({ error: error.message || "SMS service unavailable. Please check your Twilio configuration." });
      }
      res.status(500).json({ error: "Failed to send SMS" });
    }
  });

  // Share payment request via email
  app.post("/api/payment-requests/:id/send-email", requireAuth, messageSendLimiter, createPermissionMiddleware(PERMISSIONS.WRITE_INVOICES), async (req: any, res) => {
    try {
      const { email } = req.body;
      if (!email) {
        return res.status(400).json({ error: "Email is required" });
      }
      
      const request = await storage.getPaymentRequest(req.params.id, req.userId);
      if (!request) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      
      const settings = await storage.getBusinessSettings(req.userId);
      const businessName = settings?.businessName || 'Your tradie';
      
      // Use production-ready base URL detection
      const paymentUrl = `${getProductionBaseUrl(req)}/pay/${request.token}`;
      
      // Import and use email service
      const { sendPaymentRequestEmail } = await import('./emailService');
      await sendPaymentRequestEmail({
        to: email,
        businessName,
        businessEmail: settings?.email ?? undefined, // Use tradie's email for reply-to
        amount: parseFloat(request.amount),
        description: request.description,
        paymentUrl,
        reference: request.reference || undefined,
      });
      
      // Update notifications sent
      const notificationsSent = (request.notificationsSent as any[] || []);
      notificationsSent.push({ type: 'email', email, sentAt: new Date().toISOString() });
      
      await storage.updatePaymentRequest(req.params.id, req.userId, {
        notificationsSent
      } as any);
      
      res.json({ success: true, message: "Email sent successfully" });
    } catch (error) {
      console.error("Error sending payment request email:", error);
      res.status(500).json({ error: "Failed to send email" });
    }
  });

  // Generate QR code for a payment request
  app.get("/api/payment-requests/:id/qrcode", requireAuth, async (req: any, res) => {
    try {
      const request = await storage.getPaymentRequest(req.params.id, req.userId);
      if (!request) {
        return res.status(404).json({ error: "Payment request not found" });
      }
      
      const QRCode = ((await import('qrcode')) as any).default; // qrcode ships no type declarations
      // Use production-ready base URL detection
      const paymentUrl = `${getProductionBaseUrl(req)}/pay/${request.token}`;
      
      // Generate QR code as data URL (base64)
      const qrDataUrl = await QRCode.toDataURL(paymentUrl, {
        width: 300,
        margin: 2,
        color: {
          dark: '#000000',
          light: '#ffffff'
        }
      });
      
      res.json({ 
        success: true, 
        qrCode: qrDataUrl,
        paymentUrl
      });
    } catch (error) {
      console.error("Error generating QR code:", error);
      res.status(500).json({ error: "Failed to generate QR code" });
    }
  });

  // =========== STRIPE TERMINAL (Tap to Pay) ===========
  
  // Get Terminal connection token - required for SDK initialization
  app.post("/api/terminal/connection-token", requireAuth, async (req: any, res) => {
    try {
      // Workers/leads with the collect_payments permission may take Tap to Pay
      // payments on behalf of the business — everything resolves to the OWNER's
      // Stripe account and settings, never the worker's own.
      const termCtx = await getUserContext(req.userId);
      if (!hasPermission(termCtx, PERMISSIONS.MANAGE_PAYMENTS)) {
        return res.status(403).json({ error: "You don't have permission to collect payments" });
      }
      const termOwnerId = termCtx.effectiveUserId;

      const stripe = await getUncachableStripeClient();
      if (!stripe) {
        return res.status(503).json({ 
          error: "Payment processing not configured",
          message: "Stripe is not configured. Please set up Stripe integration first."
        });
      }
      
      // Get or create a location for this business
      const settings = await storage.getBusinessSettings(termOwnerId);
      let locationId: string | undefined = (settings as any)?.stripeTerminalLocationId; // column persisted in DB but absent from typed schema
      
      if (!locationId) {
        // Create a location for the user
        const location = await stripe.terminal.locations.create({
          display_name: settings?.businessName || 'Business Location',
          address: {
            line1: settings?.address || '1 Main St',
            city: 'Sydney',
            state: 'NSW',
            postal_code: '2000',
            country: 'AU',
          },
        });
        locationId = location.id;
        
        // Save location ID to business settings
        await storage.updateBusinessSettings(termOwnerId, {
          stripeTerminalLocationId: locationId,
        } as any);
      }
      
      // Create connection token
      const connectionToken = await stripe.terminal.connectionTokens.create({
        location: locationId,
      });
      
      res.json({ 
        secret: connectionToken.secret,
        locationId 
      });
    } catch (error: any) {
      console.error("Error creating terminal connection token:", error);
      res.status(500).json({ 
        error: "Failed to create connection token",
        message: error.message 
      });
    }
  });

  // Create a payment intent for terminal payment
  app.post("/api/terminal/payment-intent", paymentRateLimiter, requireAuth, async (req: any, res) => {
    try {
      const { amount, description, clientId, invoiceId, jobId, idempotencyKey } = req.body;
      
      if (!amount || amount <= 0) {
        return res.status(400).json({ error: "Amount is required and must be positive" });
      }
      
      const termCtx = await getUserContext(req.userId);
      if (!hasPermission(termCtx, PERMISSIONS.MANAGE_PAYMENTS)) {
        return res.status(403).json({ error: "You don't have permission to collect payments" });
      }
      const termOwnerId = termCtx.effectiveUserId;

      // Any invoice being collected must belong to this business.
      if (invoiceId) {
        const termInvoice = await storage.getInvoice(invoiceId, termOwnerId);
        if (!termInvoice) {
          return res.status(404).json({ error: "Invoice not found" });
        }
      }

      const stripe = await getUncachableStripeClient();
      if (!stripe) {
        return res.status(503).json({ error: "Payment processing not configured" });
      }
      
      const settings = await storage.getBusinessSettings(termOwnerId);
      const amountInCents = Math.round(parseFloat(amount) * 100);
      
      // Create PaymentIntent with card_present payment method type
      const paymentIntentParams: any = {
        amount: amountInCents,
        currency: 'aud',
        payment_method_types: ['card_present'],
        capture_method: 'automatic',
        description: description || 'In-person payment',
        metadata: {
          userId: termOwnerId,
          collectedBy: req.userId,
          clientId: clientId || '',
          invoiceId: invoiceId || '',
          jobId: jobId || '',
          source: 'tap_to_pay',
        },
      };
      
      // If using Stripe Connect, add transfer data
      if (settings?.stripeConnectAccountId && settings.connectChargesEnabled) {
        paymentIntentParams.transfer_data = {
          destination: settings.stripeConnectAccountId,
        };
      }
      
      // Use idempotency key to prevent duplicate charges (client provides or we generate)
      const requestOptions: { idempotencyKey?: string } = {};
      if (idempotencyKey) {
        requestOptions.idempotencyKey = idempotencyKey;
      } else {
        // Generate idempotency key from user, amount, and timestamp (5-minute window)
        const timeWindow = Math.floor(Date.now() / (5 * 60 * 1000));
        requestOptions.idempotencyKey = `terminal_${termOwnerId}_${amountInCents}_${invoiceId || jobId || 'direct'}_${timeWindow}`;
      }
      
      const paymentIntent = await stripe.paymentIntents.create(paymentIntentParams, requestOptions);
      
      // Store terminal payment record (owned by the business, not the collector)
      await storage.createTerminalPayment({
        userId: termOwnerId,
        stripePaymentIntentId: paymentIntent.id,
        amount: amount.toString(),
        description: description || 'In-person payment',
        clientId: clientId || null,
        invoiceId: invoiceId || null,
        jobId: jobId || null,
        status: 'pending',
      });
      
      res.json({
        clientSecret: paymentIntent.client_secret,
        paymentIntentId: paymentIntent.id,
        amount: amountInCents,
      });
    } catch (error: any) {
      console.error("Error creating terminal payment intent:", error);
      res.status(500).json({ 
        error: "Failed to create payment intent",
        message: error.message 
      });
    }
  });

  async function autoSendReceiptAfterPayment(
    userId: string,
    invoiceId: string | number | null,
    paymentAmount: number,
    paymentMethod: string,
    paymentReference?: string | null,
    description?: string,
    req?: any,
  ) {
    try {
      if (!invoiceId) {
        console.log('[Auto-Receipt] No invoice linked, skipping auto-send');
        return;
      }

      const invoice = await storage.getInvoice(invoiceId as any, userId);
      if (!invoice) {
        console.log(`[Auto-Receipt] Invoice ${invoiceId} not found, skipping auto-send`);
        return;
      }

      const clientId = invoice.clientId;
      if (!clientId) {
        console.log(`[Auto-Receipt] No client linked to invoice ${invoiceId}, skipping auto-send`);
        return;
      }

      const client = await storage.getClientById(clientId);
      if (!client) {
        console.log(`[Auto-Receipt] Client ${clientId} not found, skipping auto-send`);
        return;
      }

      const settings = await storage.getBusinessSettingsByUserId(userId);

      let receipt = await storage.getReceiptByInvoiceId(invoice.id, userId);
      if (!receipt) {
        const receiptNumber = await storage.generateReceiptNumber(userId);
        const gstAmount = paymentAmount / 11;
        const subtotal = paymentAmount - gstAmount;

        receipt = await storage.createReceipt({
          userId,
          receiptNumber,
          invoiceId: invoice.id,
          jobId: invoice.jobId,
          clientId,
          amount: paymentAmount.toFixed(2),
          gstAmount: gstAmount.toFixed(2),
          subtotal: subtotal.toFixed(2),
          paymentMethod,
          paymentReference: paymentReference || null,
          description: description || `Payment for Invoice ${invoice.number || String(invoice.id).substring(0, 8).toUpperCase()}`,
          paidAt: new Date(),
        });

        console.log(`[Auto-Receipt] Created receipt ${receiptNumber}`);
      }

      if (client.email && settings) {
        try {
          const { sendReceiptEmailWithPdf } = await import('./emailService');
          await sendReceiptEmailWithPdf(storage, invoice, client, settings, receipt, userId);
          console.log(`[Auto-Receipt] Email sent to ${client.email}`);
        } catch (emailError) {
          console.error('[Auto-Receipt] Email failed:', emailError);
        }
      }

      if (client.phone) {
        try {
          const { sendSmsToClient } = await import('./services/smsService');
          const { smsTemplates } = await import('./twilioClient');
          const crypto = await import('crypto');

          let viewToken = receipt.viewToken;
          if (!viewToken) {
            const chars = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghjkmnpqrstuvwxyz23456789';
            viewToken = '';
            for (let i = 0; i < 12; i++) {
              viewToken += chars[crypto.randomInt(chars.length)];
            }
            await storage.updateReceipt(receipt.id, userId, { viewToken });
          }

          const receiptUrl = getReceiptPublicUrl(viewToken, req);
          const businessName = settings?.businessName || 'Your tradie';
          const businessPhone = settings?.phone || undefined;
          const amount = `$${paymentAmount.toFixed(2)}`;
          const message = smsTemplates.paymentReceived(client.name || 'Customer', amount, businessName, receiptUrl, businessPhone);

          await sendSmsToClient({
            businessOwnerId: userId,
            clientId: client.id,
            clientPhone: client.phone,
            clientName: client.name || undefined,
            jobId: invoice.jobId || undefined,
            message,
            senderUserId: userId,
          });

          await storage.updateReceipt(receipt.id, userId, {
            smsSentAt: new Date(),
            recipientPhone: client.phone,
          });

          console.log(`[Auto-Receipt] SMS sent to ${client.phone}`);
        } catch (smsError) {
          console.error('[Auto-Receipt] SMS failed:', smsError);
        }
      }

      const sentVia: string[] = [];
      if (client.email && settings) sentVia.push('email');
      if (client.phone) sentVia.push('SMS');

      if (sentVia.length > 0) {
        await logActivity(
          userId,
          'payment_received',
          `Receipt auto-sent via ${sentVia.join(' and ')}`,
          `Receipt for $${paymentAmount.toFixed(2)} auto-sent via ${sentVia.join(' and ')} to ${client.name || 'customer'}`,
          'invoice',
          invoice.id,
          { receiptId: receipt.id, receiptNumber: receipt.receiptNumber, amount: paymentAmount.toFixed(2), paymentMethod, autoSent: true, sentVia }
        );
      } else {
        console.log(`[Auto-Receipt] Receipt created but no email/phone on client to send to`);
      }

      console.log(`[Auto-Receipt] Complete for invoice ${invoice.number || invoiceId}`);
    } catch (error) {
      console.error('[Auto-Receipt] Failed:', error);
    }
  }

  // Confirm terminal payment succeeded (webhook or client callback)
  app.post("/api/terminal/payment-success", requireAuth, async (req: any, res) => {
    try {
      const { paymentIntentId, cardBrand, cardLast4 } = req.body;
      
      if (!paymentIntentId) {
        return res.status(400).json({ error: "Payment intent ID is required" });
      }

      // Ownership: the terminal payment must belong to the authenticated
      // business (owner or a team member with the collect_payments permission).
      const termSuccessCtx = await getUserContext(req.userId);
      if (!hasPermission(termSuccessCtx, PERMISSIONS.MANAGE_PAYMENTS)) {
        return res.status(403).json({ error: "You don't have permission to collect payments" });
      }
      const termOwnerId = termSuccessCtx.effectiveUserId;
      const existingPayment = await storage.getTerminalPaymentByIntent(paymentIntentId);
      if (!existingPayment || existingPayment.userId !== termOwnerId) {
        return res.status(404).json({ error: "Terminal payment not found" });
      }
      if (existingPayment.status === 'succeeded') {
        return res.json({ success: true, payment: existingPayment, alreadyPaid: true });
      }

      // Verify the charge actually succeeded with Stripe before marking it paid —
      // never trust the client callback. Demo bypass only for the demo business.
      const termOwner = await storage.getUser(termOwnerId);
      const isDemoTerminalBusiness = termOwner?.email === DEMO_USER.email || termOwner?.email === VISITOR_USER.email || termOwner?.email === TRY_DEMO_USER.email;
      const isDemoTerminalPayment = isDemoTerminalBusiness && String(paymentIntentId).startsWith('demo_pi_');
      if (!isDemoTerminalPayment) {
        const stripe = await getUncachableStripeClient();
        if (!stripe) {
          return res.status(503).json({ error: "Payment processing is not available" });
        }
        // Terminal PIs are direct charges on the connected account — retrieve
        // them in the same account context or Stripe returns "No such
        // payment_intent". Legacy /api/terminal/payment-intent PIs live on the
        // platform account, so fall back to a platform retrieve if the
        // connected-account lookup misses.
        const termSettings = await storage.getBusinessSettings(termOwnerId);
        let pi;
        if (termSettings?.stripeConnectAccountId) {
          try {
            pi = await stripe.paymentIntents.retrieve(paymentIntentId, { stripeAccount: termSettings.stripeConnectAccountId });
          } catch (retrieveErr: any) {
            if (retrieveErr?.code === 'resource_missing') {
              pi = await stripe.paymentIntents.retrieve(paymentIntentId);
            } else {
              throw retrieveErr;
            }
          }
        } else {
          pi = await stripe.paymentIntents.retrieve(paymentIntentId);
        }
        if (pi.status !== 'succeeded') {
          return res.status(400).json({ error: "Payment has not been completed" });
        }
      }
      
      // Process invoice side effects BEFORE marking the terminal payment
      // succeeded — if anything critical fails, the record stays pending and
      // a retry of this endpoint re-runs the work (the alreadyPaid
      // short-circuit above only fires once we've fully succeeded).
      // If linked to an invoice, record the payment against it (supports
      // partial payments), lock it when fully paid, mark the job invoiced,
      // and cancel any still-open payment links for the same invoice.
      let invoiceFullyPaid = false;
      let autoReceipt = false;
      if (existingPayment.invoiceId) {
        const invoice = await storage.getInvoice(existingPayment.invoiceId, termOwnerId);
        if (invoice) {
          const paymentAmount = parseFloat(String(existingPayment.amount || '0'));

          // Idempotency: skip the ledger entry + amountPaid increment if this
          // payment intent was already recorded (partial earlier attempt).
          const existingRecords = await storage.getPaymentRecords(invoice.id);
          const alreadyRecorded = existingRecords.some((r: any) => r.reference === paymentIntentId);

          const invoiceTotal = parseFloat(String(invoice.total || '0'));
          const retentionAmount = parseFloat(String(invoice.retentionAmount || '0'));
          const previouslyPaid = parseFloat(String(invoice.amountPaid || '0'));
          const newTotalPaid = alreadyRecorded ? previouslyPaid : previouslyPaid + paymentAmount;
          const effectiveTotal = invoiceTotal - retentionAmount;
          invoiceFullyPaid = Math.round(newTotalPaid * 100) >= Math.round(effectiveTotal * 100);

          if (!alreadyRecorded) {
            // Payment ledger entry (same shape as manual record-payment).
            // Deliberately NOT swallowed: if this or the invoice update fails,
            // the request 500s and the client/retry can re-run it.
            await storage.createPaymentRecord({
              invoiceId: invoice.id,
              userId: termOwnerId,
              amount: paymentAmount.toFixed(2),
              method: 'card',
              reference: paymentIntentId,
              note: 'Tap to Pay contactless payment',
              recordedBy: req.userId,
              paidAt: new Date(),
            });

            const updateData: any = {
              amountPaid: newTotalPaid.toFixed(2),
              paymentMethod: 'card',
              paymentReference: paymentIntentId,
            };
            if (invoiceFullyPaid) {
              updateData.status = 'paid';
              updateData.paidAt = new Date();
              updateData.lockedAt = new Date();
              updateData.lockedReason = 'payment_received';
            } else if (newTotalPaid > 0) {
              updateData.status = 'partially_paid';
            }
            await storage.updateInvoice(invoice.id, termOwnerId, updateData);
          }

          if (invoiceFullyPaid) {
            // Mark the linked job as invoiced (paid on site)
            if (invoice.jobId) {
              try {
                const job = await storage.getJob(invoice.jobId, termOwnerId);
                if (job && job.status !== 'invoiced') {
                  await storage.updateJob(invoice.jobId, termOwnerId, { status: 'invoiced' });
                }
              } catch (jobErr) {
                console.log('[Terminal] Job status update skipped:', jobErr);
              }
            }

            // Cancel any still-open payment links / requests for this invoice —
            // the customer already paid in person.
            try {
              const openRequests = (await storage.getPaymentRequests(termOwnerId))
                .filter((pr: any) => pr.invoiceId === invoice.id && pr.status === 'pending');
              for (const pr of openRequests) {
                await storage.updatePaymentRequest(pr.id, termOwnerId, { status: 'cancelled' } as any);
                if (pr.stripePaymentIntentId && !String(pr.stripePaymentIntentId).startsWith('demo_pi_')) {
                  try {
                    const stripeForCancel = await getUncachableStripeClient();
                    if (stripeForCancel) {
                      await stripeForCancel.paymentIntents.cancel(pr.stripePaymentIntentId);
                    }
                  } catch (piCancelErr: any) {
                    // Already-succeeded/cancelled intents can't be cancelled — fine.
                    console.log('[Terminal] Payment link intent cancel skipped:', piCancelErr?.message);
                  }
                }
              }
              if (openRequests.length > 0) {
                console.log(`[Terminal] Cancelled ${openRequests.length} open payment link(s) for invoice ${invoice.number || invoice.id}`);
              }
            } catch (cancelErr) {
              console.error('[Terminal] Failed to cancel open payment links:', cancelErr);
            }

            processPaymentReceivedAutomation(termOwnerId, invoice.id)
              .catch(err => console.error('[Automations] Error processing payment received:', err));
          }

          // Push notification + real-time broadcast to the business
          try {
            const amountInCents = Math.round(paymentAmount * 100);
            await notifyPaymentReceived(termOwnerId, amountInCents, invoice.number || `INV-${invoice.id}`, invoice.id);
            const { broadcastPaymentReceived } = await import('./websocket');
            let clientName: string | undefined;
            if (invoice.clientId) {
              const payClient = await storage.getClientById(invoice.clientId);
              clientName = payClient?.name || undefined;
            }
            broadcastPaymentReceived(termOwnerId, {
              amount: amountInCents,
              invoiceNumber: invoice.number,
              clientName,
              paymentMethod: 'card_present',
            });
          } catch (notifyErr) {
            console.error('[Terminal] Payment notification failed:', notifyErr);
          }

          autoReceipt = true;
          autoSendReceiptAfterPayment(
            termOwnerId,
            invoice.id,
            paymentAmount,
            'card_present',
            paymentIntentId,
            'Tap to Pay payment',
            req,
          ).catch(err => console.error('[Terminal] Auto-receipt failed:', err));
        }
      } else {
        // Direct Tap to Pay with no invoice/job link — still record a receipt
        // using the owner's receipt numbering/template so the payment is
        // tracked and shows up in Receipts + payment history (not just as a
        // raw terminal row).
        const directAmount = parseFloat(String(existingPayment.amount || '0'));
        try {
          if (directAmount > 0) {
            const existingReceipts = await storage.getReceipts(termOwnerId);
            const already = existingReceipts.some((r: any) => r.paymentReference === paymentIntentId);
            if (!already) {
              const receiptNumber = await storage.generateReceiptNumber(termOwnerId);
              const gstAmount = directAmount / 11;
              const subtotal = directAmount - gstAmount;
              const directReceipt = await storage.createReceipt({
                userId: termOwnerId,
                receiptNumber,
                clientId: existingPayment.clientId || null,
                jobId: existingPayment.jobId || null,
                amount: directAmount.toFixed(2),
                gstAmount: gstAmount.toFixed(2),
                subtotal: subtotal.toFixed(2),
                paymentMethod: 'tap_to_pay',
                paymentReference: paymentIntentId,
                description: existingPayment.description || 'Tap to Pay payment',
                paidAt: new Date(),
              });
              await logActivity(
                termOwnerId,
                'payment_received',
                `Receipt ${receiptNumber} created`,
                `Tap to Pay payment of $${directAmount.toFixed(2)} received`,
                null,
                null,
                { receiptNumber, receiptId: directReceipt.id, amount: directAmount.toFixed(2), paymentMethod: 'tap_to_pay', paymentReference: paymentIntentId }
              );
              autoReceipt = true;
            }
          }
        } catch (directReceiptErr) {
          console.error('[Terminal] Direct Tap to Pay receipt creation failed:', directReceiptErr);
        }

        // Notify + broadcast the direct payment so it hits the owner's bell
        // and live dashboards, same as invoice-linked taps.
        try {
          const amountInCents = Math.round(directAmount * 100);
          await notifyPaymentReceived(termOwnerId, amountInCents, 'Tap to Pay', '');
          const { broadcastPaymentReceived } = await import('./websocket');
          broadcastPaymentReceived(termOwnerId, {
            amount: amountInCents,
            paymentMethod: 'card_present',
          });
        } catch (notifyErr) {
          console.error('[Terminal] Direct payment notification failed:', notifyErr);
        }
      }

      // All critical side effects done — now mark the terminal payment
      // succeeded so future calls short-circuit as alreadyPaid.
      const updatedPayment = await storage.updateTerminalPaymentByIntent(paymentIntentId, {
        status: 'succeeded',
        cardBrand,
        cardLast4,
        completedAt: new Date(),
        paymentMethod: 'card_present',
      });

      res.json({ 
        success: true, 
        payment: updatedPayment || existingPayment,
        invoiceFullyPaid,
        autoReceipt,
      });
    } catch (error: any) {
      console.error("Error confirming terminal payment:", error);
      res.status(500).json({ error: "Failed to confirm payment" });
    }
  });

  // Cancel a terminal payment
  app.post("/api/terminal/payment-cancel", requireAuth, async (req: any, res) => {
    try {
      const { paymentIntentId } = req.body;
      
      if (!paymentIntentId) {
        return res.status(400).json({ error: "Payment intent ID is required" });
      }

      // Ownership: only the business that created the payment may cancel it
      // (owner or a team member with the collect_payments permission).
      const cancelCtx = await getUserContext(req.userId);
      if (!hasPermission(cancelCtx, PERMISSIONS.MANAGE_PAYMENTS)) {
        return res.status(403).json({ error: "You don't have permission to collect payments" });
      }
      const cancelOwnerId = cancelCtx.effectiveUserId;
      const cancelPayment = await storage.getTerminalPaymentByIntent(paymentIntentId);
      if (!cancelPayment || cancelPayment.userId !== cancelOwnerId) {
        return res.status(404).json({ error: "Terminal payment not found" });
      }

      const stripe = await getUncachableStripeClient();
      if (stripe && !String(paymentIntentId).startsWith('demo_pi_')) {
        // Terminal PIs are direct charges on the connected account; legacy
        // ones live on the platform — try connected first, fall back.
        const cancelSettings = await storage.getBusinessSettings(cancelOwnerId);
        try {
          if (cancelSettings?.stripeConnectAccountId) {
            try {
              await stripe.paymentIntents.cancel(paymentIntentId, {}, { stripeAccount: cancelSettings.stripeConnectAccountId });
            } catch (connCancelErr: any) {
              if (connCancelErr?.code === 'resource_missing') {
                await stripe.paymentIntents.cancel(paymentIntentId);
              } else {
                throw connCancelErr;
              }
            }
          } else {
            await stripe.paymentIntents.cancel(paymentIntentId);
          }
        } catch (cancelErr: any) {
          // Already-cancelled/succeeded intents throw — still mark our record.
          console.log('[Terminal] Stripe cancel skipped:', cancelErr?.message);
        }
      }
      
      await storage.updateTerminalPaymentByIntent(paymentIntentId, {
        status: 'cancelled',
      });
      
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error cancelling terminal payment:", error);
      res.status(500).json({ error: "Failed to cancel payment" });
    }
  });

  // Build a unified payment history. Always includes Tap to Pay charges
  // (terminal_payments); when includeReceipts is set it also folds in every
  // other collected payment via the receipts ledger (Payment Links, QR codes,
  // card, cash, bank transfer), deduped against Tap to Pay by PaymentIntent id.
  // Every entry is normalized to the same shape, enriched with Stripe fee/net +
  // settlement (Tap to Pay only — others aren't fee-tracked) and readable
  // context (client name + invoice number OR job title), then sorted newest-first.
  const buildPaymentHistory = async (
    effectiveUserId: string,
    opts: { includeReceipts?: boolean } = {},
  ): Promise<any[]> => {
    const payments = await storage.getTerminalPayments(effectiveUserId);

    let stripe: any = null;
    let connectAccountId: string | undefined;
    try {
      const listSettings = await storage.getBusinessSettings(effectiveUserId);
      connectAccountId = (listSettings as any)?.stripeConnectAccountId || undefined;
      stripe = await getUncachableStripeClient();
    } catch { /* fee enrichment is best-effort */ }

    const retrievePi = async (intentId: string) => {
      if (connectAccountId) {
        try {
          return await stripe.paymentIntents.retrieve(intentId, { expand: ['latest_charge.balance_transaction'] }, { stripeAccount: connectAccountId });
        } catch (err: any) {
          if (err?.code !== 'resource_missing') throw err;
        }
      }
      return await stripe.paymentIntents.retrieve(intentId, { expand: ['latest_charge.balance_transaction'] });
    };

    // Bound the Stripe fan-out: cap how many uncached payments we hit Stripe
    // for per request (older ones hydrate lazily on subsequent loads) and run
    // in small concurrency batches so a big history can't burst the API.
    const MAX_LOOKUPS = 25;
    const CONCURRENCY = 4;
    let lookupBudget = MAX_LOOKUPS;

    const enrichOne = async (p: any) => {
      const meta = (p.metadata && typeof p.metadata === 'object') ? p.metadata : {};
      let fee = meta.stripeFee != null ? Number(meta.stripeFee) : null;
      let net = meta.netAmount != null ? Number(meta.netAmount) : null;
      let settlementStatus: string | null = meta.settlementStatus || null;

      const needsLookup = stripe && p.status === 'succeeded' && p.stripePaymentIntentId &&
        !String(p.stripePaymentIntentId).startsWith('demo_pi_') &&
        (fee == null || settlementStatus === 'pending' || !settlementStatus);

      if (needsLookup && lookupBudget > 0) {
        lookupBudget--;
        try {
          const pi = await retrievePi(p.stripePaymentIntentId);
          const charge = pi?.latest_charge && typeof pi.latest_charge === 'object' ? pi.latest_charge : null;
          const bt = charge?.balance_transaction && typeof charge.balance_transaction === 'object' ? charge.balance_transaction : null;
          if (bt) {
            fee = (bt.fee || 0) / 100;
            net = (bt.net || 0) / 100;
            settlementStatus = bt.status === 'available' ? 'available' : 'pending';
            await storage.updateTerminalPaymentByIntent(p.stripePaymentIntentId, {
              metadata: { ...meta, stripeFee: fee, netAmount: net, settlementStatus },
            } as any);
          }
        } catch (feeErr: any) {
          console.log('[Payments] Fee lookup skipped for', p.stripePaymentIntentId, feeErr?.message);
        }
      }

      return { ...p, fee, net, settlementStatus, method: 'tap_to_pay' };
    };

    const enriched: any[] = [];
    for (let i = 0; i < payments.length; i += CONCURRENCY) {
      const batch = payments.slice(i, i + CONCURRENCY);
      enriched.push(...await Promise.all(batch.map(enrichOne)));
    }

    // Every other collected payment (Payment Links, QR codes, card, cash, bank
    // transfer) is recorded as a receipt. Tap to Pay ALSO writes a receipt, so
    // those dedupe against the terminal rows above by Stripe PaymentIntent id
    // (the receipt's paymentReference — terminal comes first so its fee/net
    // enrichment wins). Receipts are the record of money ACTUALLY collected: an
    // unpaid or cancelled payment link never creates one, so it never shows here.
    if (opts.includeReceipts) {
      const receipts = await storage.getReceipts(effectiveUserId);
      for (const r of receipts) {
        const payMethod = (r as any).paymentMethod || 'card';
        // Link/QR receipts carry a paymentRequestId; surface them as a payment
        // link so they read clearly, unless they're explicitly a QR/tap row.
        let method = payMethod;
        if (payMethod !== 'tap_to_pay' && payMethod !== 'qr_code' && (r as any).paymentRequestId) {
          method = 'payment_link';
        }
        enriched.push({
          id: r.id,
          stripePaymentIntentId: (r as any).paymentReference || null,
          amount: r.amount,
          currency: 'aud',
          status: 'succeeded',
          description: (r as any).description || null,
          cardBrand: null,
          cardLast4: null,
          clientId: (r as any).clientId || null,
          invoiceId: (r as any).invoiceId || null,
          jobId: (r as any).jobId || null,
          metadata: {},
          createdAt: (r as any).createdAt || null,
          completedAt: (r as any).paidAt || (r as any).createdAt || null,
          fee: null,
          net: null,
          settlementStatus: null,
          method,
        });
      }
    }

    // Collapse duplicate PaymentIntents (a Tap to Pay charge exists as BOTH a
    // terminal row and a receipt). Terminal rows come first so their fee/net
    // enrichment normally wins, but a *succeeded* row always beats a stale
    // pending/failed one for the same PI (e.g. a receipt landed before the
    // terminal status update did). Rows without a PI (cash/manual) are kept.
    const byIntent = new Map<string, any>();
    const noIntent: any[] = [];
    for (const p of enriched) {
      const pi = p.stripePaymentIntentId as string | null;
      if (!pi) { noIntent.push(p); continue; }
      const existing = byIntent.get(pi);
      if (!existing) { byIntent.set(pi, p); continue; }
      if (existing.status !== 'succeeded' && p.status === 'succeeded') {
        byIntent.set(pi, p);
      }
    }
    const deduped = [...byIntent.values(), ...noIntent];

    // Attach readable context (client name + invoice number OR job title) so
    // the mobile payment history shows what each charge was for instead of a
    // generic "payment". Fetched by unique referenced id in small batches to
    // avoid an N+1 blowup on large histories.
    const fetchInBatches = async <T,>(ids: string[], fn: (id: string) => Promise<T>, onResult: (id: string, r: T) => void) => {
      for (let i = 0; i < ids.length; i += 8) {
        const slice = ids.slice(i, i + 8);
        await Promise.all(slice.map(async (id) => { try { onResult(id, await fn(id)); } catch { /* skip missing */ } }));
      }
    };
    const invoiceMap = new Map<string, any>();
    const jobMap = new Map<string, any>();
    const clientMap = new Map<string, any>();
    const invoiceIds = Array.from(new Set(deduped.filter((p) => p.invoiceId).map((p) => p.invoiceId as string)));
    const jobIds = Array.from(new Set(deduped.filter((p) => !p.invoiceId && p.jobId).map((p) => p.jobId as string)));
    await fetchInBatches(invoiceIds, (id) => storage.getInvoice(id, effectiveUserId), (id, inv) => { if (inv) invoiceMap.set(id, inv); });
    await fetchInBatches(jobIds, (id) => storage.getJob(id, effectiveUserId), (id, job) => { if (job) jobMap.set(id, job); });
    const clientIds = Array.from(new Set([
      ...deduped.map((p) => p.clientId),
      ...Array.from(invoiceMap.values()).map((i: any) => i.clientId),
      ...Array.from(jobMap.values()).map((j: any) => j.clientId),
    ].filter(Boolean) as string[]));
    await fetchInBatches(clientIds, (id) => storage.getClientById(id), (id, c) => { if (c) clientMap.set(id, c); });

    const withContext = deduped.map((p) => {
      const invoice = p.invoiceId ? invoiceMap.get(p.invoiceId) : null;
      const job = !invoice && p.jobId ? jobMap.get(p.jobId) : null;
      const clientId = invoice?.clientId || job?.clientId || p.clientId || null;
      const client = clientId ? clientMap.get(clientId) : null;
      return {
        ...p,
        invoiceNumber: invoice?.number || null,
        jobTitle: job?.title || null,
        clientName: client?.name || null,
      };
    });

    withContext.sort((a, b) => {
      const ta = new Date(a.completedAt || a.createdAt || 0).getTime();
      const tb = new Date(b.completedAt || b.createdAt || 0).getTime();
      return tb - ta;
    });

    return withContext;
  };

