  // Time Tracking Routes
  app.get("/api/time-entries", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const jobId = req.query.jobId as string | undefined;
      const teamView = req.query.teamView === 'true';
      
      let timeEntriesList: any[];
      if (jobId && teamView) {
        const userContext = await getUserContext(userId);
        const job = await storage.getJob(jobId, userContext.effectiveUserId);
        if (!job) {
          return res.status(404).json({ error: 'Job not found' });
        }
        const completed = await storage.getTimeEntriesForJob(jobId);
        const active = await storage.getActiveTimeEntriesForJob(jobId);
        timeEntriesList = [...completed, ...active].sort((a, b) => 
          new Date(b.startTime).getTime() - new Date(a.startTime).getTime()
        );
      } else if (teamView && !jobId) {
        const userContext = await getUserContext(userId);
        // Gate on the explicit privilege, not role-name strings. (The old
        // exact-uppercase 'MANAGER'/'MANAGE_TEAM' checks matched nothing —
        // roles are stored as "Manager" and permissions lowercase.)
        const perms = (userContext.permissions || []) as string[];
        const canViewTeam = userContext.isOwner ||
          perms.includes('*') ||
          perms.includes(PERMISSIONS.MANAGE_TEAM) ||
          perms.includes(PERMISSIONS.VIEW_ALL);
        if (!canViewTeam) {
          return res.status(403).json({ error: 'Team view requires owner or manager access' });
        }
        const startDate = req.query.startDate as string | undefined;
        const endDate = req.query.endDate as string | undefined;
        if (startDate && endDate) {
          const start = new Date(startDate + 'T00:00:00');
          const end = new Date(endDate + 'T23:59:59');
          timeEntriesList = await storage.getTeamTimeEntriesInRange(userContext.effectiveUserId, start, end);
        } else {
          timeEntriesList = await storage.getTimeEntries(userId, jobId);
        }
      } else {
        timeEntriesList = await storage.getTimeEntries(userId, jobId);
      }
      
      const userCache = new Map<string, any>();
      const jobCache = new Map<string, any>();
      const enriched = await Promise.all(timeEntriesList.map(async (entry: any) => {
        let userName = null;
        if (entry.userId) {
          if (!userCache.has(entry.userId)) {
            const u = await storage.getUser(entry.userId);
            userCache.set(entry.userId, u);
          }
          const u = userCache.get(entry.userId);
          if (u) {
            userName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || u.name || u.email;
          }
        }
        let jobTitle = null;
        let clientName = null;
        if (entry.jobId) {
          if (!jobCache.has(entry.jobId)) {
            const j = await storage.getJob(entry.jobId, userId);
            jobCache.set(entry.jobId, j);
          }
          const j = jobCache.get(entry.jobId);
          if (j) {
            jobTitle = j.title || null;
            if (j.clientId) {
              const c = await storage.getClient(j.clientId, userId);
              clientName = c?.name || null;
            }
          }
        }
        return { ...entry, userName, jobTitle, clientName };
      }));
      
      res.json(enriched);
    } catch (error) {
      console.error('Error fetching time entries:', error);
      res.status(500).json({ error: 'Failed to fetch time entries' });
    }
  });

  // Get all active team timers for a specific job (shows who's on-site, their elapsed time, break status)
  app.get("/api/time-entries/job-team-timers/:jobId", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { jobId } = req.params;
      
      const userContext = await getUserContext(userId);
      const job = await storage.getJob(jobId, userContext.effectiveUserId);
      if (!job) {
        return res.status(404).json({ error: 'Job not found' });
      }
      
      const activeEntries = await storage.getActiveTimeEntriesForJob(jobId);
      
      const enriched = await Promise.all(activeEntries.map(async (entry: any) => {
        let workerName = 'Unknown';
        let workerAvatar = null;
        if (entry.userId) {
          const u = await storage.getUser(entry.userId);
          if (u) {
            workerName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || u.email || '';
            workerAvatar = u.profileImageUrl || null;
          }
        }
        const now = new Date().getTime();
        const startMs = entry.startTime ? new Date(entry.startTime).getTime() : now;
        const elapsedMs = now - startMs;
        const pausedMs = entry.pausedDuration ? Number(entry.pausedDuration) * 60 * 1000 : 0;
        let currentPauseMs = 0;
        if (entry.isPaused && entry.pausedAt) {
          currentPauseMs = now - new Date(entry.pausedAt).getTime();
        }
        const effectiveMs = Math.max(0, elapsedMs - pausedMs - currentPauseMs);
        return {
          id: entry.id,
          userId: entry.userId,
          workerName,
          workerAvatar,
          startTime: entry.startTime,
          isPaused: entry.isPaused || false,
          pausedDuration: entry.pausedDuration,
          isBreak: entry.isBreak || false,
          elapsedMinutes: Math.floor(effectiveMs / (1000 * 60)),
          hourlyRate: entry.hourlyRate,
          isCurrentUser: entry.userId === userId,
        };
      }));
      
      res.json(enriched);
    } catch (error) {
      console.error('Error fetching job team timers:', error);
      res.status(500).json({ error: 'Failed to fetch team timers' });
    }
  });

  // Business-wide active timers — who is clocked in right now across all jobs.
  // Owners/managers see the whole team; everyone else sees only their own.
  app.get("/api/time-entries/active/team", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      const effectiveUserId = userContext.effectiveUserId;
      const canSeeTeam = userContext.isOwner || userContext.permissions.includes('manage_team');

      let userIds: string[] = [userId];
      if (canSeeTeam) {
        userIds = [effectiveUserId];
        const teamMembers = await storage.getTeamMembers(effectiveUserId);
        for (const m of teamMembers as any[]) {
          if (m.memberId) userIds.push(m.memberId);
        }
        userIds = Array.from(new Set(userIds));
      }

      const activeEntries = await db.select().from(timeEntries)
        .where(and(
          inArray(timeEntries.userId, userIds),
          isNull(timeEntries.endTime)
        ))
        .orderBy(desc(timeEntries.startTime));

      const userCache = new Map<string, any>();
      const jobCache = new Map<string, any>();
      const enrichedRaw = await Promise.all(activeEntries.map(async (entry: any) => {
        const isSelf = entry.userId === userId;
        // Tenant isolation: time_entries has no business-owner column, so for any
        // entry that is NOT the caller's own we require the linked job to belong to
        // THIS business (resolved via getJob(..., effectiveUserId)). This prevents a
        // worker who is a member of multiple businesses from leaking an active timer
        // on another workspace's job into this owner's list.
        let job: any = null;
        if (entry.jobId) {
          if (!jobCache.has(entry.jobId)) jobCache.set(entry.jobId, await storage.getJob(entry.jobId, effectiveUserId));
          job = jobCache.get(entry.jobId);
        }
        if (!isSelf && !job) return null;

        let workerName = 'Unknown';
        let workerAvatar: string | null = null;
        let themeColor: string | null = null;
        if (entry.userId) {
          if (!userCache.has(entry.userId)) userCache.set(entry.userId, await storage.getUser(entry.userId));
          const u = userCache.get(entry.userId);
          if (u) {
            workerName = `${u.firstName || ''} ${u.lastName || ''}`.trim() || u.email || '';
            workerAvatar = u.profileImageUrl || null;
            themeColor = (u as any).themeColor || null;
          }
        }
        const jobTitle: string | null = job?.title || null;
        const now = Date.now();
        const startMs = entry.startTime ? new Date(entry.startTime).getTime() : now;
        const pausedMs = entry.pausedDuration ? Number(entry.pausedDuration) * 60 * 1000 : 0;
        let currentPauseMs = 0;
        if (entry.isPaused && entry.pausedAt) currentPauseMs = now - new Date(entry.pausedAt).getTime();
        const effectiveMs = Math.max(0, (now - startMs) - pausedMs - currentPauseMs);
        return {
          id: entry.id,
          userId: entry.userId,
          workerName,
          workerAvatar,
          themeColor,
          jobId: entry.jobId,
          jobTitle,
          startTime: entry.startTime,
          isPaused: entry.isPaused || false,
          isBreak: entry.isBreak || false,
          elapsedMinutes: Math.floor(effectiveMs / (1000 * 60)),
          hourlyRate: entry.hourlyRate,
          isCurrentUser: entry.userId === userId,
        };
      }));

      const enriched = enrichedRaw.filter(Boolean);
      res.json(enriched);
    } catch (error) {
      console.error('Error fetching active team timers:', error);
      res.status(500).json({ error: 'Failed to fetch active team timers' });
    }
  });

