  function validateGpsCoordinate(lat: any, lng: any): boolean {
    if (lat === undefined || lat === null || lng === undefined || lng === null) return true;
    const latNum = parseFloat(String(lat));
    const lngNum = parseFloat(String(lng));
    if (isNaN(latNum) || isNaN(lngNum)) return false;
    if (latNum < -90 || latNum > 90) return false;
    if (lngNum < -180 || lngNum > 180) return false;
    return true;
  }

  app.post("/api/time-entries", requireAuth, async (req: any, res) => {
    try {
      const { clientGeneratedId, ...timeEntryBody } = req.body;
      const userId = req.userId!;
      const idempKey = clientGeneratedId ? `timeentry:${userId}:${clientGeneratedId}` : null;
      if (idempKey) {
        const cached = await getIdempotencyRecord(idempKey);
        if (cached) return res.status(201).json(cached);
      }
      const data = insertTimeEntrySchema.parse(timeEntryBody);
      
      if (!validateGpsCoordinate(data.clockInLatitude, data.clockInLongitude)) {
        return res.status(400).json({ error: 'Invalid GPS coordinates for clock-in' });
      }
      
      // Validate start time is not in the future (allow 2 min tolerance for clock drift)
      if (data.startTime) {
        const startMs = new Date(data.startTime).getTime();
        if (isNaN(startMs)) {
          return res.status(400).json({ error: 'Invalid start time' });
        }
        if (startMs > Date.now() + 120000) {
          return res.status(400).json({ error: 'Start time cannot be in the future' });
        }
      }
      
      // Validate end time is after start time if both provided
      if (data.startTime && data.endTime) {
        const startMs = new Date(data.startTime).getTime();
        const endMs = new Date(data.endTime).getTime();
        if (endMs <= startMs) {
          return res.status(400).json({ error: 'End time must be after start time' });
        }
        // Reject entries longer than 24 hours
        if (endMs - startMs > 24 * 60 * 60 * 1000) {
          return res.status(400).json({ error: 'Time entry cannot exceed 24 hours' });
        }
      }
      
      // Validate duration is not negative if provided
      if (data.duration !== undefined && data.duration !== null && Number(data.duration) < 0) {
        return res.status(400).json({ error: 'Duration cannot be negative' });
      }
      
      // Check for existing active timer to prevent overlap (with team context)
      const activeEntry = await storage.getActiveTimeEntry(userId);
      if (activeEntry) {
        return res.status(409).json({ 
          error: 'Active timer already running', 
          activeEntry: {
            id: activeEntry.id,
            description: activeEntry.description,
            startTime: activeEntry.startTime,
            jobId: activeEntry.jobId
          }
        });
      }

      // Validate referenced job belongs to this business (cross-business write guard)
      if (data.jobId) {
        const tc = await getUserContext(userId);
        const ownedJob = await storage.getJob(data.jobId, tc.effectiveUserId);
        if (!ownedJob) {
          return res.status(404).json({ error: 'Job not found' });
        }
        // Validate phaseId belongs to this job — prevents cross-job/cross-business attribution
        if ((data as any).phaseId) {
          const phases = await storage.getJobPhases(data.jobId, tc.effectiveUserId);
          if (!phases.some((p: any) => p.id === (data as any).phaseId)) {
            return res.status(400).json({ error: 'Phase not found or does not belong to this job' });
          }
        }
      }

      // Multiple workers can now track time on the same job simultaneously
      // Each worker's timer is independent and tracked with their userId

      // Resolve the hourly rate on the SERVER. Clients don't send a rate on
      // clock-in, so without this the entry silently defaulted to '85.00' even
      // when the worker's configured rate was higher (the "set 105, shows 85"
      // bug). Source-of-truth order:
      //   1. Per-job rate override for this worker (job_assignments)
      //   2. The worker's team-member employment rate (team_members)
      //   3. A rate the client explicitly sent (manual / legacy web flow)
      //   4. Legacy '85.00' fallback
      const hasUsableRate = (v: any) =>
        v !== null && v !== undefined && String(v).trim() !== '' &&
        !isNaN(parseFloat(String(v))) && parseFloat(String(v)) > 0;
      const rateCtx = await getUserContext(userId);
      let resolvedHourlyRate: string | null = null;
      if (data.jobId) {
        const assignments = await storage.getJobAssignments(data.jobId);
        const myAssignment = assignments.find(
          (a: any) => a.userId === userId && a.isActive !== false,
        );
        if (myAssignment && hasUsableRate(myAssignment.hourlyRateOverride)) {
          resolvedHourlyRate = String(myAssignment.hourlyRateOverride);
        }
      }
      if (!resolvedHourlyRate) {
        const memberRow = await storage.getTeamMemberByOwnerAndMemberId(
          rateCtx.effectiveUserId,
          userId,
        );
        if (memberRow && hasUsableRate(memberRow.hourlyRate)) {
          resolvedHourlyRate = String(memberRow.hourlyRate);
        }
      }
      if (!resolvedHourlyRate && hasUsableRate(data.hourlyRate)) {
        resolvedHourlyRate = String(data.hourlyRate);
      }
      // Last resort: the business's own default hourly rate. Only fall back to
      // the legacy hardcoded 85 when the business hasn't set a default either.
      if (!resolvedHourlyRate) {
        const bizForRate = await storage.getBusinessSettings(rateCtx.effectiveUserId);
        if (bizForRate && hasUsableRate((bizForRate as any).defaultHourlyRate)) {
          resolvedHourlyRate = String((bizForRate as any).defaultHourlyRate);
        }
      }
      const finalHourlyRate = resolvedHourlyRate || '85.00';

      const timeEntry = await storage.createTimeEntry({
        ...data,
        userId,
        startTime: data.startTime || new Date(),
        isBreak: data.isBreak || false,
        isOvertime: data.isOvertime || false,
        hourlyRate: finalHourlyRate, // Ensure string format for decimal
      } as InsertTimeEntry & { userId: string });
      
      // Get user context for broadcasts - effectiveUserId is the business owner ID
      const userContext = rateCtx;
      const businessId = userContext.effectiveUserId; // Business owner ID for broadcast targeting
      
      // Auto-update job status from "scheduled" to "in_progress" when timer starts
      if (data.jobId) {
        const job = await storage.getJob(data.jobId, businessId);
        if (job && job.status === 'scheduled') {
          await storage.updateJob(data.jobId, businessId, {
            status: 'in_progress',
            startedAt: new Date(),
          });
          
          // Broadcast job status change to all business users
          const { broadcastJobStatusChange } = await import('./websocket');
          broadcastJobStatusChange(businessId, {
            jobId: data.jobId,
            status: 'in_progress',
            title: job.title,
            updatedBy: userId,
          });
        }
        
        // Broadcast timer started event to all business users
        const { broadcastTimerEvent } = await import('./websocket');
        broadcastTimerEvent(businessId, {
          jobId: data.jobId,
          userId,
          action: 'started',
          timeEntryId: timeEntry.id,
        });
      }

      // Auto-update worker state to on_job
      await autoUpdateWorkerState(userId, 'on_job', data.jobId || null);
      
      if (idempKey) {
        await setIdempotencyRecord(idempKey, timeEntry);
      }
      res.status(201).json(timeEntry);
    } catch (error) {
      console.error('Error creating time entry:', error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: 'Invalid time entry data', details: error.errors });
      }
      res.status(500).json({ error: 'Failed to create time entry' });
    }
  });

  app.put("/api/time-entries/:id", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { id } = req.params;
      const data = insertTimeEntrySchema.partial().parse(req.body);
      const editReason = req.body.editReason || null;

      // Validate referenced job belongs to this business when re-pointing the entry
      if (data.jobId) {
        const tc = await getUserContext(userId);
        const ownedJob = await storage.getJob(data.jobId, tc.effectiveUserId);
        if (!ownedJob) {
          return res.status(404).json({ error: 'Job not found' });
        }
      }
      
      const existingEntry = await storage.getTimeEntry(id, userId);
      if (!existingEntry) {
        return res.status(404).json({ error: 'Time entry not found' });
      }
      
      let canManageEntry = (existingEntry as any).userId === userId;
      const isEditingSelf = (existingEntry as any).userId === userId;
      
      if (!canManageEntry && (existingEntry as any).userId !== userId) {
        const teamMembers = await storage.getTeamMembers(userId);
        const isTeamMember = teamMembers.some((member: any) => member.id === (existingEntry as any).userId);
        canManageEntry = isTeamMember;
      }
      
      if (!canManageEntry) {
        return res.status(403).json({ error: 'Access denied - not your time entry or team member' });
      }
      
      if (!existingEntry.endTime && data.startTime) {
        return res.status(400).json({ error: 'Cannot modify start time of active timer' });
      }
      
      const editSource = isEditingSelf ? 'manual' : 'supervisor';
      const fieldsToTrack = ['startTime', 'endTime', 'duration', 'hourlyRate', 'description', 'isBillable', 'timeCategory', 'isBreak', 'isOvertime', 'jobId'];
      
      for (const field of fieldsToTrack) {
        if ((data as any)[field] !== undefined) {
          const oldVal = (existingEntry as any)[field];
          const newVal = (data as any)[field];
          
          const oldStr = oldVal === null || oldVal === undefined ? null : String(oldVal instanceof Date ? oldVal.toISOString() : oldVal);
          const newStr = newVal === null || newVal === undefined ? null : String(newVal instanceof Date ? new Date(newVal).toISOString() : newVal);
          
          if (oldStr !== newStr) {
            await storage.createTimeEntryEdit({
              timeEntryId: id,
              editedBy: userId,
              editReason,
              fieldChanged: field,
              oldValue: oldStr,
              newValue: newStr,
              editSource,
            });
          }
        }
      }
      
      const timeEntry = await storage.updateTimeEntry(id, userId, data);
      if (!timeEntry) {
        return res.status(500).json({ error: 'Failed to update time entry' });
      }
      
      res.json(timeEntry);
    } catch (error) {
      console.error('Error updating time entry:', error);
      if (error instanceof z.ZodError) {
        return res.status(400).json({ error: 'Invalid time entry data', details: error.errors });
      }
      res.status(500).json({ error: 'Failed to update time entry' });
    }
  });

