  app.post("/api/time-entries/:id/stop", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { id } = req.params;
      
      // Verify ownership and current active status (with team/supervisor context)
      const existingEntry = await storage.getTimeEntry(id, userId);
      if (!existingEntry) {
        return res.status(404).json({ error: 'Time entry not found' });
      }
      
      if (existingEntry.endTime) {
        return res.status(400).json({ error: 'Time entry already stopped' });
      }
      
      // Allow supervisors to stop team member timers
      let canManageEntry = (existingEntry as any).userId === userId; // Owner can always manage
      
      // Check if current user can manage this entry (supervisor access)
      if (!canManageEntry && (existingEntry as any).userId !== userId) {
        // For now, implement basic supervisor logic - get all team members under this user
        const teamMembers = await storage.getTeamMembers(userId);
        const isTeamMember = teamMembers.some((member: any) => member.id === (existingEntry as any).userId);
        canManageEntry = isTeamMember;
      }
      
      if (!canManageEntry) {
        return res.status(403).json({ error: 'Access denied - not your time entry or team member' });
      }
      
      if (!validateGpsCoordinate(req.body.clockOutLatitude, req.body.clockOutLongitude)) {
        return res.status(400).json({ error: 'Invalid GPS coordinates for clock-out' });
      }
      
      const rawDistance = req.body.distanceKm;
      const parsedDistance = rawDistance != null ? parseFloat(String(rawDistance)) : NaN;
      const distanceKm = !isNaN(parsedDistance) && parsedDistance > 0 ? String(parsedDistance) : undefined;

      const locationData = {
        clockOutLatitude: req.body.clockOutLatitude ? String(req.body.clockOutLatitude) : undefined,
        clockOutLongitude: req.body.clockOutLongitude ? String(req.body.clockOutLongitude) : undefined,
        clockOutAddress: req.body.clockOutAddress || undefined,
        distanceKm,
      };
      
      const stoppedEntry = await storage.stopTimeEntry(id, userId, locationData);
      if (!stoppedEntry) {
        return res.status(500).json({ error: 'Failed to stop time entry' });
      }
      
      // Broadcast timer stopped event
      if (existingEntry.jobId) {
        const userContext = await getUserContext(userId);
        const businessId = userContext.effectiveUserId;
        const { broadcastTimerEvent } = await import('./websocket');
        broadcastTimerEvent(businessId, {
          jobId: existingEntry.jobId,
          userId: (existingEntry as any).userId || userId,
          action: 'stopped',
          timeEntryId: id,
        });
      }

      // Auto-update worker state to available
      await autoUpdateWorkerState((existingEntry as any).userId || userId, 'available', null);
      
      res.json(stoppedEntry);
    } catch (error) {
      console.error('Error stopping time entry:', error);
      res.status(500).json({ error: 'Failed to stop time entry' });
    }
  });

