  // List materials for a job

  // Create a material entry

  // Update a material
  app.patch("/api/materials/:id", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { id } = req.params;
      const effectiveUserId = req.effectiveUserId || userId;

      const existing = await storage.getJobMaterial(id, effectiveUserId);
      if (!existing) {
        return res.status(404).json({ error: "Material not found" });
      }

      const workerContext = await getWorkerPermissionContext(userId);
      if (workerContext.isWorker) {
        const allowedKeys = Object.keys(req.body);
        const onlyStatus = allowedKeys.every(k => k === 'status');
        if (!onlyStatus) {
          return res.status(403).json({ error: "Workers can only update material status" });
        }
      }

      // Validate phaseId belongs to this material's job — prevents cross-job/cross-business attribution
      if (req.body.phaseId) {
        const materialJobId = (existing as any).jobId;
        if (materialJobId) {
          const phases = await storage.getJobPhases(materialJobId, effectiveUserId);
          if (!phases.some((p: any) => p.id === req.body.phaseId)) {
            return res.status(400).json({ error: 'Phase not found or does not belong to this job' });
          }
        }
      }

      let updates = { ...req.body };
      // Strip server-controlled identity/ownership fields (mass-assignment guard)
      delete updates.id; delete updates.userId; delete updates.jobId; delete updates.createdAt; delete updates.updatedAt;

      if (updates.quantity !== undefined || updates.unitCost !== undefined) {
        const quantity = parseFloat(String(updates.quantity ?? existing.quantity ?? '1'));
        const unitCost = parseFloat(String(updates.unitCost ?? existing.unitCost ?? '0'));
        updates.totalCost = (quantity * unitCost).toFixed(2);
      }

      const updated = await storage.updateJobMaterial(id, effectiveUserId, updates);
      if (!updated) {
        return res.status(404).json({ error: "Material not found" });
      }

      res.json(updated);
    } catch (error: any) {
      console.error('Error updating job material:', error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/materials/:id/receipt-photo", requireAuth, async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { id } = req.params;
      const effectiveUserId = req.effectiveUserId || userId;

      const existing = await storage.getJobMaterial(id, effectiveUserId);
      if (!existing) {
        return res.status(404).json({ error: "Material not found" });
      }

      if (!req.body.image) {
        return res.status(400).json({ error: "No receipt image provided" });
      }

      const base64Data = req.body.image.replace(/^data:image\/\w+;base64,/, '');
      const imageBuffer = Buffer.from(base64Data, 'base64');

      if (imageBuffer.length > 10 * 1024 * 1024) {
        return res.status(400).json({ error: "Image too large. Maximum 10MB." });
      }

      let contentType = 'image/jpeg';
      let ext = 'jpg';
      const mimeMatch = req.body.image.match(/^data:(image\/\w+);base64,/);
      if (mimeMatch) {
        contentType = mimeMatch[1];
        ext = contentType.split('/')[1] || 'jpg';
      }

      const objectStorageService = new ObjectStorageService();
      const fileName = `material-receipts/${id}-${Date.now()}.${ext}`;
      const objectPath = await objectStorageService.uploadFile(fileName, imageBuffer, contentType);

      const updated = await storage.updateJobMaterial(id, effectiveUserId, { receiptPhotoUrl: objectPath });
      res.json(updated);
    } catch (error: any) {
      console.error('Error uploading material receipt:', error);
      res.status(500).json({ error: error.message });
    }
  });

