  // Get team member locations (for owners/managers only)
  app.get("/api/team/locations", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      
      console.log('[TeamLocations] User context:', { 
        userId: req.userId, 
        isOwner: userContext.isOwner, 
        effectiveUserId: userContext.effectiveUserId 
      });
      
      if (!userContext.isOwner && !hasPermission(userContext, PERMISSIONS.VIEW_ALL)) {
        console.log('[TeamLocations] Access denied for user:', req.userId);
        return res.status(403).json({ error: 'Access denied' });
      }
      
      const effectiveUserId = userContext.effectiveUserId;
      const allTeamMembers = await storage.getTeamMembers(effectiveUserId);
      const activeMembers = allTeamMembers.filter(m => m.inviteStatus === 'accepted' && m.isActive);
      
      console.log('[TeamLocations] Found', allTeamMembers.length, 'total team members,', activeMembers.length, 'active');

      // Read worker-chosen availability the SAME way Team Operations does:
      // resolve the business owner via team membership (NOT getUserContext's
      // effectiveUserId, which can differ for self-membership/owner accounts) and
      // pull every worker_state for the business in one query, keyed by userId.
      // This guarantees the map's Busy/Unavailable matches the Team Operations screen.
      const wsMembership = await storage.getTeamMembershipByMemberId(req.userId);
      const wsBusinessOwnerId = wsMembership?.businessOwnerId || req.userId;
      const workerStateByUserId = new Map<string, string>();
      try {
        const allWorkerStates = await storage.getWorkerStatesByBusiness(wsBusinessOwnerId);
        for (const ws of allWorkerStates) {
          if (ws.userId) workerStateByUserId.set(ws.userId, ws.state);
        }
      } catch (wsErr) {
        console.warn('[TeamLocations] Failed to load worker states:', wsErr);
      }

      const locations = [];
      
      for (const member of activeMembers) {
        if (!member.memberId) continue;
        
        const user = await storage.getUser(member.memberId);
        if (!user) continue;

        const role = member.roleId ? await storage.getUserRole(member.roleId) : null;
        const roleName = role?.name || 'Worker';
        const rnl = roleName.toLowerCase();
        const isSubcontractor = rnl.includes('subcontractor') || rnl.includes('sub_contractor');
        
        const recentLocation = await storage.getLatestLocationForUser(member.memberId);
        const tradieStatusData = await storage.getTradieStatus(member.memberId);
        // The availability the worker explicitly set (Available/Busy/Unavailable),
        // same source Team Operations reads. An explicit Busy/Unavailable must win
        // over the location-derived activity so the map matches Team Operations.
        const memberWorkerState = workerStateByUserId.get(member.memberId) || null;
        const explicitState = (memberWorkerState || '').toLowerCase();
        const overrideStatus = (explicitState === 'busy' || explicitState === 'unavailable') ? explicitState : null;
        
        const activeTimeEntry = await storage.getActiveTimeEntry(member.memberId);
        
        // Work Hours Ghost Mode: hide location outside work hours unless active timer
        if (member.afterHoursGhostMode && !activeTimeEntry) {
          const now = new Date();
          const memberWorkDays = (member.workDays as number[] | null) || [1, 2, 3, 4, 5];
          const currentDay = now.getDay(); // 0=Sun, 1=Mon...6=Sat
          const timeStr = now.toLocaleTimeString('en-AU', { hour: '2-digit', minute: '2-digit', hour12: false, timeZone: 'Australia/Sydney' });
          const startTime = member.workHoursStart || '07:00';
          const endTime = member.workHoursEnd || '17:00';
          const isWorkDay = memberWorkDays.includes(currentDay);
          const isDuringHours = isWorkDay && timeStr >= startTime && timeStr < endTime;
          
          if (!isDuringHours) {
            locations.push({
              id: member.memberId,
              name: `${member.firstName || user.firstName || ''} ${member.lastName || user.lastName || ''}`.trim() || user.email,
              email: user.email,
              profileImageUrl: user.profileImageUrl || null,
              themeColor: user.themeColor || null,
              latitude: null,
              longitude: null,
              lastUpdated: null,
              currentJobId: null,
              currentJobTitle: null,
              activityStatus: 'after_hours',
              speed: 0,
              batteryLevel: null,
              heading: null,
              isSubcontractor,
              roleName,
              activeJobName: null,
            });
            continue;
          }
        }

        let currentJob = null;
        if (activeTimeEntry?.jobId) {
          currentJob = await storage.getJob(activeTimeEntry.jobId, effectiveUserId);
        }

        if (!currentJob) {
          const memberJobs = await db.select().from(jobs)
            .where(and(
              eq(jobs.userId, effectiveUserId),
              eq(jobs.assignedTo, member.memberId!),
              eq(jobs.status, 'in_progress')
            ))
            .limit(1);
          if (memberJobs.length > 0) {
            currentJob = memberJobs[0];
          }
        }

        const hasActiveJob = !!currentJob && currentJob.status === 'in_progress';

        if (isSubcontractor && !hasActiveJob) {
          const isOnline = tradieStatusData?.activityStatus === 'online' || tradieStatusData?.activityStatus === 'on_job';
          locations.push({
            id: member.memberId,
            name: `${member.firstName || user.firstName || ''} ${member.lastName || user.lastName || ''}`.trim() || user.email,
            email: user.email,
            profileImageUrl: user.profileImageUrl || null,
            themeColor: user.themeColor || null,
            latitude: null,
            longitude: null,
            lastUpdated: null,
            currentJobId: null,
            currentJobTitle: null,
            activityStatus: 'offline',
            speed: 0,
            batteryLevel: null,
            heading: null,
            isSubcontractor: true,
            roleName,
            activeJobName: null,
            subbieStatus: isOnline ? 'available' : 'unavailable',
          });
          continue;
        }
        
        const buildLocationEntry = (lat: number, lng: number, lastUpdated: any, speed: number, batteryLevel: any, heading: any) => ({
          id: member.memberId,
          name: `${member.firstName || user.firstName || ''} ${member.lastName || user.lastName || ''}`.trim() || user.email,
          email: user.email,
          profileImageUrl: user.profileImageUrl || null,
          themeColor: user.themeColor || null,
          latitude: lat,
          longitude: lng,
          lastUpdated,
          currentJobId: currentJob?.id || null,
          currentJobTitle: currentJob?.title || null,
          activityStatus: overrideStatus || tradieStatusData?.activityStatus || 'online',
          workerState: memberWorkerState,
          speed,
          batteryLevel,
          heading,
          isSubcontractor,
          roleName,
          activeJobName: isSubcontractor && hasActiveJob ? currentJob?.title : null,
          subbieStatus: isSubcontractor ? (hasActiveJob ? 'on_job' : 'available') : undefined,
        });

        if (recentLocation) {
          const speed = recentLocation.speed ? parseFloat(recentLocation.speed) : 
                        tradieStatusData?.speed ? parseFloat(tradieStatusData.speed) : 0;
          locations.push(buildLocationEntry(
            parseFloat(recentLocation.latitude),
            parseFloat(recentLocation.longitude),
            recentLocation.timestamp,
            speed,
            tradieStatusData?.batteryLevel || recentLocation.batteryLevel || null,
            recentLocation.heading ? parseFloat(recentLocation.heading) : null,
          ));
        } else if (tradieStatusData?.currentLatitude && tradieStatusData?.currentLongitude) {
          const speed = tradieStatusData.speed ? parseFloat(tradieStatusData.speed) : 0;
          locations.push(buildLocationEntry(
            parseFloat(tradieStatusData.currentLatitude),
            parseFloat(tradieStatusData.currentLongitude),
            tradieStatusData.lastLocationUpdate || tradieStatusData.lastSeenAt,
            speed,
            tradieStatusData.batteryLevel || null,
            tradieStatusData.heading ? parseFloat(tradieStatusData.heading) : null,
          ));
        } else if (!isSubcontractor) {
          locations.push({
            id: member.memberId,
            name: `${member.firstName || user.firstName || ''} ${member.lastName || user.lastName || ''}`.trim() || user.email,
            email: user.email,
            profileImageUrl: user.profileImageUrl || null,
            themeColor: user.themeColor || null,
            latitude: null,
            longitude: null,
            lastUpdated: null,
            currentJobId: currentJob?.id || null,
            currentJobTitle: currentJob?.title || null,
            activityStatus: 'offline',
            speed: 0,
            batteryLevel: null,
            heading: null,
            isSubcontractor: false,
            roleName,
            activeJobName: null,
            subbieStatus: undefined,
          });
        }
      }
      
      console.log('[TeamLocations] Returning', locations.length, 'locations');
      res.json(locations);
    } catch (error: any) {
      console.error('Error fetching team locations:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Geocode an address (uses OpenStreetMap Nominatim - free)
  app.post("/api/geocode", requireAuth, async (req: any, res) => {
    try {
      const { address } = req.body;
      if (!address) {
        return res.status(400).json({ error: 'Address is required' });
      }
      
      // Use OpenStreetMap Nominatim for geocoding (free, no API key needed)
      const encodedAddress = encodeURIComponent(address);
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encodedAddress}&limit=1`,
        {
          headers: {
            'User-Agent': 'JobRunner/1.0'
          }
        }
      );
      
      if (!response.ok) {
        throw new Error('Geocoding request failed');
      }
      
      const results = await response.json();
      
      if (results.length === 0) {
        return res.status(404).json({ error: 'Address not found' });
      }
      
      const result = results[0];
      res.json({
        latitude: parseFloat(result.lat),
        longitude: parseFloat(result.lon),
        displayName: result.display_name,
      });
    } catch (error: any) {
      console.error('Error geocoding address:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Update job coordinates after geocoding

  // ===== JOB MAP ROUTES =====
  
  // Helper to validate coordinates are within valid ranges
  function isValidCoordinate(lat: number, lng: number): boolean {
    return Number.isFinite(lat) && Number.isFinite(lng) &&
           lat >= -90 && lat <= 90 &&
           lng >= -180 && lng <= 180 &&
           !(lat === 0 && lng === 0); // Exclude 0,0 which is often a default/error value
  }
  
  // Calculate distance between two coordinates in meters (Haversine formula)
  function calculateDistance(lat1: number, lon1: number, lat2: number, lon2: number): number {
    const R = 6371000; // Earth's radius in meters
    const dLat = (lat2 - lat1) * Math.PI / 180;
    const dLon = (lon2 - lon1) * Math.PI / 180;
    const a = Math.sin(dLat / 2) * Math.sin(dLat / 2) +
              Math.cos(lat1 * Math.PI / 180) * Math.cos(lat2 * Math.PI / 180) *
              Math.sin(dLon / 2) * Math.sin(dLon / 2);
    const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a));
    return R * c;
  }
  
  // Get jobs with coordinates for map display
  app.get("/api/map/jobs", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      let jobs = await storage.getJobs(userContext.effectiveUserId);
      
      // Team members without VIEW_ALL (staff tradies and subcontractors) only see
      // their assigned jobs on the map — must match the /api/jobs (Work view) gate,
      // otherwise the map leaks every business job to a plain worker.
      const mapHasViewAll = userContext.permissions.includes('view_all') || userContext.isOwner;
      if (!mapHasViewAll && userContext.teamMemberId) {
        jobs = jobs.filter(job => 
          job.assignedTo === userContext.userId || 
          job.assignedTo === userContext.teamMemberId
        );
      }
      
      // Batch fetch all clients for efficiency
      const clients = await storage.getClients(userContext.effectiveUserId);
      const clientMap = new Map(clients.map(c => [c.id, c]));
      
      // Process jobs - geocode those with addresses but no coordinates
      const processedJobs = await Promise.all(
        jobs.map(async (job) => {
          let lat = job.latitude ? parseFloat(job.latitude) : null;
          let lng = job.longitude ? parseFloat(job.longitude) : null;
          
          // If no valid coordinates but has address, try to geocode
          if ((!lat || !lng || !isValidCoordinate(lat, lng)) && job.address) {
            try {
              const coords = await geocodeAddress(job.address);
              if (coords) {
                lat = coords.latitude;
                lng = coords.longitude;
                // Update job with coordinates for future use (fire and forget)
                storage.updateJob(job.id, userContext.effectiveUserId, {
                  latitude: lat.toString(),
                  longitude: lng.toString()
                }).catch(e => console.error(`Failed to save geocoded coords for job ${job.id}:`, e));
              }
            } catch (e) {
              // Geocoding failed, skip this job for map display
            }
          }
          
          return { ...job, lat, lng };
        })
      );
      
      // Transform jobs to map data format - only include jobs with valid coordinates
      const mapData = processedJobs
        .filter(job => job.lat && job.lng && isValidCoordinate(job.lat, job.lng))
        .map(job => {
          const client = job.clientId ? clientMap.get(job.clientId) : null;
          return {
            id: job.id,
            title: job.title,
            address: job.address || '',
            latitude: job.lat!,
            longitude: job.lng!,
            status: job.status,
            scheduledAt: job.scheduledAt,
            assignedTo: job.assignedTo,
            clientName: client ? (client.name || client.email || 'Unknown Client') : 'No Client',
            clientPhone: client?.phone || '',
          };
        });
      
      res.json(mapData);
    } catch (error: any) {
      console.error('Error fetching map jobs:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Get team member locations (Life360-style enhanced data)
  app.get("/api/map/team-locations", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      // Same gate as /api/team/locations: only owners or members with the
      // view_all permission may see everyone's live locations on the map.
      if (!userContext.isOwner && !hasPermission(userContext, PERMISSIONS.VIEW_ALL)) {
        return res.status(403).json({ error: 'Access denied' });
      }
      const allTeamMembers = await storage.getTeamMembers(userContext.effectiveUserId);
      
      const locations = await Promise.all(
        allTeamMembers.map(async (member) => {
          if (!member.memberId) return null;
          
          const role = member.roleId ? await storage.getUserRole(member.roleId) : null;
          const memberRoleName = role?.name || 'Worker';
          const mrl = memberRoleName.toLowerCase();
          const isSubcontractor = mrl.includes('subcontractor') || mrl.includes('sub_contractor');

          const status = await storage.getTradieStatus(member.memberId);
          const location = await storage.getLatestLocationForUser(member.memberId);
          const user = await storage.getUser(member.memberId);
          // The availability the worker explicitly set (Available/Busy/Unavailable),
          // same source Team Operations reads. The map must reflect this, not just
          // the location-derived activity (online/working/offline).
          const workerStateRow = await storage.getWorkerState(member.memberId, userContext.effectiveUserId);
          
          let currentJobTitle = undefined;
          let currentJobId = status?.currentJobId || location?.jobId;
          let activeJob = null;

          if (currentJobId) {
            activeJob = await storage.getJob(currentJobId, userContext.effectiveUserId);
            currentJobTitle = activeJob?.title || 'On Job';
          }

          // A subcontractor's map visibility depends on having an in-progress job.
          // tradie_status.current_job_id can be stale (point to a now-'done' job),
          // which would otherwise leave activeJob set to a non-in-progress job and
          // hide a subcontractor who actually IS on an active job. So run the
          // in-progress lookup whenever the resolved job isn't in_progress.
          if ((!activeJob || activeJob.status !== 'in_progress') && isSubcontractor) {
            const memberJobs = await db.select().from(jobs)
              .where(and(
                eq(jobs.userId, userContext.effectiveUserId),
                eq(jobs.assignedTo, member.memberId!),
                eq(jobs.status, 'in_progress')
              ))
              .limit(1);
            if (memberJobs.length > 0) {
              activeJob = memberJobs[0];
              currentJobId = activeJob.id;
              currentJobTitle = activeJob.title;
            }
          }

          const hasActiveJob = !!activeJob && activeJob.status === 'in_progress';

          if (isSubcontractor && !hasActiveJob) {
            return null;
          }

          const lat = status?.currentLatitude ? parseFloat(status.currentLatitude) : 
                      location?.latitude ? parseFloat(location.latitude) : null;
          const lng = status?.currentLongitude ? parseFloat(status.currentLongitude) :
                      location?.longitude ? parseFloat(location.longitude) : null;
          
          if (lat == null || lng == null) return null;
          if (!isValidCoordinate(lat, lng)) return null;
          
          const lastActivity = status?.lastSeenAt || location?.timestamp;
          const isActive = lastActivity ? 
            (Date.now() - new Date(lastActivity).getTime()) < 15 * 60 * 1000 : false;
          
          const activityStatus = status?.activityStatus || 'offline';
          const speed = status?.speed ? parseFloat(status.speed) : 
                        location?.speed ? parseFloat(location.speed) : 0;
          const isDriving = speed > 5;
          
          return {
            id: member.memberId,
            name: `${member.firstName || user?.firstName || ''} ${member.lastName || user?.lastName || ''}`.trim() || member.email,
            email: member.email,
            profileImageUrl: user?.profileImageUrl || null,
            themeColor: user?.themeColor || null,
            latitude: lat,
            longitude: lng,
            lastSeenAt: status?.lastSeenAt || location?.timestamp,
            activityStatus: activityStatus,
            workerState: workerStateRow?.state || null,
            isActive: isActive,
            isDriving: isDriving,
            speed: speed,
            heading: status?.heading ? parseFloat(status.heading) : 
                     location?.heading ? parseFloat(location.heading) : null,
            batteryLevel: status?.batteryLevel || location?.batteryLevel || null,
            isCharging: status?.isCharging || location?.isCharging || false,
            currentJobId: currentJobId,
            currentJobTitle: currentJobTitle,
            currentAddress: status?.currentAddress || location?.address || null,
            isSubcontractor,
            roleName: memberRoleName,
            activeJobName: isSubcontractor && hasActiveJob ? currentJobTitle : undefined,
          };
        })
      );
      
      res.json(locations.filter(Boolean));
    } catch (error: any) {
      console.error('Error fetching team locations:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Update tradie's own location and status (called from tradie's device)
