  // ===== REPORTING ROUTES =====

  // Multi-job profitability overview report
  app.get("/api/reports/profitability", requireAuth, requirePaidTier(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);

      if (!userContext.isOwner) {
        return res.status(403).json({ error: 'Access denied - owners only' });
      }

      const effectiveUserId = userContext.effectiveUserId;
      const { startDate, endDate, status } = req.query;

      let jobs = await storage.getJobs(effectiveUserId);

      if (status) {
        jobs = jobs.filter(j => j.status === status);
      }
      if (startDate) {
        jobs = jobs.filter(j => new Date(j.createdAt!) >= new Date(startDate as string));
      }
      if (endDate) {
        jobs = jobs.filter(j => new Date(j.createdAt!) <= new Date(endDate as string));
      }

      const allInvoices = await storage.getInvoices(effectiveUserId);
      const allExpenses = await storage.getExpenses(effectiveUserId);
      const allQuotes = await storage.getQuotes(effectiveUserId);

      const reportTeamMembers = await storage.getTeamMembers(effectiveUserId);
      const reportSubcontractorUserIds = new Set<string>();
      for (const member of reportTeamMembers) {
        if (member.roleId) {
          try {
            const role = await storage.getUserRole(member.roleId);
            if (role?.name?.toLowerCase().includes('subcontractor')) {
              if (member.memberId) reportSubcontractorUserIds.add(member.memberId);
              reportSubcontractorUserIds.add(member.id);
            }
          } catch (e) {}
        }
      }

      let totalRevenue = 0;
      let totalCosts = 0;
      let jobsProfitable = 0;
      let jobsAtLoss = 0;

      const jobProfitability = await Promise.all(jobs.map(async (job) => {
        const jobInvoices = allInvoices.filter(i => i.jobId === job.id && i.status === 'paid');
        const revenue = jobInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);

        const jobQuote = allQuotes.find(q => q.jobId === job.id && (q.status === 'accepted' || q.status === 'sent'));
        const quotedAmount = jobQuote ? parseFloat(jobQuote.total || '0') : null;

        const jobExpenses = allExpenses.filter(e => e.jobId === job.id);
        const expenseCost = jobExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

        const subExpenses = jobExpenses.filter(e => {
          const desc = (e.description || '').toLowerCase();
          const cat = ((e as any).category || (e as any).categoryName || '').toLowerCase();
          return cat.includes('subcontractor') || desc.includes('subcontractor');
        });
        const subExpenseCost = subExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

        const timeEntries = await storage.getTimeEntries(effectiveUserId, job.id);
        const completedTimeEntries = timeEntries.filter(e => e.endTime);

        const employeeTimeEntries = completedTimeEntries.filter(e => !reportSubcontractorUserIds.has(e.userId));
        const subTimeEntries = completedTimeEntries.filter(e => reportSubcontractorUserIds.has(e.userId));

        const calcCost = (e: any) => {
          const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
          return hours * parseFloat(e.hourlyRate?.toString() || '0');
        };

        const labourCost = employeeTimeEntries.reduce((sum, e) => sum + calcCost(e), 0);
        const subTimeCost = subTimeEntries.reduce((sum, e) => sum + calcCost(e), 0);
        const subcontractorCost = subTimeCost + subExpenseCost;

        let materialsCost = 0;
        try {
          const materials = await storage.getJobMaterials(job.id, effectiveUserId);
          materialsCost = materials.reduce((sum, m) => sum + parseFloat(m.totalCost?.toString() || '0'), 0);
        } catch (e) { /* no materials */ }

        const otherExpenseCost = expenseCost - subExpenseCost;
        const costs = otherExpenseCost + labourCost + subcontractorCost + materialsCost;
        const profit = revenue - costs;
        const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

        totalRevenue += revenue;
        totalCosts += costs;
        if (margin > 5) jobsProfitable++;
        else if (revenue > 0) jobsAtLoss++;

        let clientName = null;
        try {
          if (job.clientId) {
            const client = await storage.getClientById(job.clientId);
            clientName = client ? `${(client as any).firstName || ''} ${(client as any).lastName || ''}`.trim() : null;
          }
        } catch (e) {}

        const totalHours = completedTimeEntries.reduce((sum, e) => {
          return sum + (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
        }, 0);

        return {
          jobId: job.id,
          title: job.title,
          status: job.status,
          clientId: job.clientId || null,
          clientName,
          assignedTo: (job as any).assignedTo || null,
          quoted: quotedAmount,
          revenue,
          labourCost,
          subcontractorCost,
          materialCost: materialsCost,
          expenseCost: otherExpenseCost,
          costs,
          profit,
          margin: parseFloat(margin.toFixed(1)),
          profitStatus: margin > 15 ? 'profitable' : margin > 5 ? 'tight' : 'loss',
          completedAt: (job as any).completedAt || null,
          createdAt: job.createdAt,
          totalHours: parseFloat(totalHours.toFixed(1)),
        };
      }));

      jobProfitability.sort((a, b) => {
        const dateA = new Date(a.completedAt || a.createdAt || 0).getTime();
        const dateB = new Date(b.completedAt || b.createdAt || 0).getTime();
        return dateB - dateA;
      });

      const totalProfit = totalRevenue - totalCosts;
      const avgMargin = totalRevenue > 0 ? (totalProfit / totalRevenue) * 100 : 0;

      res.json({
        summary: {
          totalRevenue,
          totalCosts,
          totalProfit,
          averageMargin: parseFloat(avgMargin.toFixed(1)),
          jobsAnalyzed: jobs.length,
          jobsProfitable,
          jobsAtLoss,
          jobsNoRevenue: jobs.length - jobsProfitable - jobsAtLoss,
        },
        jobs: jobProfitability,
      });
    } catch (error) {
      console.error("Error generating profitability report:", error);
      res.status(500).json({ error: "Failed to generate profitability report" });
    }
  });

  app.get("/api/reports/profitability/by-client", requireAuth, requirePaidTier(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      const isOwnerOrManager = userContext.isOwner || userContext.permissions.includes(PERMISSIONS.MANAGE_TEAM);
      if (!isOwnerOrManager) return res.status(403).json({ error: 'Access denied - owners and managers only' });
      const effectiveUserId = userContext.effectiveUserId;
      const { startDate, endDate } = req.query;

      let jobs = await storage.getJobs(effectiveUserId);
      if (startDate) jobs = jobs.filter(j => new Date(j.createdAt!) >= new Date(startDate as string));
      if (endDate) jobs = jobs.filter(j => new Date(j.createdAt!) <= new Date(endDate as string));

      const allInvoices = await storage.getInvoices(effectiveUserId);
      const allExpenses = await storage.getExpenses(effectiveUserId);

      const clientMap: Record<string, { clientId: string; clientName: string; jobCount: number; totalRevenue: number; totalCosts: number; totalProfit: number; margins: number[] }> = {};

      await Promise.all(jobs.map(async (job) => {
        const cid = job.clientId || 'no-client';
        if (!clientMap[cid]) {
          let clientName = 'No Client';
          try {
            if (job.clientId) {
              const client = await storage.getClientById(job.clientId);
              clientName = client ? `${(client as any).firstName || ''} ${(client as any).lastName || ''}`.trim() || 'Unknown' : 'Unknown';
            }
          } catch (e) {}
          clientMap[cid] = { clientId: cid, clientName, jobCount: 0, totalRevenue: 0, totalCosts: 0, totalProfit: 0, margins: [] };
        }
        const entry = clientMap[cid];
        entry.jobCount++;

        const jobInvoices = allInvoices.filter(i => i.jobId === job.id && i.status === 'paid');
        const revenue = jobInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);
        const jobExpenses = allExpenses.filter(e => e.jobId === job.id);
        const expenseCost = jobExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);
        const timeEntries = await storage.getTimeEntries(effectiveUserId, job.id);
        const labourCost = timeEntries.filter(e => e.endTime).reduce((sum, e) => {
          const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
          return sum + (hours * parseFloat(e.hourlyRate?.toString() || '0'));
        }, 0);
        let materialsCost = 0;
        try { const m = await storage.getJobMaterials(job.id, effectiveUserId); materialsCost = m.reduce((s, x) => s + parseFloat(x.totalCost?.toString() || '0'), 0); } catch (e) {}

        const costs = expenseCost + labourCost + materialsCost;
        const profit = revenue - costs;
        const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

        entry.totalRevenue += revenue;
        entry.totalCosts += costs;
        entry.totalProfit += profit;
        if (revenue > 0) entry.margins.push(margin);
      }));

      const clients = Object.values(clientMap).map(c => ({
        ...c,
        avgMargin: c.margins.length > 0 ? parseFloat((c.margins.reduce((a, b) => a + b, 0) / c.margins.length).toFixed(1)) : 0,
        margins: undefined,
      })).sort((a, b) => b.totalProfit - a.totalProfit);

      res.json({ clients });
    } catch (error) {
      console.error("Error generating by-client profitability:", error);
      res.status(500).json({ error: "Failed to generate by-client report" });
    }
  });

  app.get("/api/reports/profitability/by-worker", requireAuth, requirePaidTier(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      const isOwnerOrManager = userContext.isOwner || userContext.permissions.includes(PERMISSIONS.MANAGE_TEAM);
      if (!isOwnerOrManager) return res.status(403).json({ error: 'Access denied - owners and managers only' });
      const effectiveUserId = userContext.effectiveUserId;
      const { startDate, endDate } = req.query;

      let jobs = await storage.getJobs(effectiveUserId);
      if (startDate) jobs = jobs.filter(j => new Date(j.createdAt!) >= new Date(startDate as string));
      if (endDate) jobs = jobs.filter(j => new Date(j.createdAt!) <= new Date(endDate as string));

      const allInvoices = await storage.getInvoices(effectiveUserId);
      const teamMembers = await storage.getTeamMembers(effectiveUserId);

      const workerMap: Record<string, { workerId: string; workerName: string; jobCount: number; totalHours: number; totalLabourCost: number; revenueGenerated: number; avgHourlyRate: number; rateEntries: number[] }> = {};

      await Promise.all(jobs.map(async (job) => {
        const assignee = (job as any).assignedTo;
        if (!assignee) return;

        if (!workerMap[assignee]) {
          let workerName = 'Unknown Worker';
          const member = teamMembers.find((m: any) => m.id === assignee || m.memberId === assignee);
          if (member) {
            workerName = (member as any).name || 'Team Member';
          } else {
            try {
              const user = await storage.getUser(assignee);
              if (user) workerName = `${user.firstName || ''} ${user.lastName || ''}`.trim() || 'Unknown';
            } catch (e) {}
          }
          workerMap[assignee] = { workerId: assignee, workerName, jobCount: 0, totalHours: 0, totalLabourCost: 0, revenueGenerated: 0, avgHourlyRate: 0, rateEntries: [] };
        }
        const entry = workerMap[assignee];
        entry.jobCount++;

        const jobInvoices = allInvoices.filter(i => i.jobId === job.id && i.status === 'paid');
        const revenue = jobInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);
        entry.revenueGenerated += revenue;

        const timeEntries = await storage.getTimeEntries(effectiveUserId, job.id);
        timeEntries.filter(e => e.endTime).forEach(e => {
          const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
          const rate = parseFloat(e.hourlyRate?.toString() || '0');
          entry.totalHours += hours;
          entry.totalLabourCost += hours * rate;
          if (rate > 0) entry.rateEntries.push(rate);
        });
      }));

      const workers = Object.values(workerMap).map(w => ({
        ...w,
        totalHours: parseFloat(w.totalHours.toFixed(1)),
        avgHourlyRate: w.rateEntries.length > 0 ? parseFloat((w.rateEntries.reduce((a, b) => a + b, 0) / w.rateEntries.length).toFixed(2)) : 0,
        rateEntries: undefined,
      })).sort((a, b) => b.revenueGenerated - a.revenueGenerated);

      res.json({ workers });
    } catch (error) {
      console.error("Error generating by-worker profitability:", error);
      res.status(500).json({ error: "Failed to generate by-worker report" });
    }
  });

  app.get("/api/reports/profitability/by-job-type", requireAuth, requirePaidTier(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      if (!userContext.isOwner) {
        return res.status(403).json({ error: 'Access denied - owners only' });
      }
      const effectiveUserId = userContext.effectiveUserId;
      const { startDate, endDate } = req.query;

      let allJobs = await storage.getJobs(effectiveUserId);
      if (startDate) {
        allJobs = allJobs.filter(j => new Date(j.createdAt!) >= new Date(startDate as string));
      }
      if (endDate) {
        allJobs = allJobs.filter(j => new Date(j.createdAt!) <= new Date(endDate as string));
      }

      const allInvoices = await storage.getInvoices(effectiveUserId);
      const allExpenses = await storage.getExpenses(effectiveUserId);

      const jtTeamMembers = await storage.getTeamMembers(effectiveUserId);
      const jtSubcontractorUserIds = new Set<string>();
      for (const member of jtTeamMembers) {
        if (member.roleId) {
          try {
            const role = await storage.getUserRole(member.roleId);
            if (role?.name?.toLowerCase().includes('subcontractor')) {
              if (member.memberId) jtSubcontractorUserIds.add(member.memberId);
              jtSubcontractorUserIds.add(member.id);
            }
          } catch (e) {}
        }
      }

      const typeMap: Record<string, {
        jobType: string;
        jobCount: number;
        totalRevenue: number;
        totalLabourCost: number;
        totalSubcontractorCost: number;
        totalMaterialCost: number;
        totalExpenseCost: number;
        totalCosts: number;
        totalProfit: number;
        totalHours: number;
      }> = {};

      await Promise.all(allJobs.map(async (job) => {
        const jobType = job.title?.trim() || 'Uncategorised';

        if (!typeMap[jobType]) {
          typeMap[jobType] = { jobType, jobCount: 0, totalRevenue: 0, totalLabourCost: 0, totalSubcontractorCost: 0, totalMaterialCost: 0, totalExpenseCost: 0, totalCosts: 0, totalProfit: 0, totalHours: 0 };
        }
        const entry = typeMap[jobType];
        entry.jobCount++;

        const jobInvoices = allInvoices.filter(i => i.jobId === job.id && i.status === 'paid');
        const revenue = jobInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);
        entry.totalRevenue += revenue;

        const jobExpenses = allExpenses.filter(e => e.jobId === job.id);
        const expenseCost = jobExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

        const jtSubExpenses = jobExpenses.filter(e => {
          const desc = (e.description || '').toLowerCase();
          const cat = ((e as any).category || (e as any).categoryName || '').toLowerCase();
          return cat.includes('subcontractor') || desc.includes('subcontractor');
        });
        const jtSubExpenseCost = jtSubExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

        entry.totalExpenseCost += expenseCost - jtSubExpenseCost;

        const timeEntries = await storage.getTimeEntries(effectiveUserId, job.id);
        const completedTE = timeEntries.filter(e => e.endTime);
        const employeeTE = completedTE.filter(e => !jtSubcontractorUserIds.has(e.userId));
        const subTE = completedTE.filter(e => jtSubcontractorUserIds.has(e.userId));

        const calcHrCost = (e: any) => {
          const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
          return hours * parseFloat(e.hourlyRate?.toString() || '0');
        };

        const labourCost = employeeTE.reduce((sum, e) => sum + calcHrCost(e), 0);
        const subTimeCost = subTE.reduce((sum, e) => sum + calcHrCost(e), 0);
        entry.totalLabourCost += labourCost;
        entry.totalSubcontractorCost += subTimeCost + jtSubExpenseCost;

        const hours = completedTE.reduce((sum, e) => {
          return sum + (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
        }, 0);
        entry.totalHours += hours;

        let materialsCost = 0;
        try {
          const materials = await storage.getJobMaterials(job.id, effectiveUserId);
          materialsCost = materials.reduce((sum, m) => sum + parseFloat(m.totalCost?.toString() || '0'), 0);
        } catch (e) {}
        entry.totalMaterialCost += materialsCost;

        const costs = (expenseCost - jtSubExpenseCost) + labourCost + (subTimeCost + jtSubExpenseCost) + materialsCost;
        entry.totalCosts += costs;
        entry.totalProfit += revenue - costs;
      }));

      const jobTypes = Object.values(typeMap).map(t => ({
        ...t,
        avgMargin: t.totalRevenue > 0 ? parseFloat(((t.totalProfit / t.totalRevenue) * 100).toFixed(1)) : 0,
        totalHours: parseFloat(t.totalHours.toFixed(1)),
      })).sort((a, b) => b.totalRevenue - a.totalRevenue);

      const best = jobTypes.length > 0 ? jobTypes.reduce((a, b) => a.avgMargin > b.avgMargin ? a : b) : null;
      const worst = jobTypes.length > 0 ? jobTypes.reduce((a, b) => a.avgMargin < b.avgMargin ? a : b) : null;

      let previousPeriodTypes: Record<string, { avgMargin: number }> = {};
      if (startDate && endDate) {
        const start = new Date(startDate as string);
        const end = new Date(endDate as string);
        const duration = end.getTime() - start.getTime();
        const prevStart = new Date(start.getTime() - duration);
        const prevEnd = new Date(start.getTime());

        let prevJobs = await storage.getJobs(effectiveUserId);
        prevJobs = prevJobs.filter(j => {
          const d = new Date(j.createdAt!);
          return d >= prevStart && d < prevEnd;
        });

        const prevTypeMap: Record<string, { revenue: number; costs: number }> = {};
        await Promise.all(prevJobs.map(async (job) => {
          const jobType = job.title?.trim() || 'Uncategorised';
          if (!prevTypeMap[jobType]) prevTypeMap[jobType] = { revenue: 0, costs: 0 };

          const jobInvoices = allInvoices.filter(i => i.jobId === job.id && i.status === 'paid');
          const revenue = jobInvoices.reduce((sum, i) => sum + parseFloat(i.total || '0'), 0);
          prevTypeMap[jobType].revenue += revenue;

          const jobExpenses = allExpenses.filter(e => e.jobId === job.id);
          const expenseCost = jobExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

          const timeEntries = await storage.getTimeEntries(effectiveUserId, job.id);
          const labourCost = timeEntries.filter(e => e.endTime).reduce((sum, e) => {
            const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
            return sum + (hours * parseFloat(e.hourlyRate?.toString() || '0'));
          }, 0);

          let materialsCost = 0;
          try {
            const materials = await storage.getJobMaterials(job.id, effectiveUserId);
            materialsCost = materials.reduce((sum, m) => sum + parseFloat(m.totalCost?.toString() || '0'), 0);
          } catch (e) {}

          prevTypeMap[jobType].costs += expenseCost + labourCost + materialsCost;
        }));

        for (const [type, data] of Object.entries(prevTypeMap)) {
          previousPeriodTypes[type] = {
            avgMargin: data.revenue > 0 ? parseFloat(((( data.revenue - data.costs) / data.revenue) * 100).toFixed(1)) : 0,
          };
        }
      }

      const jobTypesWithTrend = jobTypes.map(t => ({
        ...t,
        previousMargin: previousPeriodTypes[t.jobType]?.avgMargin ?? null,
        marginChange: previousPeriodTypes[t.jobType] != null ? parseFloat((t.avgMargin - previousPeriodTypes[t.jobType].avgMargin).toFixed(1)) : null,
      }));

      res.json({
        jobTypes: jobTypesWithTrend,
        best: best ? { jobType: best.jobType, avgMargin: best.avgMargin } : null,
        worst: worst ? { jobType: worst.jobType, avgMargin: worst.avgMargin } : null,
      });
    } catch (error) {
      console.error("Error generating by-job-type profitability:", error);
      res.status(500).json({ error: "Failed to generate by-job-type report" });
    }
  });

  app.get("/api/reports/profitability/trend", requireAuth, requirePaidTier(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      if (!userContext.isOwner) {
        return res.status(403).json({ error: 'Access denied - owners only' });
      }
      const effectiveUserId = userContext.effectiveUserId;

      const now = new Date();
      const months: { year: number; month: number; label: string; startDate: Date; endDate: Date }[] = [];
      for (let i = 11; i >= 0; i--) {
        const d = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const endD = new Date(d.getFullYear(), d.getMonth() + 1, 0, 23, 59, 59, 999);
        months.push({
          year: d.getFullYear(),
          month: d.getMonth(),
          label: d.toLocaleDateString('en-AU', { month: 'short', year: '2-digit' }),
          startDate: d,
          endDate: endD,
        });
      }

      const allJobs = await storage.getJobs(effectiveUserId);
      const allInvoices = await storage.getInvoices(effectiveUserId);
      const allExpenses = await storage.getExpenses(effectiveUserId);

      const teamMembers = await storage.getTeamMembers(effectiveUserId);
      const subcontractorIds = new Set<string>();
      for (const member of teamMembers) {
        if (member.roleId) {
          try {
            const role = await storage.getUserRole(member.roleId);
            if (role?.name?.toLowerCase().includes('subcontractor')) {
              if (member.memberId) subcontractorIds.add(member.memberId);
              subcontractorIds.add(member.id);
            }
          } catch (e) {}
        }
      }

      const jobTimeEntriesCache: Record<string, any[]> = {};

      const trend = await Promise.all(months.map(async (m) => {
        const monthInvoices = allInvoices.filter(inv => {
          if (inv.status !== 'paid' || !inv.paidAt) return false;
          const paidDate = new Date(inv.paidAt);
          return paidDate >= m.startDate && paidDate <= m.endDate;
        });
        const revenue = monthInvoices.reduce((sum, inv) => sum + parseFloat(inv.total || '0'), 0);

        const monthExpenses = allExpenses.filter(exp => {
          const expDate = exp.expenseDate ? new Date(exp.expenseDate) : (exp.createdAt ? new Date(exp.createdAt) : null);
          return expDate && expDate >= m.startDate && expDate <= m.endDate;
        });
        const expenseCost = monthExpenses.reduce((sum, e) => sum + parseFloat(e.amount || '0'), 0);

        const jobIdsInMonth = new Set<string>();
        monthInvoices.forEach(inv => { if (inv.jobId) jobIdsInMonth.add(inv.jobId); });
        monthExpenses.forEach(exp => { if (exp.jobId) jobIdsInMonth.add(exp.jobId); });

        let labourCost = 0;
        for (const jobId of jobIdsInMonth) {
          if (!jobTimeEntriesCache[jobId]) {
            jobTimeEntriesCache[jobId] = await storage.getTimeEntries(effectiveUserId, jobId);
          }
          const entries = jobTimeEntriesCache[jobId].filter(e => {
            if (!e.endTime) return false;
            const entryDate = new Date(e.startTime);
            return entryDate >= m.startDate && entryDate <= m.endDate;
          });
          labourCost += entries.reduce((sum, e) => {
            const hours = (new Date(e.endTime!).getTime() - new Date(e.startTime).getTime()) / (1000 * 60 * 60);
            return sum + hours * parseFloat(e.hourlyRate?.toString() || '0');
          }, 0);
        }

        const totalCosts = expenseCost + labourCost;
        const profit = revenue - totalCosts;
        const margin = revenue > 0 ? (profit / revenue) * 100 : 0;

        return {
          month: m.label,
          revenue: parseFloat(revenue.toFixed(2)),
          costs: parseFloat(totalCosts.toFixed(2)),
          profit: parseFloat(profit.toFixed(2)),
          margin: parseFloat(margin.toFixed(1)),
        };
      }));

      res.json({ trend });
    } catch (error) {
      console.error("Error generating profitability trend:", error);
      res.status(500).json({ error: "Failed to generate profitability trend" });
    }
  });

  // Get business performance summary
  app.get("/api/reports/summary", requireAuth, requirePaidTier(), createPermissionMiddleware(PERMISSIONS.READ_REPORTS), async (req: any, res) => {
    try {
      const userId = req.userContext?.effectiveUserId || req.userId!;
      const { startDate, endDate } = req.query;
      
      const start = startDate ? new Date(startDate as string) : new Date(new Date().getFullYear(), 0, 1);
      const end = endDate ? new Date(endDate as string) : new Date();
      
      const [jobs, invoices, quotes] = await Promise.all([
        storage.getJobs(userId),
        storage.getInvoices(userId),
        storage.getQuotes(userId),
      ]);
      
      // Filter by date range
      const filteredJobs = jobs.filter(j => {
        const date = j.createdAt ? new Date(j.createdAt) : null;
        return date && date >= start && date <= end;
      });
      
      const filteredInvoices = invoices.filter(i => {
        const date = i.createdAt ? new Date(i.createdAt) : null;
        return date && date >= start && date <= end;
      });
      
      const filteredQuotes = quotes.filter(q => {
        const date = q.createdAt ? new Date(q.createdAt) : null;
        return date && date >= start && date <= end;
      });
      
      // Calculate metrics
      const totalRevenue = filteredInvoices
        .filter(i => i.status === 'paid')
        .reduce((sum, i) => sum + Number(i.total || 0), 0);
      
      const pendingRevenue = filteredInvoices
        .filter(i => i.status === 'unpaid' || i.status === 'sent')
        .reduce((sum, i) => sum + Number(i.total || 0), 0);
      
      const overdueRevenue = filteredInvoices
        .filter(i => {
          if (i.status === 'paid') return false;
          return i.dueDate && new Date(i.dueDate) < new Date();
        })
        .reduce((sum, i) => sum + Number(i.total || 0), 0);
      
      const quoteConversionRate = filteredQuotes.length > 0
        ? (filteredQuotes.filter(q => q.status === 'accepted').length / filteredQuotes.length) * 100
        : 0;
      
      const jobsCompleted = filteredJobs.filter(j => j.status === 'done').length;
      const jobsInProgress = filteredJobs.filter(j => j.status === 'in_progress').length;
      
      // GST calculations
      const gstCollected = totalRevenue / 11; // GST is 1/11 of total for 10% GST
      
      res.json({
        period: { start, end },
        revenue: {
          total: totalRevenue,
          pending: pendingRevenue,
          overdue: overdueRevenue,
          gstCollected,
        },
        jobs: {
          total: filteredJobs.length,
          completed: jobsCompleted,
          inProgress: jobsInProgress,
        },
        quotes: {
          total: filteredQuotes.length,
          accepted: filteredQuotes.filter(q => q.status === 'accepted').length,
          pending: filteredQuotes.filter(q => q.status === 'pending').length,
          conversionRate: quoteConversionRate,
        },
        invoices: {
          total: filteredInvoices.length,
          paid: filteredInvoices.filter(i => i.status === 'paid').length,
          unpaid: filteredInvoices.filter(i => i.status === 'unpaid').length,
          overdue: filteredInvoices.filter(i => {
            if (i.status === 'paid') return false;
            return i.dueDate && new Date(i.dueDate) < new Date();
          }).length,
        },
      });
    } catch (error: any) {
      console.error('Error getting report summary:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Get monthly revenue breakdown
  app.get("/api/reports/revenue", requireAuth, requirePaidTier(), createPermissionMiddleware(PERMISSIONS.READ_REPORTS), async (req: any, res) => {
    try {
      const userId = req.userContext?.effectiveUserId || req.userId!;
      const { year } = req.query;
      
      const targetYear = year ? parseInt(year as string) : new Date().getFullYear();
      
      const invoices = await storage.getInvoices(userId);
      
      // Group by month
      const monthlyRevenue: { [month: number]: { total: number; gst: number; paid: number } } = {};
      
      for (let m = 0; m < 12; m++) {
        monthlyRevenue[m] = { total: 0, gst: 0, paid: 0 };
      }
      
      invoices.forEach(invoice => {
        if (invoice.status !== 'paid') return;
        
        // Use paidAt if available, otherwise fall back to createdAt (consistent with summary)
        const paymentDate = invoice.paidAt ? new Date(invoice.paidAt) : 
                           invoice.createdAt ? new Date(invoice.createdAt) : null;
        
        if (paymentDate && paymentDate.getFullYear() === targetYear) {
          const month = paymentDate.getMonth();
          const amount = Number(invoice.total || 0);
          monthlyRevenue[month].total += amount;
          monthlyRevenue[month].gst += amount / 11;
          monthlyRevenue[month].paid++;
        }
      });
      
      const months = [
        'Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun',
        'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'
      ];
      
      res.json({
        year: targetYear,
        months: months.map((name, index) => ({
          month: name,
          revenue: monthlyRevenue[index].total,
          gst: monthlyRevenue[index].gst,
          invoicesPaid: monthlyRevenue[index].paid,
        })),
        yearTotal: Object.values(monthlyRevenue).reduce((sum, m) => sum + m.total, 0),
        yearGst: Object.values(monthlyRevenue).reduce((sum, m) => sum + m.gst, 0),
      });
    } catch (error: any) {
      console.error('Error getting revenue report:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
