  // ============================================
  // ADMIN DASHBOARD ROUTES (Super Admin Only)
  // ============================================
  
  // Admin middleware - requires isPlatformAdmin flag to be true
  const requireAdmin = async (req: any, res: any, next: any) => {
    try {
      const userId = req.userId;
      if (!userId) {
        return res.status(401).json({ error: 'Not authenticated' });
      }
      
      const user = await storage.getUser(userId);
      // Only isPlatformAdmin flag grants admin access - no email fallbacks
      const isAdmin = user?.isPlatformAdmin === true || (user as any)?.is_platform_admin === true;
      if (!user || !isAdmin) {
        return res.status(403).json({ error: 'Access denied. Admin only.' });
      }
      
      next();
    } catch (error) {
      console.error('Admin auth error:', error);
      res.status(500).json({ error: 'Authentication error' });
    }
  };
  
  // Get admin stats - KPIs, user growth, feature usage
  app.get("/api/admin/stats", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      // Get all users
      const allUsers = await db.select().from(users);
      
      const now = new Date();
      const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
      
      // Total users
      const totalUsers = allUsers.length;
      
      // Active users (updated in last 7 days)
      const activeUsers = allUsers.filter(u => {
        const updatedAt = u.updatedAt ? new Date(u.updatedAt) : null;
        return updatedAt && updatedAt >= sevenDaysAgo;
      }).length;
      
      // Onboarding completion rate (users with business settings)
      const allBusinessSettings = await db.select().from(businessSettings);
      const usersWithOnboarding = allBusinessSettings.length;
      const onboardingCompletionRate = totalUsers > 0 
        ? Math.round((usersWithOnboarding / totalUsers) * 100) 
        : 0;
      
      // User growth data - signups per month for last 12 months
      const growthData: { month: string; signups: number }[] = [];
      for (let i = 11; i >= 0; i--) {
        const monthStart = new Date(now.getFullYear(), now.getMonth() - i, 1);
        const monthEnd = new Date(now.getFullYear(), now.getMonth() - i + 1, 0, 23, 59, 59);
        const monthLabel = monthStart.toLocaleDateString('en-AU', { month: 'short', year: '2-digit' });
        
        const signups = allUsers.filter(u => {
          const createdAt = u.createdAt ? new Date(u.createdAt) : null;
          return createdAt && createdAt >= monthStart && createdAt <= monthEnd;
        }).length;
        
        growthData.push({ month: monthLabel, signups });
      }
      
      // Feature usage stats across all users
      const allJobs = await db.select().from(jobs);
      const allInvoices = await db.select().from(invoices);
      const allQuotes = await db.select().from(quotes);
      const allClients = await db.select().from(clients);
      
      const featureUsage = {
        totalJobs: allJobs.length,
        totalInvoices: allInvoices.length,
        totalQuotes: allQuotes.length,
        totalClients: allClients.length,
        completedJobs: allJobs.filter(j => j.status === 'done').length,
        paidInvoices: allInvoices.filter(i => i.status === 'paid').length,
        acceptedQuotes: allQuotes.filter(q => q.status === 'accepted').length,
      };
      
      // Subscription tier breakdown
      const tierBreakdown = {
        free: allUsers.filter(u => u.subscriptionTier === 'free' || !u.subscriptionTier).length,
        pro: allUsers.filter(u => u.subscriptionTier === 'pro').length,
        trial: allUsers.filter(u => u.subscriptionTier === 'trial').length,
      };
      
      res.json({
        kpis: {
          totalUsers,
          activeUsers,
          onboardingCompletionRate,
        },
        growthData,
        featureUsage,
        tierBreakdown,
      });
    } catch (error: any) {
      console.error('Error getting admin stats:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Week-1 (Day-7) retention by weekly signup cohort. Cohort = paying business
  // owners only (users that own a business / have a business_settings row);
  // workers & subcontractors are naturally excluded. "Retained" = the owner had
  // a tracked active day within 7 days AFTER their signup day.
  app.get("/api/admin/retention", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      const BUSINESS_TZ = 'Australia/Sydney';

      // Business owners = users with a business_settings row.
      const ownerRows = await db
        .selectDistinct({ id: users.id, createdAt: users.createdAt })
        .from(users)
        .innerJoin(businessSettings, eq(businessSettings.userId, users.id));

      const ownerIds = ownerRows.map((o) => o.id);
      let activityRows: { userId: string; activityDate: string | null }[] = [];
      if (ownerIds.length > 0) {
        activityRows = await db
          .select({ userId: userActivity.userId, activityDate: userActivity.activityDate })
          .from(userActivity)
          .where(inArray(userActivity.userId, ownerIds));
      }

      // userId -> set of active YYYY-MM-DD days; track earliest day overall.
      const activityByUser = new Map<string, Set<string>>();
      let trackingStart: string | null = null;
      for (const r of activityRows) {
        if (!r.activityDate) continue;
        const d = String(r.activityDate).slice(0, 10);
        if (!activityByUser.has(r.userId)) activityByUser.set(r.userId, new Set());
        activityByUser.get(r.userId)!.add(d);
        if (!trackingStart || d < trackingStart) trackingStart = d;
      }

      // Date helpers on YYYY-MM-DD strings (lexical order == chronological).
      const toLocalDate = (dt: Date): string =>
        new Intl.DateTimeFormat('en-CA', { timeZone: BUSINESS_TZ, year: 'numeric', month: '2-digit', day: '2-digit' }).format(dt);
      const addDays = (ymd: string, days: number): string => {
        const [y, m, d] = ymd.split('-').map(Number);
        const dt = new Date(Date.UTC(y, m - 1, d));
        dt.setUTCDate(dt.getUTCDate() + days);
        return dt.toISOString().slice(0, 10);
      };
      const weekStart = (ymd: string): string => {
        const [y, m, d] = ymd.split('-').map(Number);
        const dt = new Date(Date.UTC(y, m - 1, d));
        const dow = dt.getUTCDay(); // 0 Sun .. 6 Sat
        const back = dow === 0 ? 6 : dow - 1; // Monday-start week
        dt.setUTCDate(dt.getUTCDate() - back);
        return dt.toISOString().slice(0, 10);
      };

      const todayLocal = toLocalDate(new Date());

      type Cohort = { weekStart: string; signups: number; retained: number };
      const cohortMap = new Map<string, Cohort>();
      for (const o of ownerRows) {
        if (!o.createdAt) continue;
        const signupDay = toLocalDate(new Date(o.createdAt as any));
        const ws = weekStart(signupDay);
        if (!cohortMap.has(ws)) cohortMap.set(ws, { weekStart: ws, signups: 0, retained: 0 });
        const c = cohortMap.get(ws)!;
        c.signups += 1;
        // Came back within 7 days = any active day after signup, within 7 days.
        const windowEnd = addDays(signupDay, 7);
        const days = activityByUser.get(o.id);
        const returned = days
          ? Array.from(days).some((d) => d > signupDay && d <= windowEnd)
          : false;
        if (returned) c.retained += 1;
      }

      // Last 12 weeks, oldest -> newest (continuous; 0-signup weeks included).
      const weeks = 12;
      const thisWeekStart = weekStart(todayLocal);
      const cohorts = [] as Array<{
        weekStart: string; signups: number; retained: number; retentionPct: number | null; windowComplete: boolean;
      }>;
      for (let i = weeks - 1; i >= 0; i--) {
        const ws = addDays(thisWeekStart, -7 * i);
        const c = cohortMap.get(ws) || { weekStart: ws, signups: 0, retained: 0 };
        // 7-day window is complete once 7 days passed since the END of the week.
        const windowComplete = addDays(ws, 14) <= todayLocal;
        cohorts.push({
          weekStart: ws,
          signups: c.signups,
          retained: c.retained,
          retentionPct: c.signups > 0 ? Math.round((c.retained / c.signups) * 100) : null,
          windowComplete,
        });
      }

      // Headline = retention across the last 8 complete cohorts that had signups.
      let headlineRetained = 0;
      let headlineSignups = 0;
      let headlineCohorts = 0;
      const completeWithSignups = cohorts.filter((c) => c.windowComplete && c.signups > 0);
      for (const c of completeWithSignups.slice(-8)) {
        headlineRetained += c.retained;
        headlineSignups += c.signups;
        headlineCohorts += 1;
      }
      const headlineRetentionPct = headlineSignups > 0 ? Math.round((headlineRetained / headlineSignups) * 100) : null;

      res.json({
        cohorts,
        headline: {
          retentionPct: headlineRetentionPct,
          cohorts: headlineCohorts,
          signups: headlineSignups,
          retained: headlineRetained,
        },
        trackingStartedAt: trackingStart,
        generatedAt: new Date().toISOString(),
      });
    } catch (error: any) {
      console.error('Error getting admin retention:', error);
      res.status(500).json({ error: error.message });
    }
  });
  
  // Admin communications analytics
  app.get("/api/admin/communications", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      const now = new Date();
      const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
      const sevenDaysAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

      const allSms = await db.select({
        id: smsMessages.id,
        direction: smsMessages.direction,
        status: smsMessages.status,
        isJobRequest: smsMessages.isJobRequest,
        intentType: smsMessages.intentType,
        createdAt: smsMessages.createdAt,
      }).from(smsMessages);

      const allCalls = await db.select({
        id: aiReceptionistCalls.id,
        status: aiReceptionistCalls.status,
        outcome: aiReceptionistCalls.outcome,
        callerIntent: aiReceptionistCalls.callerIntent,
        duration: aiReceptionistCalls.duration,
        cost: aiReceptionistCalls.cost,
        leadId: aiReceptionistCalls.leadId,
        createdAt: aiReceptionistCalls.createdAt,
      }).from(aiReceptionistCalls);

      const allLeads = await db.select({
        id: leads.id,
        source: leads.source,
        status: leads.status,
        estimatedValue: leads.estimatedValue,
        createdAt: leads.createdAt,
      }).from(leads);

      const allConversations = await db.select({
        id: smsConversations.id,
        createdAt: smsConversations.createdAt,
      }).from(smsConversations);

      const sms30d = allSms.filter(s => s.createdAt && new Date(s.createdAt) >= thirtyDaysAgo);
      const sms7d = allSms.filter(s => s.createdAt && new Date(s.createdAt) >= sevenDaysAgo);
      const calls30d = allCalls.filter(c => c.createdAt && new Date(c.createdAt) >= thirtyDaysAgo);
      const calls7d = allCalls.filter(c => c.createdAt && new Date(c.createdAt) >= sevenDaysAgo);
      const leads30d = allLeads.filter(l => l.createdAt && new Date(l.createdAt) >= thirtyDaysAgo);

      const smsDailyData: { date: string; inbound: number; outbound: number }[] = [];
      for (let i = 29; i >= 0; i--) {
        const dayStart = new Date(now.getFullYear(), now.getMonth(), now.getDate() - i);
        const dayEnd = new Date(dayStart.getTime() + 24 * 60 * 60 * 1000);
        const dayLabel = dayStart.toLocaleDateString('en-AU', { day: 'numeric', month: 'short' });
        const daySms = sms30d.filter(s => {
          const d = new Date(s.createdAt!);
          return d >= dayStart && d < dayEnd;
        });
        smsDailyData.push({
          date: dayLabel,
          inbound: daySms.filter(s => s.direction === 'inbound').length,
          outbound: daySms.filter(s => s.direction === 'outbound').length,
        });
      }

      const leadsBySource: Record<string, number> = {};
      allLeads.forEach(l => {
        const src = l.source || 'other';
        leadsBySource[src] = (leadsBySource[src] || 0) + 1;
      });

      const leadsByStatus: Record<string, number> = {};
      allLeads.forEach(l => {
        const st = l.status || 'new';
        leadsByStatus[st] = (leadsByStatus[st] || 0) + 1;
      });

      const callOutcomes: Record<string, number> = {};
      allCalls.forEach(c => {
        const out = c.outcome || 'unknown';
        callOutcomes[out] = (callOutcomes[out] || 0) + 1;
      });

      const totalCallDuration = allCalls.reduce((sum, c) => sum + (c.duration || 0), 0);
      const totalCallCost = allCalls.reduce((sum, c) => sum + (c.cost ? parseFloat(String(c.cost)) : 0), 0);

      res.json({
        sms: {
          total: allSms.length,
          last30d: sms30d.length,
          last7d: sms7d.length,
          inbound: allSms.filter(s => s.direction === 'inbound').length,
          outbound: allSms.filter(s => s.direction === 'outbound').length,
          delivered: allSms.filter(s => s.status === 'delivered' || s.status === 'sent').length,
          failed: allSms.filter(s => s.status === 'failed').length,
          jobRequests: allSms.filter(s => s.isJobRequest).length,
          dailyData: smsDailyData,
        },
        conversations: {
          total: allConversations.length,
        },
        calls: {
          total: allCalls.length,
          last30d: calls30d.length,
          last7d: calls7d.length,
          completed: allCalls.filter(c => c.status === 'completed').length,
          missed: allCalls.filter(c => c.status === 'missed').length,
          transferred: allCalls.filter(c => c.outcome === 'transferred').length,
          leadsCreated: allCalls.filter(c => c.leadId).length,
          avgDuration: allCalls.length > 0 ? Math.round(totalCallDuration / allCalls.length) : 0,
          totalCost: Math.round(totalCallCost * 100) / 100,
          outcomes: callOutcomes,
        },
        leads: {
          total: allLeads.length,
          last30d: leads30d.length,
          bySource: leadsBySource,
          byStatus: leadsByStatus,
          newLeads: allLeads.filter(l => l.status === 'new').length,
          wonLeads: allLeads.filter(l => l.status === 'won').length,
          conversionRate: allLeads.length > 0 
            ? Math.round((allLeads.filter(l => l.status === 'won').length / allLeads.length) * 100) 
            : 0,
          totalEstimatedValue: allLeads.reduce((sum, l) => sum + (l.estimatedValue ? parseFloat(String(l.estimatedValue)) : 0), 0),
        },
      });
    } catch (error: any) {
      console.error('Error getting admin communications stats:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get all users for admin
  app.get("/api/admin/users", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      // Get all users with basic info (exclude sensitive fields)
      const allUsers = await db.select({
        id: users.id,
        email: users.email,
        firstName: users.firstName,
        lastName: users.lastName,
        subscriptionTier: users.subscriptionTier,
        tradeType: users.tradeType,
        createdAt: users.createdAt,
        updatedAt: users.updatedAt,
        isActive: users.isActive,
        emailVerified: users.emailVerified,
        betaUser: users.betaUser,
        betaLifetimeAccess: users.betaLifetimeAccess,
      }).from(users).orderBy(desc(users.createdAt));
      
      // Get business settings to check onboarding completion
      const allBusinessSettings = await db.select({
        userId: businessSettings.userId,
        businessName: businessSettings.businessName,
        accountType: businessSettings.accountType,
      }).from(businessSettings).orderBy(businessSettings.id);
      
      const businessSettingsMap = new Map(allBusinessSettings.map(bs => [bs.userId, bs]));

      // Resolve team-member roles (for users who are members of someone else's business)
      const memberRoleRows = await db.select({
        memberId: teamMembers.memberId,
        roleName: userRoles.name,
      })
        .from(teamMembers)
        .leftJoin(userRoles, eq(teamMembers.roleId, userRoles.id))
        .where(eq(teamMembers.inviteStatus, 'accepted'))
        .orderBy(teamMembers.id);
      const memberRoleMap = new Map<string, string>();
      for (const row of memberRoleRows) {
        if (row.memberId && !memberRoleMap.has(row.memberId)) {
          memberRoleMap.set(row.memberId, row.roleName || 'Team member');
        }
      }

      const allWebsiteAddons = await db.select({
        businessId: websiteAddons.businessId,
        websiteClickToCall: websiteAddons.websiteClickToCall,
        websiteChatWidget: websiteAddons.websiteChatWidget,
        websiteBookingForm: websiteAddons.websiteBookingForm,
      }).from(websiteAddons);
      const websiteAddonMap = new Map(allWebsiteAddons.map(wa => [wa.businessId, wa]));
      
      // Enrich user data
      const enrichedUsers = allUsers.map(user => {
        const wa = websiteAddonMap.get(user.id);
        const ownSettings = businessSettingsMap.get(user.id);
        let role: string;
        if (ownSettings?.accountType === 'subcontractor') {
          role = 'Subcontractor';
        } else if (ownSettings) {
          role = 'Owner';
        } else {
          role = memberRoleMap.get(user.id) || 'Unassigned';
        }
        return {
          ...user,
          name: [user.firstName, user.lastName].filter(Boolean).join(' ') || user.email || 'Unknown',
          role,
          hasCompletedOnboarding: businessSettingsMap.has(user.id),
          businessName: businessSettingsMap.get(user.id)?.businessName || null,
          websiteFeatures: wa ? {
            clickToCall: wa.websiteClickToCall || false,
            chatWidget: wa.websiteChatWidget || false,
            bookingForm: wa.websiteBookingForm || false,
          } : null,
        };
      });
      
      res.json({ users: enrichedUsers });
    } catch (error: any) {
      console.error('Error getting admin users:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Get system health status for admin
  app.get("/api/admin/health", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      const startTime = Date.now();
      
      // Check database connectivity and latency
      let dbStatus = 'healthy';
      let dbLatency = 0;
      try {
        const dbStart = Date.now();
        await db.select().from(users).limit(1);
        dbLatency = Date.now() - dbStart;
        if (dbLatency > 1000) dbStatus = 'degraded';
      } catch (error) {
        dbStatus = 'down';
        dbLatency = -1;
      }
      
      // API latency is just this request's processing time
      const apiLatency = Date.now() - startTime;
      
      let totalUsers = 0;
      let totalJobs = 0;
      if (dbStatus !== 'down') {
        try {
          const [userCount, jobCount] = await Promise.all([
            db.select({ count: sql<number>`count(*)::int` }).from(users),
            db.select({ count: sql<number>`count(*)::int` }).from(jobs),
          ]);
          totalUsers = userCount[0]?.count ?? 0;
          totalJobs = jobCount[0]?.count ?? 0;
        } catch {
          dbStatus = 'degraded';
        }
      }
      
      res.json({
        api: { 
          status: 'healthy', 
          latency: apiLatency,
          avgResponseTime: apiLatency, 
        },
        database: { 
          status: dbStatus, 
          latency: dbLatency,
          connections: 1, // Neon serverless uses connection pooling
        },
        backgroundJobs: { 
          status: 'healthy', 
          pending: 0,
        },
        storage: { 
          status: 'healthy', 
          used: 'N/A',
        },
        metrics: {
          totalUsers,
          totalJobs,
          errorRate: 0,
          activeSessions: 1,
        }
      });
    } catch (error: any) {
      console.error('Error getting admin health:', error);
      res.status(500).json({ error: error.message });
    }
  });


  app.post("/api/client-errors", async (req: any, res) => {
    try {
      const { message, stack, componentStack, url, userAgent } = req.body;
      if (!message) return res.status(400).json({ error: 'Message required' });

      // Drop benign Vite HMR dev-socket noise (wss://localhost:undefined/?token=...).
      // It self-recovers, affects no end user, and was spamming email alerts.
      const msgStr = String(message);
      if (
        (msgStr.includes('localhost:undefined') && msgStr.includes('WebSocket')) ||
        msgStr.includes("Failed to construct 'WebSocket'")
      ) {
        return res.json({ received: true, ignored: true });
      }

      // Drop benign browser noise: "ResizeObserver loop completed with
      // undelivered notifications." (and the older "loop limit exceeded"
      // variant) just means the browser deferred observer delivery one frame.
      // Nothing breaks and no user is affected — it was spamming email alerts.
      if (msgStr.includes('ResizeObserver loop')) {
        return res.json({ received: true, ignored: true });
      }

      // Drop errors thrown inside automation/headless-browser injected scripts
      // (Playwright/Puppeteer bots, uptime monitors, scrapers). These come from
      // scripts the tool injects into the page (UtilityScript.evaluate /
      // addScriptContent / *_evaluation_script), never from our app bundle, and
      // affect no real end user. They were spamming email alerts.
      const stackStr = String(stack || '');
      if (
        stackStr.includes('UtilityScript') ||
        stackStr.includes('addScriptContent') ||
        stackStr.includes('puppeteer_evaluation_script') ||
        stackStr.includes('__playwright')
      ) {
        return res.json({ received: true, ignored: true });
      }

      // Drop cross-origin "Script error." — the browser strips all detail from
      // errors thrown by scripts on a different origin. No stack, no file, no
      // line number is ever available, so these alerts are pure noise.
      if (msgStr.trim() === 'Script error.' || msgStr.trim() === 'Script error') {
        return res.json({ received: true, ignored: true });
      }

      // Drop Android WebView "Java object is gone" / postMessage lifecycle errors.
      // This fires when a user navigates away or backgrounds the app while JS is
      // still executing and tries to call back into Java via postMessage or a
      // JavascriptInterface. The Java-side WebView object gets GC'd before the
      // JS call completes — not a bug in our code, just Android WebView lifecycle.
      // Non-fatal: the app continues normally. Suppressing to avoid alert noise.
      if (
        msgStr.includes('Java object is gone') ||
        msgStr.includes('Error invoking postMessage')
      ) {
        return res.json({ received: true, ignored: true });
      }

      const userId = req.session?.userId || null;
      logger.error('frontend', `Client error: ${String(message).substring(0, 500)}`, {
        userId,
        metadata: {
          stack: String(stack || '').substring(0, 2000),
          componentStack: String(componentStack || '').substring(0, 1000),
          url: String(url || '').substring(0, 500),
          userAgent: String(userAgent || '').substring(0, 300),
        },
        error: new Error(String(message)),
      });

      res.json({ received: true });
    } catch (error) {
      res.status(500).json({ error: 'Failed to log error' });
    }
  });

  app.get("/api/admin/error-logs", requireAuth, requireAdmin, async (req: any, res) => {
    try {
      const limit = Math.min(parseInt(req.query.limit as string) || 50, 200);
      const offset = parseInt(req.query.offset as string) || 0;
      const level = req.query.level as string;
      const category = req.query.category as string;

      const conditions: any[] = [];
      if (level) conditions.push(eq(errorLogs.level, level));
      if (category) conditions.push(eq(errorLogs.category, category));

      const [logs, countResult] = await Promise.all([
        db.select().from(errorLogs)
          .where(conditions.length > 0 ? and(...conditions) : undefined)
          .orderBy(desc(errorLogs.createdAt))
          .limit(limit)
          .offset(offset),
        db.select({ count: sql<number>`count(*)::int` }).from(errorLogs)
          .where(conditions.length > 0 ? and(...conditions) : undefined),
      ]);

      res.setHeader('X-Total-Count', countResult[0]?.count ?? 0);
      res.json(logs);
    } catch (error) {
      logger.error('api', 'Failed to fetch error logs', { error });
      res.status(500).json({ error: 'Failed to fetch error logs' });
    }
  });

