  // Approve or reject time off (owner/manager only)
  app.patch("/api/team/time-off/:id", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const { id } = req.params;
      const { status, approverComment } = req.body;
      
      if (!status || !['approved', 'rejected'].includes(status)) {
        return res.status(400).json({ error: 'Status must be approved or rejected' });
      }
      
      // Verify the time off request belongs to this business
      const [existingTimeOff] = await db.select().from(teamMemberTimeOff)
        .where(eq(teamMemberTimeOff.id, id));
      
      if (!existingTimeOff) {
        return res.status(404).json({ error: 'Time off request not found' });
      }
      
      const isOwned = await verifyTeamMemberOwnership(userId, existingTimeOff.teamMemberId);
      if (!isOwned) {
        return res.status(403).json({ error: 'Time off request does not belong to your business' });
      }
      
      // Atomic conditional update: only transition if the current persisted status differs
      // from the requested status. This prevents concurrent PATCH requests from both
      // observing the old status and both running side effects (duplicate notifications,
      // double-counted leave balance). If the row is already in the target status the
      // update matches 0 rows and we skip all side effects.
      const updated = await db.update(teamMemberTimeOff)
        .set({
          status,
          approvedBy: userId,
          approvedAt: new Date(),
          approverComment: approverComment || null,
          updatedAt: new Date(),
        })
        // Only allow transition from 'pending'. Approved/rejected requests are terminal:
        // allowing approved→rejected would leave an unreverted balance increment,
        // and rejected→approved would double-count leave days.
        .where(and(eq(teamMemberTimeOff.id, id), eq(teamMemberTimeOff.status, 'pending')))
        .returning();

      const [timeOff] = updated;
      if (!timeOff) {
        // Already in requested status — return the current row without side effects
        const [current] = await db.select().from(teamMemberTimeOff).where(eq(teamMemberTimeOff.id, id));
        return res.json(current);
      }

      // Send push notification to the worker whose leave was actioned (only on actual transition)
      try {
        const [member] = await db.select().from(teamMembers)
          .where(eq(teamMembers.id, existingTimeOff.teamMemberId));
        if (member?.memberId) {
          const { sendPushNotification } = await import('./pushNotifications');
          const statusLabel = status === 'approved' ? 'approved ✅' : 'declined ❌';
          const leaveTypeLabel = existingTimeOff.reason?.replace(/_/g, ' ') || 'leave';
          await sendPushNotification({
            userId: member.memberId,
            type: 'leave_decision',
            title: `Leave ${status === 'approved' ? 'Approved' : 'Declined'}`,
            body: `Your ${leaveTypeLabel} request has been ${statusLabel}${approverComment ? `: ${approverComment}` : '.'}`,
            data: { timeOffId: id, status },
          });
        }
      } catch (notifErr) {
        console.error('Failed to send leave decision notification:', notifErr);
      }

      // When approving, increment taken days in team_member_leave_balances.
      // Gated on actual transition (timeOff !== undefined above) so concurrent
      // approvals cannot double-count. existingTimeOff.status is the pre-update value.
      if (status === 'approved' && existingTimeOff.startDate && existingTimeOff.endDate) {
        try {
          const startMs = new Date(existingTimeOff.startDate).getTime();
          const endMs = new Date(existingTimeOff.endDate).getTime();
          const daysTaken = Math.max(1, Math.ceil((endMs - startMs) / (1000 * 60 * 60 * 24)) + 1);
          const leaveYear = new Date(existingTimeOff.startDate).getFullYear();
          const leaveType = existingTimeOff.reason || 'other';

          // Resolve businessOwnerId for this team member
          const [memberRow] = await db.select().from(teamMembers)
            .where(eq(teamMembers.id, existingTimeOff.teamMemberId)).limit(1);
          const bizOwnerId = memberRow?.businessOwnerId || userId;

          const [existing] = await db.select().from(teamMemberLeaveBalances)
            .where(and(
              eq(teamMemberLeaveBalances.teamMemberId, existingTimeOff.teamMemberId),
              eq(teamMemberLeaveBalances.leaveType, leaveType),
              eq(teamMemberLeaveBalances.year, leaveYear),
            )).limit(1);

          if (existing) {
            const newTaken = parseFloat(existing.taken || '0') + daysTaken;
            await db.update(teamMemberLeaveBalances)
              .set({ taken: newTaken.toString(), updatedAt: new Date() })
              .where(eq(teamMemberLeaveBalances.id, existing.id));
          } else {
            await db.insert(teamMemberLeaveBalances).values({
              teamMemberId: existingTimeOff.teamMemberId,
              businessOwnerId: bizOwnerId,
              leaveType,
              year: leaveYear,
              accrued: '0',
              taken: daysTaken.toString(),
            });
          }
        } catch (balErr) {
          console.error('Failed to update leave balance on approval:', balErr);
        }
      }

      res.json(timeOff);
    } catch (error: any) {
      console.error('Error updating time off:', error);
      res.status(500).json({ error: error.message });
    }
  });

