  // ============================================

  // List invites for a job (owner only)

  // Create a new job invite (owner only)

  // Revoke a job invite (owner only)

  // Get invite details by code (public - for invite acceptance page)
  app.get("/api/invite/:code", async (req: any, res) => {
    try {
      const { code } = req.params;

      const invite = await storage.getJobInviteByCode(code);
      if (!invite) {
        return res.status(404).json({ error: 'Invite not found' });
      }

      // Check if invite is expired
      if (invite.expiresAt && new Date(invite.expiresAt) < new Date()) {
        return res.status(410).json({ error: 'Invite has expired', status: 'expired' });
      }

      // Check if invite is already used or revoked
      if (invite.status !== 'pending') {
        return res.status(410).json({ error: `Invite is ${invite.status}`, status: invite.status });
      }

      // Get job and business info for display
      const job = await storage.getJobPublic(invite.jobId);
      if (!job) {
        return res.status(404).json({ error: 'Job not found' });
      }

      const businessSettings = await storage.getBusinessSettings(invite.userId);

      res.json({
        invite: {
          id: invite.id,
          role: invite.role,
          permissions: invite.permissions,
          status: invite.status,
          createdAt: invite.createdAt,
        },
        job: {
          title: job.title,
          address: job.address,
        },
        business: {
          companyName: businessSettings?.businessName || 'Business',
        },
      });
    } catch (error: any) {
      console.error('Error getting invite details:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Accept a job invite (requires auth)
  app.post("/api/invite/:code/accept", requireAuth, async (req: any, res) => {
    try {
      const acceptingUserId = req.userId!;
      const { code } = req.params;

      const invite = await storage.getJobInviteByCode(code);
      if (!invite) {
        return res.status(404).json({ error: 'Invite not found' });
      }

      // Check if invite is expired
      if (invite.expiresAt && new Date(invite.expiresAt) < new Date()) {
        return res.status(410).json({ error: 'Invite has expired' });
      }

      // Check if invite is already used or revoked
      if (invite.status !== 'pending') {
        return res.status(410).json({ error: `Invite is ${invite.status}` });
      }

      // Cannot accept own invite
      if (invite.userId === acceptingUserId) {
        return res.status(400).json({ error: 'Cannot accept your own invite' });
      }

      // Accept the invite
      const acceptedInvite = await storage.acceptJobInvite(code, acceptingUserId);
      if (!acceptedInvite) {
        return res.status(500).json({ error: 'Failed to accept invite' });
      }

      res.json({
        success: true,
        jobId: invite.jobId,
        role: invite.role,
        permissions: invite.permissions,
      });
    } catch (error: any) {
      console.error('Error accepting job invite:', error);
      res.status(500).json({ error: error.message });
    }
  });

  // Address search - Google Places API (when key available) with Nominatim fallback
  app.get("/api/address-search", requireAuth, async (req, res) => {
    try {
      const query = req.query.q;
      if (typeof query !== 'string' || query.length < 3) {
        return res.json([]);
      }

      const googleApiKey = process.env.GOOGLE_MAPS_API_KEY;
      
      if (googleApiKey) {
        const encoded = encodeURIComponent(query);
        const response = await fetch(
          `https://maps.googleapis.com/maps/api/place/autocomplete/json?input=${encoded}&components=country:au&types=address&key=${googleApiKey}`
        );
        
        if (response.ok) {
          const data = await response.json();
          if (data.status === 'OK' && data.predictions) {
            const results = data.predictions.map((p: any) => ({
              description: p.description,
              place_id: p.place_id,
              provider: 'google',
            }));
            return res.json(results);
          } else if (data.status === 'ZERO_RESULTS') {
            return res.json([]);
          }
        }
      }
      
      // Fallback to Nominatim (free, no key needed)
      const encoded = encodeURIComponent(query);
      const response = await fetch(
        `https://nominatim.openstreetmap.org/search?format=json&q=${encoded}&countrycodes=au&limit=5&addressdetails=1`,
        {
          headers: {
            "User-Agent": "JobRunner/1.0 (jobrunner.com.au)",
          },
        }
      );
      
      if (!response.ok) {
        return res.status(response.status).json({ error: "Address search failed" });
      }
      
      const data = await response.json();
      const userNumberMatch = query.trim().match(/^(\d+[a-zA-Z]?(?:\/\d+[a-zA-Z]?)?)\s+/);
      const userStreetNumber = userNumberMatch ? userNumberMatch[1] : null;
      
      const results = data.map((item: any) => {
        const addr = item.address || {};
        const parts: string[] = [];
        const houseNumber = addr.house_number || userStreetNumber;
        if (houseNumber && addr.road) parts.push(`${houseNumber} ${addr.road}`);
        else if (addr.road) parts.push(addr.road);
        const locality = addr.suburb || addr.city || addr.town || addr.village;
        if (locality) parts.push(locality);
        const stateMap: Record<string, string> = {
          'New South Wales': 'NSW', 'Victoria': 'VIC', 'Queensland': 'QLD',
          'South Australia': 'SA', 'Western Australia': 'WA', 'Tasmania': 'TAS',
          'Northern Territory': 'NT', 'Australian Capital Territory': 'ACT',
        };
        const stateAbbr = addr.state ? (stateMap[addr.state] || addr.state) : '';
        if (stateAbbr && addr.postcode) parts.push(`${stateAbbr} ${addr.postcode}`);
        else if (stateAbbr) parts.push(stateAbbr);
        return {
          description: parts.length > 0 ? parts.join(', ') : item.display_name,
          lat: item.lat,
          lng: item.lon,
          provider: 'nominatim',
        };
      });
      res.json(results);
    } catch (error) {
      console.error("Address search error:", error);
      res.status(500).json({ error: "Address search failed" });
    }
  });

