      if (updates.expiryDate === '') {
        updates.expiryDate = null;
      }
      
      const doc = await storage.updateComplianceDocument(req.params.id, businessOwnerId, updates);
      if (!doc) return res.status(404).json({ error: "Document not found" });
      
