  app.get("/api/swms", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const docs = await db.select().from(swmsDocuments).where(eq(swmsDocuments.userId, userId)).orderBy(desc(swmsDocuments.createdAt));
      const docsWithJob = await Promise.all(docs.map(async (doc) => {
        let jobTitle = null;
        if (doc.jobId) {
          try {
            const job = await storage.getJob(doc.jobId, userId);
            jobTitle = job?.title || null;
          } catch {}
        }
        const hazardCount = await db.select({ count: sql<number>`count(*)` }).from(swmsHazards).where(eq(swmsHazards.swmsId, doc.id));
        const sigCount = await db.select({ count: sql<number>`count(*)` }).from(swmsSignatures).where(eq(swmsSignatures.swmsId, doc.id));
        return { ...doc, jobTitle, hazardCount: Number(hazardCount[0]?.count || 0), signatureCount: Number(sigCount[0]?.count || 0) };
      }));
      res.json(docsWithJob);
    } catch (error: any) {
      console.error("Error fetching SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/swms", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const { title, description, jobId, siteAddress, workActivityDescription, ppeRequirements, emergencyContact, firstAidLocation, status, hazards, attachmentUrl, attachmentType } = req.body;
      if (!title) return res.status(400).json({ error: 'Title is required' });

      let resolvedAddress = siteAddress;
      if (jobId && !siteAddress) {
        try {
          const job = await storage.getJob(jobId, userId);
          if (job?.address) resolvedAddress = job.address;
        } catch {}
      }

      const [doc] = await db.insert(swmsDocuments).values({
        userId,
        jobId: jobId || null,
        title,
        description: description || null,
        siteAddress: resolvedAddress || null,
        workActivityDescription: workActivityDescription || null,
        ppeRequirements: ppeRequirements || [],
        emergencyContact: emergencyContact || null,
        firstAidLocation: firstAidLocation || null,
        status: status || 'draft',
        attachmentUrl: attachmentUrl || null,
        attachmentType: attachmentType || null,
      }).returning();

      if (hazards && Array.isArray(hazards) && hazards.length > 0) {
        for (let i = 0; i < hazards.length; i++) {
          const h = hazards[i];
          await db.insert(swmsHazards).values({
            swmsId: doc.id,
            stepNumber: i + 1,
            activityTask: h.activityTask || 'Activity',
            hazard: h.hazard || 'Hazard',
            likelihood: h.likelihood || 'possible',
            consequence: h.consequence || 'moderate',
            riskBefore: h.riskBefore || 'medium',
            controlMeasures: h.controlMeasures || null,
            riskAfter: h.riskAfter || 'low',
            sortOrder: i,
          });
        }
      }

      res.json(doc);
    } catch (error: any) {
      console.error("Error creating SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.get("/api/swms/:id", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, req.params.id), eq(swmsDocuments.userId, userId)));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });
      const hazards = await db.select().from(swmsHazards).where(eq(swmsHazards.swmsId, doc.id)).orderBy(asc(swmsHazards.sortOrder));
      const signatures = await db.select().from(swmsSignatures).where(eq(swmsSignatures.swmsId, doc.id)).orderBy(asc(swmsSignatures.signedAt));
      let jobTitle = null;
      if (doc.jobId) {
        try {
          const job = await storage.getJob(doc.jobId, userId);
          jobTitle = job?.title || null;
        } catch {}
      }
      res.json({ ...doc, jobTitle, hazards, signatures });
    } catch (error: any) {
      console.error("Error fetching SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.patch("/api/swms/:id", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [existing] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, req.params.id), eq(swmsDocuments.userId, userId)));
      if (!existing) return res.status(404).json({ error: 'SWMS not found' });

      const updates: any = { updatedAt: new Date() };
      const fields = ['title', 'description', 'jobId', 'siteAddress', 'workActivityDescription', 'ppeRequirements', 'emergencyContact', 'firstAidLocation', 'status'];
      fields.forEach(f => { if (req.body[f] !== undefined) updates[f] = req.body[f]; });

      const [updated] = await db.update(swmsDocuments).set(updates).where(eq(swmsDocuments.id, req.params.id)).returning();
      res.json(updated);
    } catch (error: any) {
      console.error("Error updating SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.delete("/api/swms/:id", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [existing] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, req.params.id), eq(swmsDocuments.userId, userId)));
      if (!existing) return res.status(404).json({ error: 'SWMS not found' });
      await db.delete(swmsDocuments).where(eq(swmsDocuments.id, req.params.id));
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error deleting SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });


  app.post("/api/swms/:id/hazards", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, req.params.id), eq(swmsDocuments.userId, userId)));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });

      const { activityTask, hazard, likelihood, consequence, riskBefore, controlMeasures, riskAfter } = req.body;
      if (!activityTask || !hazard) return res.status(400).json({ error: 'Activity and hazard are required' });

      const existing = await db.select({ count: sql<number>`count(*)` }).from(swmsHazards).where(eq(swmsHazards.swmsId, doc.id));
      const stepNum = Number(existing[0]?.count || 0) + 1;

      const [h] = await db.insert(swmsHazards).values({
        swmsId: doc.id,
        stepNumber: stepNum,
        activityTask,
        hazard,
        likelihood: likelihood || 'possible',
        consequence: consequence || 'moderate',
        riskBefore: riskBefore || 'medium',
        controlMeasures: controlMeasures || null,
        riskAfter: riskAfter || 'low',
        sortOrder: stepNum - 1,
      }).returning();
      res.json(h);
    } catch (error: any) {
      console.error("Error adding hazard:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.patch("/api/swms/hazards/:hazardId", requireAuth, async (req: any, res) => {
    try {
      const [hazard] = await db.select().from(swmsHazards).where(eq(swmsHazards.id, req.params.hazardId));
      if (!hazard) return res.status(404).json({ error: 'Hazard not found' });

      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, hazard.swmsId), eq(swmsDocuments.userId, userId)));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });

      const updates: any = {};
      const fields = ['activityTask', 'hazard', 'likelihood', 'consequence', 'riskBefore', 'controlMeasures', 'riskAfter', 'sortOrder'];
      fields.forEach(f => { if (req.body[f] !== undefined) updates[f] = req.body[f]; });

      const [updated] = await db.update(swmsHazards).set(updates).where(eq(swmsHazards.id, req.params.hazardId)).returning();
      res.json(updated);
    } catch (error: any) {
      console.error("Error updating hazard:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.delete("/api/swms/hazards/:hazardId", requireAuth, async (req: any, res) => {
    try {
      const [hazard] = await db.select().from(swmsHazards).where(eq(swmsHazards.id, req.params.hazardId));
      if (!hazard) return res.status(404).json({ error: 'Hazard not found' });

      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, hazard.swmsId), eq(swmsDocuments.userId, userId)));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });

      await db.delete(swmsHazards).where(eq(swmsHazards.id, req.params.hazardId));
      res.json({ success: true });
    } catch (error: any) {
      console.error("Error deleting hazard:", error);
      res.status(500).json({ error: error.message });
    }
  });

  app.post("/api/swms/:id/sign", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(eq(swmsDocuments.id, req.params.id));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });

      if (doc.userId !== userId) {
        const teamCheck = await db.execute(sql`SELECT 1 FROM team_members WHERE user_id = ${req.userId} AND business_owner_id = ${doc.userId} AND status = 'active' LIMIT 1`);
        if (!teamCheck.rows || teamCheck.rows.length === 0) return res.status(403).json({ error: 'Not authorized to sign this SWMS' });
      }

      const { workerName, signatureData, latitude, longitude, address, workerUserId, idempotencyKey } = req.body;
      if (!workerName || !signatureData) return res.status(400).json({ error: 'Worker name and signature are required' });

      const idemKey: string | undefined = idempotencyKey || req.headers['idempotency-key'];
      if (idemKey) {
        const cached = await getIdempotencyRecord(`swmssign:${req.params.id}:${idemKey}`);
        if (cached) return res.json({ ...cached, idempotentReplay: true });
      }

      const [sig] = await db.insert(swmsSignatures).values({
        swmsId: req.params.id,
        workerName,
        workerUserId: workerUserId || req.userId || null,
        signatureData,
        signedAt: new Date(),
        latitude: latitude || null,
        longitude: longitude || null,
        address: address || null,
      }).returning();

      if (idemKey) {
        await setIdempotencyRecord(`swmssign:${req.params.id}:${idemKey}`, sig);
      }

      if (doc.status === 'draft') {
        await db.update(swmsDocuments)
          .set({ status: 'active' })
          .where(eq(swmsDocuments.id, req.params.id));
      }

      res.json(sig);
    } catch (error: any) {
      console.error("Error signing SWMS:", error);
      res.status(500).json({ error: error.message });
    }
  });

  const PPE_LABELS: Record<string, string> = {
    hard_hat: 'Hard Hat',
    safety_glasses: 'Safety Glasses',
    hi_vis: 'Hi-Vis Vest',
    steel_caps: 'Steel Cap Boots',
    hearing_protection: 'Hearing Protection',
    dust_mask: 'Dust Mask / Respirator',
    gloves: 'Gloves',
    fall_harness: 'Fall Arrest Harness',
    face_shield: 'Face Shield',
    sun_protection: 'Sun Protection',
  };

  const RISK_MATRIX: Record<string, Record<string, string>> = {
    rare: { insignificant: 'low', minor: 'low', moderate: 'low', major: 'medium', catastrophic: 'medium' },
    unlikely: { insignificant: 'low', minor: 'low', moderate: 'medium', major: 'medium', catastrophic: 'high' },
    possible: { insignificant: 'low', minor: 'medium', moderate: 'medium', major: 'high', catastrophic: 'extreme' },
    likely: { insignificant: 'low', minor: 'medium', moderate: 'high', major: 'high', catastrophic: 'extreme' },
    almost_certain: { insignificant: 'medium', minor: 'high', moderate: 'high', major: 'extreme', catastrophic: 'extreme' },
  };

  app.get("/api/swms/:id/pdf", requireAuth, async (req: any, res) => {
    try {
      const userContext = await getUserContext(req.userId);
      const userId = userContext.effectiveUserId;
      const [doc] = await db.select().from(swmsDocuments).where(and(eq(swmsDocuments.id, req.params.id), eq(swmsDocuments.userId, userId)));
      if (!doc) return res.status(404).json({ error: 'SWMS not found' });

      const hazards = await db.select().from(swmsHazards).where(eq(swmsHazards.swmsId, doc.id)).orderBy(asc(swmsHazards.sortOrder));
      const signatures = await db.select().from(swmsSignatures).where(eq(swmsSignatures.swmsId, doc.id)).orderBy(asc(swmsSignatures.signedAt));

      const businessRaw = await storage.getBusinessSettingsByUserId(userId);
      const businessName = businessRaw?.businessName || 'Business';
      const abn = businessRaw?.abn || '';

      const ppeList = (doc.ppeRequirements as string[] || []).map((p: string) => PPE_LABELS[p] || p).join(', ');

      const riskColor = (r: string) => {
        if (r === 'low') return 'background:#dcfce7;color:#166534';
        if (r === 'medium') return 'background:#fef3c7;color:#92400e';
        if (r === 'high') return 'background:#fee2e2;color:#991b1b';
        return 'background:#7f1d1d;color:#fff';
      };

      const { getSwmsTemplateSettings, resolveLogoUrl } = await import('./pdfService');
      const templateSettings = getSwmsTemplateSettings(businessRaw as any);
      const ac = templateSettings.accentColor;
      const tmpl = templateSettings.template;
      const logoUrl = await resolveLogoUrl(businessRaw?.logoUrl) || '';

      const tableHeaderBg = tmpl.tableStyle === 'minimal' ? 'transparent' : ac;
      const tableHeaderColor = tmpl.tableStyle === 'minimal' ? '#1a1a1a' : 'white';
      const tableHeaderBorder = tmpl.tableStyle === 'minimal' ? `border-bottom: 2px solid ${ac};` : `border: 1px solid ${ac};`;
      const getTableRowCss = () => {
        if (tmpl.tableStyle === 'striped') return 'table tbody tr:nth-child(odd) { background: #f9fafb; } table tbody tr:nth-child(even) { background: transparent; } table td { border-bottom: none; }';
        if (tmpl.tableStyle === 'minimal') return 'table td { border-bottom: 1px solid #e5e7eb; }';
        return 'table td { border-bottom: 1px solid #eee; }';
      };

      const headerBorder = tmpl.showHeaderDivider
        ? `border-bottom: ${tmpl.headerBorderWidth} solid ${ac};`
        : 'border-bottom: none;';

      const getNoteStyle = () => {
        if (tmpl.noteStyle === 'highlighted') return `background: linear-gradient(135deg, ${ac}10, ${ac}05); border: 1px solid ${ac}30; border-radius: 6px; padding: 8px 12px;`;
        if (tmpl.noteStyle === 'simple') return `background: transparent; border-top: 1px solid #e5e7eb; padding: 8px 0;`;
        return `background: #fafafa; border-left: 4px solid ${ac}; border-radius: 0 6px 6px 0; padding: 8px 12px;`;
      };

      const html = `<!DOCTYPE html>
<html><head><meta charset="UTF-8"><title>SWMS - ${doc.title}</title>
<link rel="preconnect" href="https://fonts.googleapis.com">
<link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
<link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body { font-family: ${tmpl.fontFamily}; font-size: ${tmpl.baseFontSize}; font-weight: ${tmpl.bodyWeight}; line-height: 1.5; color: #1a1a1a; background: #fff; }
  .document { max-width: 800px; margin: 0 auto; padding: 15px 20px; }
  .header { display: flex; justify-content: space-between; align-items: flex-start; margin-bottom: 12px; padding-bottom: 10px; ${headerBorder} }
  .company-info { flex: 1; }
  .company-name { font-size: 24px; font-weight: ${tmpl.headingWeight}; color: ${ac}; margin-bottom: 4px; }
  .company-details { color: #666; font-size: 10px; line-height: 1.6; }
  .company-details p { margin: 2px 0; }
  .document-type { text-align: right; }
  .document-title { font-size: 28px; font-weight: ${tmpl.headingWeight}; color: ${ac}; text-transform: uppercase; letter-spacing: 1px; line-height: 1.2; white-space: nowrap; }
  .document-subtitle { font-size: 12px; color: #666; margin-top: 4px; }
  .logo { max-width: 150px; max-height: 60px; object-fit: contain; margin-bottom: 12px; }
  .section { margin-bottom: 14px; }
  .section-title { font-size: 12px; font-weight: ${tmpl.headingWeight}; color: ${ac}; text-transform: uppercase; letter-spacing: 1px; border-bottom: ${tmpl.headerBorderWidth} solid ${ac}; padding-bottom: 4px; margin-bottom: 8px; }
  .info-section { display: flex; justify-content: space-between; margin-bottom: 10px; gap: 20px; }
  .info-block { flex: 1; }
  .info-label { font-size: 10px; text-transform: uppercase; letter-spacing: 1px; color: #888; margin-bottom: 4px; font-weight: 600; }
  .info-value { color: #1a1a1a; line-height: 1.5; font-size: 11px; }
  .note-block { ${getNoteStyle()} margin-bottom: 10px; font-size: 11px; color: #444; }
  table { width: 100%; border-collapse: collapse; font-size: 10px; margin-bottom: 10px; }
  th { background: ${tableHeaderBg}; color: ${tableHeaderColor}; padding: 6px 8px; text-align: left; ${tableHeaderBorder} font-size: 9px; text-transform: uppercase; font-weight: 600; letter-spacing: 0.5px; }
  ${getTableRowCss()}
  td { padding: 6px 8px; vertical-align: top; }
  table tr:last-child td { border-bottom: 2px solid ${ac}; }
  .risk-badge { padding: 2px 8px; border-radius: 10px; font-size: 9px; font-weight: 700; text-transform: uppercase; display: inline-block; }
  .ppe-grid { display: flex; flex-wrap: wrap; gap: 6px; }
  .ppe-item { background: ${ac}10; border: 1px solid ${ac}30; border-radius: 4px; padding: 4px 10px; font-size: 10px; color: ${ac}; font-weight: 500; }
  .sig-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 10px; }
  .sig-card { border: 1px solid #e2e8f0; border-radius: 6px; padding: 10px; }
  .sig-card img { max-width: 180px; max-height: 60px; }
  .sig-name { font-weight: 700; font-size: 12px; }
  .sig-meta { font-size: 9px; color: #666; margin-top: 2px; }
  .footer { margin-top: 20px; text-align: center; font-size: 9px; color: #999; border-top: 1px solid #eee; padding-top: 8px; }
  @page { size: A4; margin: 10mm; }
</style></head><body>
<div class="document">
  <div class="header">
    <div class="company-info">
      ${logoUrl ? `<img class="logo" src="${logoUrl}" alt="${escapeHtml(businessName)}" />` : ''}
      <div class="company-name">${escapeHtml(businessName)}</div>
      <div class="company-details">
        ${abn ? `<p>ABN: ${abn}</p>` : ''}
      </div>
    </div>
    <div class="document-type">
      <div class="document-title">SWMS</div>
      <div class="document-subtitle">Safe Work Method Statement</div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">General Information</div>
    <div class="info-section">
      <div class="info-block">
        <div class="info-label">Document Title</div>
        <div class="info-value">${doc.title}</div>
      </div>
      <div class="info-block">
        <div class="info-label">Status</div>
        <div class="info-value">${(doc.status || 'draft').toUpperCase()}</div>
      </div>
    </div>
    <div class="info-section">
      <div class="info-block">
        <div class="info-label">Site Address</div>
        <div class="info-value">${doc.siteAddress || 'Not specified'}</div>
      </div>
      <div class="info-block">
        <div class="info-label">Date Created</div>
        <div class="info-value">${doc.createdAt ? new Date(doc.createdAt).toLocaleDateString('en-AU') : '-'}</div>
      </div>
    </div>
    ${doc.description ? `<div class="note-block">${doc.description}</div>` : ''}
  </div>

  <div class="section">
    <div class="section-title">Work Activity Description</div>
    <div class="note-block">${doc.workActivityDescription || 'Not specified'}</div>
  </div>

  <div class="section">
    <div class="section-title">Hazard Identification & Risk Assessment</div>
    ${hazards.length > 0 ? `<table>
      <thead><tr>
        <th style="width:5%">#</th>
        <th style="width:18%">Activity / Task</th>
        <th style="width:18%">Hazard</th>
        <th style="width:8%">Likelihood</th>
        <th style="width:8%">Consequence</th>
        <th style="width:8%">Risk</th>
        <th style="width:22%">Control Measures</th>
        <th style="width:8%">Residual</th>
      </tr></thead>
      <tbody>${hazards.map((h, i) => `<tr>
        <td>${i + 1}</td>
        <td>${h.activityTask}</td>
        <td>${h.hazard}</td>
        <td>${h.likelihood.replace('_', ' ')}</td>
        <td>${h.consequence}</td>
        <td><span class="risk-badge" style="${riskColor(h.riskBefore)}">${h.riskBefore}</span></td>
        <td>${h.controlMeasures || '-'}</td>
        <td><span class="risk-badge" style="${riskColor(h.riskAfter)}">${h.riskAfter}</span></td>
      </tr>`).join('')}</tbody>
    </table>` : '<p>No hazards identified</p>'}
  </div>

  <div class="section">
    <div class="section-title">PPE Requirements</div>
    ${ppeList ? `<div class="ppe-grid">${(doc.ppeRequirements as string[] || []).map((p: string) => `<div class="ppe-item">${PPE_LABELS[p] || p}</div>`).join('')}</div>` : '<p>No PPE requirements specified</p>'}
  </div>

  <div class="section">
    <div class="section-title">Emergency Information</div>
    <div class="info-section">
      <div class="info-block">
        <div class="info-label">Emergency Contact</div>
        <div class="info-value">${doc.emergencyContact || 'Not specified'}</div>
      </div>
      <div class="info-block">
        <div class="info-label">First Aid Location</div>
        <div class="info-value">${doc.firstAidLocation || 'Not specified'}</div>
      </div>
    </div>
  </div>

  <div class="section">
    <div class="section-title">Worker Sign-off</div>
    <p style="font-size:10px;color:#555;margin-bottom:8px">I have read and understood this SWMS and agree to follow the safe work procedures described.</p>
    ${signatures.length > 0 ? `<div class="sig-grid">${signatures.map(s => `<div class="sig-card">
      <div class="sig-name">${s.workerName}</div>
      ${s.signatureData && s.signatureData.startsWith('data:') ? `<img src="${s.signatureData}" alt="Signature" />` : `<div style="font-style:italic;color:#666;font-size:10px;padding:8px 0">Signed electronically via mobile</div>`}
      <div class="sig-meta">Signed: ${s.signedAt ? new Date(s.signedAt).toLocaleString('en-AU') : '-'}</div>
      ${s.address ? `<div class="sig-meta">Location: ${s.address}</div>` : (s.latitude ? `<div class="sig-meta">GPS: ${s.latitude}, ${s.longitude}</div>` : '')}
    </div>`).join('')}</div>` : '<p>No signatures yet</p>'}
  </div>

  <div class="footer">
    <p>Generated by JobRunner &bull; ${new Date().toLocaleDateString('en-AU')}</p>
    <p>This SWMS must be reviewed when work conditions change or a new hazard is identified.</p>
  </div>
</div>
</body></html>`;

      if (req.query.format === 'html') {
        res.setHeader('Content-Type', 'text/html');
        return res.send(html);
      }
      const { generatePDFBuffer } = await import('./pdfService');
      const buffer = await generatePDFBuffer(html);
      res.setHeader('Content-Type', 'application/pdf');
      const disposition = req.query.inline === 'true' ? 'inline' : 'attachment'; res.setHeader('Content-Disposition', `${disposition}; filename="SWMS-${doc.title.replace(/[^a-zA-Z0-9]/g, '-')}.pdf"`);
      res.send(buffer);
    } catch (error: any) {
      console.error("Error generating SWMS PDF:", error);
      res.status(500).json({ error: error.message });
    }
  });

  const hazardScanUpload = multer({
    storage: multer.memoryStorage(),
    limits: { fileSize: 10 * 1024 * 1024 },
    fileFilter: imageOnlyFilter,
  });

  app.post("/api/swms/scan-hazards", requireAuth, visionPerUserLimiter, hazardScanUpload.array('photos', 10), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      const effectiveUserId = userContext.effectiveUserId;
      const { jobId, jobContext } = req.body;
      let imageBuffers: Buffer[] = [];

      if (req.files && req.files.length > 0) {
        imageBuffers = req.files.map((f: any) => f.buffer);
      } else if (jobId) {
        const photos = await storage.getJobPhotos(jobId, effectiveUserId);
        if (!photos || photos.length === 0) {
          return res.status(400).json({ error: "No photos found for this job." });
        }

        const { getSignedPhotoUrl } = await import('./photoService');
        const limitedPhotos = photos.slice(0, 5);
        for (const photo of limitedPhotos) {
          try {
            const { url } = await getSignedPhotoUrl(photo.objectStorageKey);
            if (url) {
              const photoResponse = await fetch(url);
              if (photoResponse.ok) {
                const arrayBuffer = await photoResponse.arrayBuffer();
                imageBuffers.push(Buffer.from(arrayBuffer));
              }
            }
          } catch (e) {
            console.warn(`[SWMS] Failed to fetch photo ${photo.id}:`, e);
          }
        }

        if (imageBuffers.length === 0) {
          return res.status(400).json({ error: "Could not retrieve any job photos for analysis." });
        }
      } else {
        return res.status(400).json({ error: "Provide either photos or a jobId to scan for hazards." });
      }

      const contextStr = jobContext || 'General construction work';
      const result = await detectHazards(imageBuffers, contextStr);
      res.json(result);
    } catch (error: any) {
      if (isBackpressure(error)) return send429(res, error);
      console.error("Hazard scan error:", error);
      res.status(500).json({ error: error.message || "Failed to scan for hazards" });
    }
  });

  app.get("/api/swms/risk-matrix", requireAuth, async (_req: any, res) => {
    res.json(RISK_MATRIX);
  });

  app.get("/api/team/:memberId/performance", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userId = req.userContext?.effectiveUserId || req.userId!;
      const { memberId } = req.params;

      const teamMembersList = await storage.getTeamMembers(userId);
      const member = teamMembersList.find((m: any) => m.id === memberId || m.memberId === memberId);
      if (!member) {
        return res.status(404).json({ error: "Team member not found" });
      }

      const workerUserId = member.memberId;
      if (!workerUserId) {
        return res.json({
          memberId: member.id,
          name: `${member.firstName || ''} ${member.lastName || ''}`.trim() || member.email,
          role: 'pending',
          jobsCompletedThisMonth: 0,
          jobsCompletedAllTime: 0,
          hoursWorkedThisMonth: 0,
          hoursWorkedAllTime: 0,
          onTimeRate: 0,
          averageJobDurationHours: 0,
          utilisationRate: 0,
          revenueGenerated: 0,
          currentStreak: 0,
        });
      }

      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

      const allJobs = await storage.getJobs(userId);
      const allTimeEntries = await storage.getTimeEntries(userId);
      const allInvoices = await storage.getInvoices(userId);

      const workerJobs = allJobs.filter((j: any) =>
        j.assignedTo === workerUserId || j.assignedTo === memberId
      );

      const completedJobs = workerJobs.filter((j: any) => j.status === 'done' || j.status === 'invoiced');
      const completedThisMonth = completedJobs.filter((j: any) => {
        const d = j.completedAt ? new Date(j.completedAt) : null;
        return d && d >= startOfMonth;
      });

      const workerTimeEntries = allTimeEntries.filter((te: any) => te.userId === workerUserId);
      const totalMinutesAllTime = workerTimeEntries
        .filter((te: any) => te.endTime && !te.isBreak)
        .reduce((sum: number, te: any) => sum + (te.duration || Math.round((new Date(te.endTime!).getTime() - new Date(te.startTime).getTime()) / 60000)), 0);
      const monthEntries = workerTimeEntries.filter((te: any) => new Date(te.startTime) >= startOfMonth && te.endTime && !te.isBreak);
      const totalMinutesThisMonth = monthEntries
        .reduce((sum: number, te: any) => sum + (te.duration || Math.round((new Date(te.endTime!).getTime() - new Date(te.startTime).getTime()) / 60000)), 0);

      let onTimeCount = 0;
      const jobsWithSchedule = completedJobs.filter((j: any) => j.scheduledAt && j.completedAt);
      for (const j of jobsWithSchedule) {
        const scheduled = new Date(j.scheduledAt!);
        const completed = new Date(j.completedAt!);
        const scheduledEnd = new Date(scheduled.getTime() + (j.estimatedDuration || 60) * 60000);
        if (completed <= new Date(scheduledEnd.getTime() + 24 * 60 * 60 * 1000)) {
          onTimeCount++;
        }
      }
      const onTimeRate = jobsWithSchedule.length > 0 ? Math.round((onTimeCount / jobsWithSchedule.length) * 100) : 0;

      const avgDurationHours = completedJobs.length > 0
        ? +(totalMinutesAllTime / 60 / completedJobs.length).toFixed(1)
        : 0;

      const workingDaysThisMonth = Math.max(1, Math.ceil((now.getTime() - startOfMonth.getTime()) / (1000 * 60 * 60 * 24)));
      const weekdaysThisMonth = Math.max(1, Math.round(workingDaysThisMonth * 5 / 7));
      const capacityMinutes = weekdaysThisMonth * 8 * 60;
      const utilisationRate = capacityMinutes > 0 ? Math.min(100, Math.round((totalMinutesThisMonth / capacityMinutes) * 100)) : 0;

      const workerJobIds = new Set(workerJobs.map((j: any) => j.id));
      const revenueGenerated = allInvoices
        .filter((inv: any) => inv.status === 'paid' && inv.jobId && workerJobIds.has(inv.jobId))
        .reduce((sum: number, inv: any) => sum + parseFloat(inv.total || '0'), 0);

      let currentStreak = 0;
      const sortedCompleted = [...jobsWithSchedule].sort((a: any, b: any) =>
        new Date(b.completedAt!).getTime() - new Date(a.completedAt!).getTime()
      );
      for (const j of sortedCompleted) {
        const scheduled = new Date(j.scheduledAt!);
        const completed = new Date(j.completedAt!);
        const scheduledEnd = new Date(scheduled.getTime() + (j.estimatedDuration || 60) * 60000);
        if (completed <= new Date(scheduledEnd.getTime() + 24 * 60 * 60 * 1000)) {
          currentStreak++;
        } else {
          break;
        }
      }

      const workerUser = await storage.getUser(workerUserId);

      res.json({
        memberId: member.id,
        userId: workerUserId,
        name: `${member.firstName || workerUser?.firstName || ''} ${member.lastName || workerUser?.lastName || ''}`.trim() || member.email,
        email: member.email,
        role: member.roleId,
        profileImageUrl: workerUser?.profileImageUrl,
        jobsCompletedThisMonth: completedThisMonth.length,
        jobsCompletedAllTime: completedJobs.length,
        hoursWorkedThisMonth: +(totalMinutesThisMonth / 60).toFixed(1),
        hoursWorkedAllTime: +(totalMinutesAllTime / 60).toFixed(1),
        onTimeRate,
        averageJobDurationHours: avgDurationHours,
        utilisationRate,
        revenueGenerated: +revenueGenerated.toFixed(2),
        currentStreak,
      });
    } catch (error) {
      console.error("Get worker performance error:", error);
      res.status(500).json({ error: "Failed to fetch worker performance" });
    }
  });

  app.get("/api/team/performance-summary", requireAuth, ownerOrManagerOnly(), async (req: any, res) => {
    try {
      const userId = req.userContext?.effectiveUserId || req.userId!;

      const teamMembersList = await storage.getTeamMembers(userId);
      const activeMembers = teamMembersList.filter((m: any) => m.isActive && m.inviteStatus === 'accepted' && m.memberId);

      if (activeMembers.length === 0) {
        return res.json({ workers: [], summary: { averageOnTimeRate: 0, totalHoursThisMonth: 0, busiestWorker: null, teamSize: 0 } });
      }

      const now = new Date();
      const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);

      const allJobs = await storage.getJobs(userId);
      const allTimeEntries = await storage.getTimeEntries(userId);
      const allInvoices = await storage.getInvoices(userId);

      const workers: any[] = [];
      let totalOnTimeRate = 0;
      let totalHoursThisMonth = 0;
      let busiestWorker: { name: string; hours: number } | null = null;

      for (const member of activeMembers) {
        const workerUserId = member.memberId!;

        const workerJobs = allJobs.filter((j: any) =>
          j.assignedTo === workerUserId || j.assignedTo === member.id
        );
        const completedJobs = workerJobs.filter((j: any) => j.status === 'done' || j.status === 'invoiced');
        const completedThisMonth = completedJobs.filter((j: any) => {
          const d = j.completedAt ? new Date(j.completedAt) : null;
          return d && d >= startOfMonth;
        });

        const workerTimeEntries = allTimeEntries.filter((te: any) => te.userId === workerUserId);
        const monthEntries = workerTimeEntries.filter((te: any) => new Date(te.startTime) >= startOfMonth && te.endTime && !te.isBreak);
        const totalMinutesThisMonth = monthEntries
          .reduce((sum: number, te: any) => sum + (te.duration || Math.round((new Date(te.endTime!).getTime() - new Date(te.startTime).getTime()) / 60000)), 0);
        const hoursThisMonth = +(totalMinutesThisMonth / 60).toFixed(1);

        let onTimeCount = 0;
        const jobsWithSchedule = completedJobs.filter((j: any) => j.scheduledAt && j.completedAt);
        for (const j of jobsWithSchedule) {
          const scheduled = new Date(j.scheduledAt!);
          const completed = new Date(j.completedAt!);
          const scheduledEnd = new Date(scheduled.getTime() + (j.estimatedDuration || 60) * 60000);
          if (completed <= new Date(scheduledEnd.getTime() + 24 * 60 * 60 * 1000)) {
            onTimeCount++;
          }
        }
        const onTimeRate = jobsWithSchedule.length > 0 ? Math.round((onTimeCount / jobsWithSchedule.length) * 100) : 0;

        const workingDaysThisMonth = Math.max(1, Math.ceil((now.getTime() - startOfMonth.getTime()) / (1000 * 60 * 60 * 24)));
        const weekdaysThisMonth = Math.max(1, Math.round(workingDaysThisMonth * 5 / 7));
        const capacityMinutes = weekdaysThisMonth * 8 * 60;
        const utilisationRate = capacityMinutes > 0 ? Math.min(100, Math.round((totalMinutesThisMonth / capacityMinutes) * 100)) : 0;

        const workerJobIds = new Set(workerJobs.map((j: any) => j.id));
        const revenueGenerated = allInvoices
          .filter((inv: any) => inv.status === 'paid' && inv.jobId && workerJobIds.has(inv.jobId))
          .reduce((sum: number, inv: any) => sum + parseFloat(inv.total || '0'), 0);

        const workerUser = await storage.getUser(workerUserId);
        const name = `${member.firstName || workerUser?.firstName || ''} ${member.lastName || workerUser?.lastName || ''}`.trim() || member.email;

        const last4Weeks: number[] = [];
        for (let w = 0; w < 4; w++) {
          const weekEnd = new Date(now.getTime() - w * 7 * 24 * 60 * 60 * 1000);
          const weekStart = new Date(weekEnd.getTime() - 7 * 24 * 60 * 60 * 1000);
          const weekMinutes = workerTimeEntries
            .filter((te: any) => te.endTime && !te.isBreak && new Date(te.startTime) >= weekStart && new Date(te.startTime) < weekEnd)
            .reduce((sum: number, te: any) => sum + (te.duration || Math.round((new Date(te.endTime!).getTime() - new Date(te.startTime).getTime()) / 60000)), 0);
          last4Weeks.unshift(+(weekMinutes / 60).toFixed(1));
        }

        workers.push({
          memberId: member.id,
          userId: workerUserId,
          name,
          email: member.email,
          role: member.roleId,
          profileImageUrl: workerUser?.profileImageUrl,
          jobsCompletedThisMonth: completedThisMonth.length,
          jobsCompletedAllTime: completedJobs.length,
          hoursWorkedThisMonth: hoursThisMonth,
          onTimeRate,
          utilisationRate,
          revenueGenerated: +revenueGenerated.toFixed(2),
          last4WeeksHours: last4Weeks,
        });

        totalOnTimeRate += onTimeRate;
        totalHoursThisMonth += hoursThisMonth;
        if (!busiestWorker || hoursThisMonth > busiestWorker.hours) {
          busiestWorker = { name, hours: hoursThisMonth };
        }
      }

      res.json({
        workers,
        summary: {
          averageOnTimeRate: workers.length > 0 ? Math.round(totalOnTimeRate / workers.length) : 0,
          totalHoursThisMonth: +totalHoursThisMonth.toFixed(1),
          busiestWorker,
          teamSize: workers.length,
        },
      });
    } catch (error) {
      console.error("Get team performance summary error:", error);
      res.status(500).json({ error: "Failed to fetch team performance summary" });
    }
  });

  // ============================================
  // WHS - Aggregate Summary (used by WhsHub overview/sidebar counts)
  // Returns all 7 lists the WHS hub needs in a single round-trip.
  // Each query is wrapped so a single failure doesn't 500 the whole page.
  // ============================================
  app.get("/api/whs/summary", requireAuth, createPermissionMiddleware(PERMISSIONS.READ_JOBS), async (req: any, res) => {
    try {
      const userId = req.userId!;
      const userContext = await getUserContext(userId);
      const swmsUserId = userContext.effectiveUserId;

      const safe = async <T>(fn: () => Promise<T>, fallback: T): Promise<T> => {
        try { return await fn(); } catch (e: any) {
          console.error('[WHS summary] sub-query failed:', e?.message || e);
          return fallback;
        }
      };

      const [incidents, emergencyInfo, jsaDocs, hazardReports, ppeChecklists, trainingRecords, swmsRaw] = await Promise.all([
        safe(() => storage.getIncidentReports(userId), [] as any[]),
        safe(() => storage.getSiteEmergencyInfo(userId), [] as any[]),
        safe(() => storage.getJsaDocuments(userId), [] as any[]),
        safe(() => storage.getHazardReports(userId), [] as any[]),
        safe(() => storage.getPpeChecklists(userId), [] as any[]),
        safe(() => storage.getTrainingRecords(userId), [] as any[]),
        safe(async () => {
          return await db.select().from(swmsDocuments)
            .where(eq(swmsDocuments.userId, swmsUserId))
            .orderBy(desc(swmsDocuments.createdAt));
        }, [] as any[]),
      ]);

      // Compute hazard counts for SWMS in a single grouped query (vs N+1).
      let swmsDocs: any[] = swmsRaw;
      if (swmsRaw.length > 0) {
        try {
          const swmsIds = swmsRaw.map((d: any) => d.id);
          const hazardCounts = await db
            .select({ swmsId: swmsHazards.swmsId, count: sql<number>`count(*)` })
            .from(swmsHazards)
            .where(inArray(swmsHazards.swmsId, swmsIds))
            .groupBy(swmsHazards.swmsId);
          const sigCounts = await db
            .select({ swmsId: swmsSignatures.swmsId, count: sql<number>`count(*)` })
            .from(swmsSignatures)
            .where(inArray(swmsSignatures.swmsId, swmsIds))
            .groupBy(swmsSignatures.swmsId);
          const hMap = new Map(hazardCounts.map(r => [r.swmsId, Number(r.count)]));
          const sMap = new Map(sigCounts.map(r => [r.swmsId, Number(r.count)]));
          swmsDocs = swmsRaw.map((d: any) => ({
            ...d,
            hazardCount: hMap.get(d.id) || 0,
            signatureCount: sMap.get(d.id) || 0,
          }));
        } catch (e: any) {
          console.error('[WHS summary] SWMS count enrichment failed:', e?.message || e);
          swmsDocs = swmsRaw.map((d: any) => ({ ...d, hazardCount: 0, signatureCount: 0 }));
        }
      }

      res.json({
        incidents,
        emergencyInfo,
        jsaDocs,
        hazardReports,
        ppeChecklists,
        trainingRecords,
        swmsDocs,
      });
    } catch (error: any) {
      console.error('Get WHS summary error:', error);
      res.status(500).json({ error: 'Failed to fetch WHS summary' });
    }
  });

