  app.post("/api/ai-receptionist/test-call", requireAuth, requirePaidTier(), requireOwnerSubscriptionActive(), requirePermission(PERMISSIONS.MANAGE_AI_RECEPTIONIST), async (req: any, res) => {
    try {
      const userId = req.effectiveUserId || req.userId || req.session?.userId;
      const lastCall = testCallRateLimit.get(userId);
      if (lastCall && Date.now() - lastCall < 60000) {
        return res.status(429).json({ error: 'Please wait at least 60 seconds between test calls' });
      }
      const config = await storage.getAiReceptionistConfig(userId);
      if (!config || !config.vapiAssistantId) {
        return res.status(400).json({ error: 'AI Receptionist not provisioned' });
      }
      const { phoneNumber } = req.body;
      if (!phoneNumber || !/^\+?\d{8,15}$/.test(phoneNumber.replace(/\s/g, ''))) {
        return res.status(400).json({ error: 'Valid phone number is required' });
      }
      testCallRateLimit.set(userId, Date.now());
      const { createOutboundCall } = await import('./vapiService');
      const call = await createOutboundCall(config.vapiAssistantId, phoneNumber);
      res.json({ success: true, callId: call.id });
    } catch (error: any) {
      console.error('[AI Receptionist] Test call error:', error.message);
      res.status(500).json({ error: 'Failed to initiate test call' });
    }
  });

  app.get("/api/ai-receptionist/analytics", requireAuth, requireOwnerSubscriptionActive(), requirePermission(PERMISSIONS.MANAGE_AI_RECEPTIONIST), async (req: any, res) => {
    try {
      const userId = req.effectiveUserId || req.userId || req.session?.userId;
      const phoneNumberId = req.query.phoneNumberId as string | undefined;
      const calls = await storage.getAiReceptionistCalls(userId, undefined, phoneNumberId);
      const totalCalls = calls.length;
      const completedCalls = calls.filter((c: any) => c.status === 'completed');
      const missedCalls = calls.filter((c: any) => c.outcome === 'missed' || c.status === 'missed');
      const transferredCalls = calls.filter((c: any) => c.outcome === 'transferred');
      const leadsCaptures = calls.filter((c: any) => c.outcome === 'message_taken' || c.leadId);
      const bookedCalls = calls.filter((c: any) => c.outcome === 'booked');
      const totalDuration = completedCalls.reduce((sum: number, c: any) => sum + (c.duration || 0), 0);
      const avgDuration = completedCalls.length > 0 ? Math.round(totalDuration / completedCalls.length) : 0;

      const intentBreakdown: Record<string, number> = {};
      for (const call of calls) {
        const intent = (call as any).callerIntent || 'unknown';
        intentBreakdown[intent] = (intentBreakdown[intent] || 0) + 1;
      }

      const outcomeBreakdown: Record<string, number> = {};
      for (const call of calls) {
        const outcome = (call as any).outcome || 'unknown';
        outcomeBreakdown[outcome] = (outcomeBreakdown[outcome] || 0) + 1;
      }

      const last7Days = new Date();
      last7Days.setDate(last7Days.getDate() - 7);
      const recentCalls = calls.filter((c: any) => new Date(c.createdAt) >= last7Days);

      const dailyVolume: Record<string, number> = {};
      for (const call of recentCalls) {
        const day = new Date((call as any).createdAt).toISOString().split('T')[0];
        dailyVolume[day] = (dailyVolume[day] || 0) + 1;
      }

      // Real measured latency: rolling avg over the last 20 completed calls
      // that have a per-call latency value persisted from the Vapi webhook.
      const latencyWindow = completedCalls
        .slice(0, 20)
        .map((c: any) => (typeof c.latencyMs === 'number' ? c.latencyMs : null))
        .filter((n: number | null): n is number => n !== null && n > 0);
      const avgMeasuredLatencyMs = latencyWindow.length > 0
        ? Math.round(latencyWindow.reduce((a: number, b: number) => a + b, 0) / latencyWindow.length)
        : null;
      // When a specific receptionist (phoneNumberId === aiReceptionistConfig.id)
      // is selected, compare measured latency against THAT config's estimate so
      // multi-number setups don't get a false mismatch from the default config.
      let config: any = undefined;
      if (phoneNumberId) {
        config = await storage.getAiReceptionistConfigById(phoneNumberId);
        if (config && config.userId !== userId) config = undefined;
      }
      if (!config) {
        config = await storage.getAiReceptionistConfig(userId);
      }
      const estimatedLatencyMs = config?.lastLatencyMs ?? null;
      const estimatedStatus = config?.latencyStatus ?? null;
      // Mismatch flag: estimate says fast but reality is well above the
      // amber ceiling — tells the user their last "Test Response Time"
      // result no longer matches what callers actually experience.
      const latencyMismatch = !!(
        avgMeasuredLatencyMs !== null &&
        latencyWindow.length >= 3 &&
        estimatedStatus === 'optimal' &&
        avgMeasuredLatencyMs > 1500
      );

      res.json({
        totalCalls,
        completedCalls: completedCalls.length,
        missedCalls: missedCalls.length,
        transferredCalls: transferredCalls.length,
        leadsCaptures: leadsCaptures.length,
        bookedCalls: bookedCalls.length,
        totalDuration,
        avgDuration,
        intentBreakdown,
        outcomeBreakdown,
        dailyVolume,
        recentCallCount: recentCalls.length,
        avgMeasuredLatencyMs,
        latencySampleSize: latencyWindow.length,
        estimatedLatencyMs,
        estimatedLatencyStatus: estimatedStatus,
        latencyMismatch,
      });
    } catch (error: any) {
      console.error('[AI Receptionist] Analytics error:', error.message);
      res.status(500).json({ error: 'Failed to fetch analytics' });
    }
  });

